class MarketChartView(QChartView):
    hoverKeyChanged = Signal(str)
    hoverTextChanged = Signal(str)
    staticAnnotationActivated = Signal(object)
    contextMenuRequested = Signal(object)

    def __init__(self, *args, **kwargs) -> None:
        super().__init__(*args, **kwargs)
        self._context: dict[str, object] = {}
        self._static_annotations: list[dict[str, object]] = []
        self._static_annotation_payloads: list[dict[str, object]] = []
        self._static_annotation_items: list[QGraphicsSimpleTextItem] = []
        self._crosshair_items_ready = False
        self._crosshair_v = QGraphicsLineItem()
        self._crosshair_h = QGraphicsLineItem()
        self._crosshair_label = QGraphicsSimpleTextItem()
        for item in (self._crosshair_v, self._crosshair_h):
            item.setPen(QPen(QColor("#5cbcff"), 1.0, Qt.DashLine))
            item.setZValue(50)
            item.hide()
        self._crosshair_label.setBrush(QColor("#eff6ff"))
        self._crosshair_label.setZValue(51)
        self._crosshair_label.hide()
        self._hover_summary_frame = QFrame(self.viewport())
        self._hover_summary_frame.setObjectName("marketChartHoverCard")
        self._hover_summary_frame.setAttribute(Qt.WA_TransparentForMouseEvents, True)
        self._hover_summary_frame.setStyleSheet(
            """
            QFrame#marketChartHoverCard {
                background: rgba(10, 16, 24, 0.90);
                border: 1px solid rgba(126, 215, 255, 0.26);
                border-radius: 14px;
            }
            QLabel#marketChartHoverCardTitle {
                color: #eff6ff;
                font-weight: 700;
                font-size: 13px;
            }
            QLabel#marketChartHoverCardBody {
                color: #b8c7d9;
                font-size: 12px;
            }
            QLabel#marketChartHoverCardFooter {
                color: #7ed7ff;
                font-size: 11px;
            }
            """
        )
        hover_layout = QVBoxLayout(self._hover_summary_frame)
        hover_layout.setContentsMargins(12, 10, 12, 10)
        hover_layout.setSpacing(4)
        self._hover_summary_title = QLabel("图表焦点")
        self._hover_summary_title.setObjectName("marketChartHoverCardTitle")
        self._hover_summary_title.setWordWrap(True)
        self._hover_summary_body = QLabel("移动鼠标到 K 线或副图，可固定看当前时点信息。")
        self._hover_summary_body.setObjectName("marketChartHoverCardBody")
        self._hover_summary_body.setWordWrap(True)
        self._hover_summary_footer = QLabel("PageUp/PageDown 翻页，Home 回最新")
        self._hover_summary_footer.setObjectName("marketChartHoverCardFooter")
        self._hover_summary_footer.setWordWrap(True)
        hover_layout.addWidget(self._hover_summary_title)
        hover_layout.addWidget(self._hover_summary_body)
        hover_layout.addWidget(self._hover_summary_footer)
        self._hover_summary_frame.hide()
        self._hover_summary_drag_active = False
        self._hover_summary_drag_offset = QPointF()
        self._hover_summary_manual_pos: tuple[float, float] | None = None
        self._current_hover_key = ""
        self.setMouseTracking(True)
        self.setRubberBand(QChartView.NoRubberBand)

    def setChart(self, chart: QChart) -> None:
        self._clear_static_annotations()
        super().setChart(chart)
        self._ensure_crosshair_items()
        self._reset_hover_summary_card()
        QTimer.singleShot(0, self._layout_static_annotations)

    def set_chart_context(self, **context: object) -> None:
        self._context = dict(context)
        self._static_annotations = [
            item for item in list(self._context.get("static_annotations", []) or []) if isinstance(item, dict)
        ]
        self._current_hover_key = ""
        self._refresh_static_annotations()
        self._reset_hover_summary_card()

    def resizeEvent(self, event) -> None:  # type: ignore[override]
        super().resizeEvent(event)
        QTimer.singleShot(0, self._layout_hover_summary_card)
        QTimer.singleShot(0, self._layout_static_annotations)

    def leaveEvent(self, event) -> None:
        if self._hover_summary_drag_active:
            self._hover_summary_drag_active = False
            self.viewport().setCursor(Qt.ArrowCursor)
        self._hide_crosshair(notify=True)
        super().leaveEvent(event)

    def mouseDoubleClickEvent(self, event: QMouseEvent) -> None:
        self._hide_crosshair(notify=False)
        super().mouseDoubleClickEvent(event)

    def mousePressEvent(self, event: QMouseEvent) -> None:
        if hasattr(event, "button") and event.button() == Qt.LeftButton:
            frame = getattr(self, "_hover_summary_frame", None)
            if isinstance(frame, QFrame) and frame.isVisible() and frame.geometry().contains(event.position().toPoint()):
                frame_top_left = frame.geometry().topLeft()
                self._hover_summary_drag_active = True
                self._hover_summary_drag_offset = event.position() - QPointF(float(frame_top_left.x()), float(frame_top_left.y()))
                self.viewport().setCursor(Qt.ClosedHandCursor)
                event.accept()
                return
            payload = self._static_annotation_payload_at_position(event.position())
            if isinstance(payload, dict) and payload.get("clickable"):
                self.staticAnnotationActivated.emit(dict(payload))
                event.accept()
                return
        super().mousePressEvent(event)

    def mouseMoveEvent(self, event: QMouseEvent) -> None:
        frame = getattr(self, "_hover_summary_frame", None)
        if self._hover_summary_drag_active and isinstance(frame, QFrame):
            width = frame.width()
            height = frame.height()
            target_x = float(event.position().x() - self._hover_summary_drag_offset.x())
            target_y = float(event.position().y() - self._hover_summary_drag_offset.y())
            max_x = max(8.0, float(self.viewport().width() - width - 8))
            max_y = max(8.0, float(self.viewport().height() - height - 8))
            clamped_x = max(8.0, min(target_x, max_x))
            clamped_y = max(8.0, min(target_y, max_y))
            self._hover_summary_manual_pos = (clamped_x, clamped_y)
            frame.move(int(clamped_x), int(clamped_y))
            frame.raise_()
            event.accept()
            return
        super().mouseMoveEvent(event)
        payload = self._static_annotation_payload_at_position(event.position())
        hovering_card = isinstance(frame, QFrame) and frame.isVisible() and frame.geometry().contains(event.position().toPoint())
        clickable = isinstance(payload, dict) and payload.get("clickable")
        if hovering_card:
            self.viewport().setCursor(Qt.OpenHandCursor)
        else:
            self.viewport().setCursor(Qt.PointingHandCursor if clickable else Qt.ArrowCursor)
        self._update_crosshair(event.position())

    def mouseReleaseEvent(self, event: QMouseEvent) -> None:
        if self._hover_summary_drag_active and hasattr(event, "button") and event.button() == Qt.LeftButton:
            self._hover_summary_drag_active = False
            self.viewport().setCursor(Qt.OpenHandCursor)
            event.accept()
            return
        super().mouseReleaseEvent(event)

    def contextMenuEvent(self, event) -> None:  # type: ignore[override]
        position = QPointF(event.pos()) if hasattr(event, "pos") else QPointF()
        if self.chart() is not None and self._plot_contains(position):
            self.contextMenuRequested.emit(
                {
                    "global_pos": self.mapToGlobal(event.pos()) if hasattr(event, "pos") else None,
                    "local_pos": position,
                }
            )
            event.accept()
            return
        super().contextMenuEvent(event)

    def wheelEvent(self, event: QWheelEvent) -> None:
        if self.chart() is not None and self._plot_contains(event.position()):
            event.accept()
            return
        super().wheelEvent(event)

    def _ensure_crosshair_items(self) -> None:
        scene = self.scene()
        if scene is None:
            return
        for item in (self._crosshair_v, self._crosshair_h, self._crosshair_label):
            if item.scene() is not scene:
                scene.addItem(item)
        self._crosshair_items_ready = True

    def _clear_static_annotations(self) -> None:
        for item in list(self._static_annotation_items):
            scene = item.scene()
            if scene is not None:
                scene.removeItem(item)
        self._static_annotation_payloads = []
        self._static_annotation_items = []

    def _refresh_static_annotations(self) -> None:
        self._clear_static_annotations()
        scene = self.scene()
        if scene is None or not self._static_annotations:
            return
        label_font = QFont()
        label_font.setPointSize(9)
        label_font.setBold(True)
        for payload in self._static_annotations[:24]:
            text = str(payload.get("text", "") or "").strip()
            if not text:
                continue
            item = QGraphicsSimpleTextItem(text)
            item.setFont(label_font)
            item.setBrush(ui_status_module.chart_annotation_tone_color(str(payload.get("tone", "") or "")))
            item.setZValue(54)
            scene.addItem(item)
            self._static_annotation_payloads.append(payload)
            self._static_annotation_items.append(item)
        QTimer.singleShot(0, self._layout_static_annotations)

    def _static_annotation_payload_at_position(self, position: QPointF) -> dict[str, object] | None:
        if not self._static_annotation_items:
            return None
        scene_point = self.mapToScene(position.toPoint())
        for item, payload in reversed(list(zip(self._static_annotation_items, self._static_annotation_payloads))):
            if not isinstance(payload, dict):
                continue
            try:
                bounds = item.sceneBoundingRect()
            except Exception:
                continue
            if bounds.contains(scene_point):
                return payload
        return None

    def _layout_static_annotations(self) -> None:
        chart = self.chart()
        if chart is None or not self._static_annotation_items:
            return
        plot_area = chart.plotArea()
        if plot_area.width() <= 0 or plot_area.height() <= 0:
            return
        plot_left = plot_area.left() + 4.0
        plot_top = plot_area.top() + 4.0
        plot_right = plot_area.right() - 4.0
        plot_bottom = plot_area.bottom() - 4.0

        def _clamp_rect(x_pos: float, y_pos: float, width: float, height: float) -> tuple[float, float]:
            clamped_x = max(plot_left, min(x_pos, plot_right - width))
            clamped_y = max(plot_top, min(y_pos, plot_bottom - height))
            return clamped_x, clamped_y

        def _intersects(rect: tuple[float, float, float, float], others: list[tuple[float, float, float, float]], gap: float = 4.0) -> bool:
            x_pos, y_pos, width, height = rect
            for other_x, other_y, other_width, other_height in others:
                if (
                    x_pos < other_x + other_width + gap
                    and x_pos + width + gap > other_x
                    and y_pos < other_y + other_height + gap
                    and y_pos + height + gap > other_y
                ):
                    return True
            return False

        positioned: list[tuple[QGraphicsSimpleTextItem, dict[str, object], float, float, float, float]] = []
        for item, payload in zip(self._static_annotation_items, self._static_annotation_payloads):
            try:
                x_value = float(payload.get("x", 0.0) or 0.0)
                y_value = float(payload.get("y", 0.0) or 0.0)
            except (TypeError, ValueError):
                item.hide()
                continue
            point = chart.mapToPosition(QPointF(x_value, y_value))
            rect = item.boundingRect()
            anchor = str(payload.get("anchor", "above") or "above")
            extra_dx = float(payload.get("dx", 0.0) or 0.0)
            extra_dy = float(payload.get("dy", 0.0) or 0.0)
            offset_x = 8.0
            offset_y = -rect.height() - 6.0
            if anchor == "below":
                offset_x = 8.0
                offset_y = 6.0
            elif anchor == "right":
                offset_x = 10.0
                offset_y = -(rect.height() / 2.0)
            elif anchor == "left":
                offset_x = -rect.width() - 10.0
                offset_y = -(rect.height() / 2.0)
            elif anchor == "center":
                offset_x = -(rect.width() / 2.0)
                offset_y = -(rect.height() / 2.0) - 6.0
            elif anchor == "top_right":
                x_pos, y_pos = _clamp_rect(plot_right - rect.width(), plot_top, rect.width(), rect.height())
                positioned.append((item, payload, x_pos, y_pos, rect.width(), rect.height()))
                continue
            x_pos, y_pos = _clamp_rect(point.x() + offset_x + extra_dx, point.y() + offset_y + extra_dy, rect.width(), rect.height())
            positioned.append((item, payload, x_pos, y_pos, rect.width(), rect.height()))

        placed_rects: list[tuple[float, float, float, float]] = []
        badge_labels = [row for row in positioned if str(row[1].get("anchor", "") or "") == "top_right"]
        for item, _payload, x_pos, y_pos, width, height in badge_labels:
            item.setPos(x_pos, y_pos)
            item.show()
            placed_rects.append((x_pos, y_pos, width, height))
        right_labels = sorted(
            [row for row in positioned if str(row[1].get("anchor", "") or "") == "right"],
            key=lambda row: row[3],
        )
        last_bottom = plot_area.top() + 4.0
        for item, _payload, x_pos, y_pos, _width, height in right_labels:
            if y_pos < last_bottom:
                y_pos = min(last_bottom + 2.0, plot_bottom - height)
            item.setPos(x_pos, y_pos)
            item.show()
            last_bottom = y_pos + height
            placed_rects.append((x_pos, y_pos, _width, height))

        floating_labels = sorted(
            [row for row in positioned if str(row[1].get("anchor", "") or "") not in {"right", "top_right"}],
            key=lambda row: (row[2], row[3]),
        )
        for item, payload, x_pos, y_pos, width, height in floating_labels:
            anchor = str(payload.get("anchor", "") or "")
            direction = 1.0 if anchor == "below" else -1.0
            step = max(height + 4.0, 14.0)
            candidate_x, candidate_y = x_pos, y_pos
            attempts = 0
            horizontal_toggle = 1.0
            while _intersects((candidate_x, candidate_y, width, height), placed_rects) and attempts < 18:
                attempts += 1
                candidate_y += direction * step
                if candidate_y < plot_top or candidate_y > plot_bottom - height:
                    direction *= -1.0
                    candidate_y = y_pos + direction * step * attempts
                if attempts in {6, 12}:
                    candidate_x += horizontal_toggle * min(18.0, width * 0.35)
                    horizontal_toggle *= -1.0
                candidate_x, candidate_y = _clamp_rect(candidate_x, candidate_y, width, height)
            item.setPos(candidate_x, candidate_y)
            item.show()
            placed_rects.append((candidate_x, candidate_y, width, height))

    def _plot_contains(self, position: QPointF) -> bool:
        chart = self.chart()
        if chart is None:
            return False
        return chart.plotArea().contains(position)

    def _hide_crosshair(self, *, notify: bool) -> None:
        for item in (self._crosshair_v, self._crosshair_h, self._crosshair_label):
            item.hide()
        QToolTip.hideText()
        self._reset_hover_summary_card()
        if notify:
            self.hoverTextChanged.emit("")
        if notify and self._current_hover_key:
            self._current_hover_key = ""
            self.hoverKeyChanged.emit("")

    def _update_crosshair(self, position: QPointF) -> None:
        chart = self.chart()
        if chart is None:
            self._hide_crosshair(notify=False)
            return
        self._ensure_crosshair_items()
        plot_area = chart.plotArea()
        if not plot_area.contains(position):
            self._hide_crosshair(notify=True)
            return
        hover_index = self._hover_index_from_position(position)
        if hover_index is None:
            self._hide_crosshair(notify=True)
            return
        self._apply_crosshair_for_index(hover_index, global_pos=position.toPoint(), notify=True)

    def sync_hover_key(self, key: str) -> None:
        if not key:
            self._hide_crosshair(notify=False)
            return
        hover_keys = list(self._context.get("hover_keys", []) or [])
        if not hover_keys:
            return
        try:
            index = hover_keys.index(key)
        except ValueError:
            return
        self._apply_crosshair_for_index(index, global_pos=None, notify=False)

    def _apply_crosshair_for_index(self, index: int, global_pos=None, *, notify: bool) -> None:
        chart = self.chart()
        if chart is None:
            self._hide_crosshair(notify=False)
            return
        plot_area = chart.plotArea()
        x_numeric = self._numeric_x_value_for_index(index)
        y_numeric = self._context_y_midpoint()
        point = chart.mapToPosition(QPointF(x_numeric, y_numeric))
        x = max(plot_area.left(), min(plot_area.right(), point.x()))
        y = max(plot_area.top(), min(plot_area.bottom(), point.y()))
        self._crosshair_v.setLine(x, plot_area.top(), x, plot_area.bottom())
        self._crosshair_h.setLine(plot_area.left(), y, plot_area.right(), y)
        self._crosshair_v.show()
        self._crosshair_h.show()

        tooltip = self._build_tooltip_text_for_index(index)
        if tooltip:
            inline_text = " | ".join(line.strip() for line in tooltip.splitlines()[:3] if line.strip())
            self._crosshair_label.setText(inline_text)
            label_pos = QPointF(min(x + 12, plot_area.right() - 280), max(plot_area.top() + 6, y - 22))
            self._crosshair_label.setPos(label_pos)
            self._crosshair_label.show()
            if global_pos is not None:
                QToolTip.showText(self.mapToGlobal(global_pos), tooltip, self)
        else:
            self._crosshair_label.hide()
        self._set_hover_summary_card_for_index(index)

        hover_key = self._hover_key_for_index(index)
        self._current_hover_key = hover_key
        if notify:
            self.hoverTextChanged.emit(tooltip)
        if notify and hover_key:
            self.hoverKeyChanged.emit(hover_key)

    def _hover_index_from_position(self, position: QPointF) -> int | None:
        chart = self.chart()
        if chart is None:
            return None
        try:
            value = chart.mapToValue(position)
        except Exception:
            return None
        x_kind = str(self._context.get("x_kind", "value"))
        hover_keys = list(self._context.get("hover_keys", []) or [])
        max_index = len(hover_keys) - 1
        if max_index < 0:
            payloads = list(self._context.get("hover_payloads", []) or [])
            max_index = len(payloads) - 1
        if max_index < 0:
            labels = list(self._context.get("x_labels", []) or [])
            max_index = len(labels) - 1
        if max_index < 0:
            return None
        if x_kind == "datetime":
            x_values = list(self._context.get("x_values", []) or [])
            if not x_values:
                return None
            return min(range(len(x_values)), key=lambda current: abs(x_values[current] - value.x()))
        if x_kind == "category":
            return max(0, min(int(round(value.x())), max_index))
        x_values = list(self._context.get("x_values", []) or [])
        if x_values:
            return min(range(len(x_values)), key=lambda current: abs(x_values[current] - value.x()))
        return max(0, min(int(round(value.x())), max_index))

    def _numeric_x_value_for_index(self, index: int) -> float:
        x_kind = str(self._context.get("x_kind", "value"))
        if x_kind == "datetime":
            x_values = list(self._context.get("x_values", []) or [])
            if x_values:
                clamped = max(0, min(index, len(x_values) - 1))
                return float(x_values[clamped])
        if x_kind == "category":
            return float(index)
        x_values = list(self._context.get("x_values", []) or [])
        if x_values:
            clamped = max(0, min(index, len(x_values) - 1))
            return float(x_values[clamped])
        return float(index)

    def _context_y_midpoint(self) -> float:
        chart = self.chart()
        if chart is None:
            return 0.0
        axes = chart.axes(Qt.Vertical)
        if not axes:
            return 0.0
        axis = axes[0]
        if hasattr(axis, "min") and hasattr(axis, "max"):
            return float(axis.min() + axis.max()) / 2.0
        return 0.0

    def _hover_key_for_index(self, index: int) -> str:
        hover_keys = list(self._context.get("hover_keys", []) or [])
        if hover_keys:
            clamped = max(0, min(index, len(hover_keys) - 1))
            return str(hover_keys[clamped])
        x_kind = str(self._context.get("x_kind", "value"))
        return self._format_x_value(self._numeric_x_value_for_index(index), x_kind)

    def _build_tooltip_text_for_index(self, index: int) -> str:
        payloads = list(self._context.get("hover_payloads", []) or [])
        if payloads:
            clamped = max(0, min(index, len(payloads) - 1))
            return self._format_payload_tooltip(payloads[clamped])
        x_label = str(self._context.get("x_label", "X"))
        y_label = str(self._context.get("y_label", "Y"))
        y_suffix = str(self._context.get("y_suffix", ""))
        x_kind = str(self._context.get("x_kind", "value"))
        value = self._numeric_x_value_for_index(index)
        y_values = list(self._context.get("y_values", []) or [])
        y_value = y_values[max(0, min(index, len(y_values) - 1))] if y_values else 0.0
        return f"{x_label}: {self._format_x_value(value, x_kind)}\n{y_label}: {float(y_value):,.2f}{y_suffix}"

    @staticmethod
    def _format_payload_tooltip(payload: object) -> str:
        if payload is None:
            return ""
        if isinstance(payload, str):
            return payload
        if isinstance(payload, dict):
            return "\n".join(f"{key}: {value}" for key, value in payload.items())
        if isinstance(payload, (list, tuple)):
            return "\n".join(str(item) for item in payload if str(item).strip())
        return str(payload)

    def _format_x_value(self, x_value: float, x_kind: str) -> str:
        if x_kind == "datetime":
            pattern = str(self._context.get("datetime_format", "MM-dd"))
            return QDateTime.fromMSecsSinceEpoch(int(x_value)).toString(pattern)
        if x_kind == "category":
            labels = list(self._context.get("x_labels", []) or [])
            if labels:
                index = max(0, min(int(round(x_value)), len(labels) - 1))
                return str(labels[index])
        return f"{x_value:.2f}"

    def _hover_summary_lines_for_index(self, index: int) -> list[str]:
        tooltip = self._build_tooltip_text_for_index(index)
        return [line.strip() for line in tooltip.splitlines() if line.strip()]

    def _layout_hover_summary_card(self) -> None:
        frame = getattr(self, "_hover_summary_frame", None)
        if not isinstance(frame, QFrame):
            return
        width = max(220, min(330, self.viewport().width() // 3))
        height = max(112, min(188, self.viewport().height() - 32))
        x_pos = max(8, self.viewport().width() - width - 12)
        y_pos = 12
        manual_pos = getattr(self, "_hover_summary_manual_pos", None)
        if manual_pos is not None:
            try:
                requested_x = float(manual_pos[0])
                requested_y = float(manual_pos[1])
            except (TypeError, ValueError, IndexError):
                requested_x, requested_y = x_pos, y_pos
            max_x = max(8.0, float(self.viewport().width() - width - 8))
            max_y = max(8.0, float(self.viewport().height() - height - 8))
            x_pos = int(max(8.0, min(requested_x, max_x)))
            y_pos = int(max(8.0, min(requested_y, max_y)))
            self._hover_summary_manual_pos = (float(x_pos), float(y_pos))
        frame.setGeometry(x_pos, y_pos, width, height)
        frame.raise_()

    def _set_hover_summary_card_content(self, lines: list[str]) -> None:
        frame = getattr(self, "_hover_summary_frame", None)
        title_label = getattr(self, "_hover_summary_title", None)
        body_label = getattr(self, "_hover_summary_body", None)
        footer_label = getattr(self, "_hover_summary_footer", None)
        if not isinstance(frame, QFrame) or not isinstance(title_label, QLabel) or not isinstance(body_label, QLabel) or not isinstance(footer_label, QLabel):
            return
        cleaned = [line for line in lines if str(line).strip()]
        if not cleaned:
            title_label.setText("图表焦点")
            body_label.setText("移动鼠标到 K 线或副图，可固定看当前时点信息。")
            footer_label.setText("PageUp/PageDown 翻页，Home 回最新")
        else:
            title_label.setText(cleaned[0])
            middle_lines = cleaned[1:5]
            footer_lines = cleaned[5:7]
            body_label.setText("\n".join(middle_lines) if middle_lines else "当前时点暂无更多明细。")
            footer_label.setText(" | ".join(footer_lines) if footer_lines else "PageUp/PageDown 翻页，Home 回最新")
        self._layout_hover_summary_card()
        frame.show()

    def _set_hover_summary_card_for_index(self, index: int) -> None:
        lines = self._hover_summary_lines_for_index(index)
        self._set_hover_summary_card_content(lines)

    def _reset_hover_summary_card(self) -> None:
        hover_keys = list(self._context.get("hover_keys", []) or [])
        if hover_keys:
            self._set_hover_summary_card_for_index(len(hover_keys) - 1)
            return
        payloads = list(self._context.get("hover_payloads", []) or [])
        if payloads:
            self._set_hover_summary_card_for_index(len(payloads) - 1)
            return
        self._set_hover_summary_card_content([])


class _FocusBannerClickFilter(QObject):
    def __init__(self, owner) -> None:
        super().__init__(owner if isinstance(owner, QObject) else None)
        self._owner = owner

    def eventFilter(self, watched, event) -> bool:
        if event.type() == QEvent.MouseButtonRelease and isinstance(watched, QLabel):
            banner_name = watched.property("focusBannerName")
            if banner_name and hasattr(self._owner, "_on_focus_banner_clicked_v41"):
                if hasattr(event, "button") and event.button() == Qt.RightButton and hasattr(self._owner, "_open_focus_banner_menu_v42"):
                    global_pos = event.globalPosition().toPoint() if hasattr(event, "globalPosition") else watched.mapToGlobal(watched.rect().center())
                    self._owner._open_focus_banner_menu_v42(str(banner_name), watched, global_pos)
                else:
                    self._owner._on_focus_banner_clicked_v41(str(banner_name), watched)
                return True
        return super().eventFilter(watched, event)


class _ShellChipClickFilter(QObject):
    def __init__(self, owner) -> None:
        super().__init__(owner if isinstance(owner, QObject) else None)
        self._owner = owner

    def eventFilter(self, watched, event) -> bool:
        chip_name = watched.property("shellChipName") if isinstance(watched, QWidget) else ""
        if event.type() == QEvent.Enter and chip_name in {"shell_focus_chip", "shell_focus_hover_card"}:
            if hasattr(self._owner, "_show_shell_focus_hover_card_v49"):
                self._owner._show_shell_focus_hover_card_v49()
            return False
        if event.type() == QEvent.Leave and chip_name in {"shell_focus_chip", "shell_focus_hover_card"}:
            if hasattr(self._owner, "_schedule_hide_shell_focus_hover_card_v49"):
                self._owner._schedule_hide_shell_focus_hover_card_v49()
            return False
        if event.type() == QEvent.MouseButtonRelease and isinstance(watched, QFrame):
            if chip_name and hasattr(self._owner, "_on_shell_chip_clicked_v47"):
                self._owner._on_shell_chip_clicked_v47(str(chip_name))
                return True
        return super().eventFilter(watched, event)


