    def _finish_startup_bootstrap(self) -> None:
        if not _qh_window_ready_for_ui_v1(self):
            return
        self._set_startup_progress(42, "正在加载观察池与运行状态...")
        self._schedule_startup_loading_compact()
        self._schedule_startup_loading_hide()
        self._refresh_watchlist()
        self._refresh_broker_status()
        self._restore_news_source_snapshot()
        if self.state.universe_dir and Path(self.state.universe_dir).exists():
            self._set_startup_progress(56, "正在后台扫描本地股票数据...")
            _qh_schedule_window_callback_v1(
                self,
                80,
                lambda: self._scan_universe(Path(self.state.universe_dir), quiet=True, async_mode=True),
            )
        else:
            self._startup_scan_loaded = True
        _qh_schedule_window_callback_v1(
            self,
            20,
            lambda: self.refresh_remote_market(quiet=True, update_chart=True, async_mode=True),
        )

    def _restore_news_source_snapshot(self) -> None:
        provider_key = str(getattr(self, "news_source_provider_key", "") or "").strip().lower()
        if not provider_key:
            return
        try:
            self._load_news_source(provider_key, refresh_after_load=False)
        except Exception:
            return

