    def _refresh_detail_history_summary_v1(self) -> None:
        cards = getattr(self, "detail_history_summary_cards", None)
        if not isinstance(cards, dict) or not cards:
            return

        def _set_card_copy(key: str, *, headline: str, detail: str, meta: str, button_text: str | None = None) -> None:
            copy_helper = getattr(self, "_set_capability_card_copy_v1", None)
            if callable(copy_helper):
                copy_helper(cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)
                return
            QuantHunterWindow._set_capability_card_copy_v1(self, cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)

        history_rows = list(getattr(self, "strategy_history_rows", []) or [])
        compare_rows = self._strategy_history_selected_compare_rows() if hasattr(self, "_strategy_history_selected_compare_rows") else list(getattr(self, "strategy_history_compare_rows", []) or [])
        trade_rows = self._strategy_history_selected_trades() if hasattr(self, "_strategy_history_selected_trades") else list(getattr(self, "strategy_history_trade_rows", []) or [])
        selected_name = self._selected_strategy_history_name() if hasattr(self, "_selected_strategy_history_name") else ""
        selected_summary = self._strategy_history_selected_summary() if hasattr(self, "_strategy_history_selected_summary") else None
        selected_trade = self._selected_strategy_history_trade_snapshot() if hasattr(self, "_selected_strategy_history_trade_snapshot") else None

        if selected_summary is not None:
            strategy_detail = (
                f"收益 {float(getattr(selected_summary, 'total_return', 0.0) or 0.0):.2%} | "
                f"胜率 {float(getattr(selected_summary, 'win_rate', 0.0) or 0.0):.2%} | "
                f"回撤 {float(getattr(selected_summary, 'max_drawdown', 0.0) or 0.0):.2%}"
            )
            strategy_meta = (
                f"信号 {int(getattr(selected_summary, 'signal_count', 0) or 0)} | "
                f"成交 {int(getattr(selected_summary, 'trade_count', 0) or 0)} | "
                "下一步：先看统计表再进参数对比"
            )
        elif history_rows:
            strategy_detail = f"已载入 {len(history_rows)} 组 | 当前 {selected_name or '未锁定战法'}"
            strategy_meta = "下一步：先从统计表锁定一套战法，再看参数对比和逐笔样本"
        else:
            strategy_detail = "等待运行历史战法统计"
            strategy_meta = "下一步：先运行回测，再看参数对比与逐笔样本"
        _set_card_copy(
            "strategy",
            headline=f"当前战法：{selected_name or '待选择'}",
            detail=strategy_detail,
            meta=strategy_meta,
            button_text="看统计",
        )

        if compare_rows:
            best_row = max(compare_rows, key=lambda item: float(item.get("total_return", 0.0) or 0.0))
            worst_row = min(compare_rows, key=lambda item: float(item.get("total_return", 0.0) or 0.0))
            compare_detail = (
                f"最佳 {best_row.get('scenario_label', '--')} {float(best_row.get('total_return', 0.0) or 0.0):.2%} | "
                f"最差 {worst_row.get('scenario_label', '--')} {float(worst_row.get('total_return', 0.0) or 0.0):.2%}"
            )
            compare_meta = f"当前 {len(compare_rows)} 条场景 | 下一步：先看收益差，再决定是否继续调参数"
        else:
            compare_detail = "等待生成参数对比"
            compare_meta = "下一步：先运行战法参数对比，再看最佳/最差场景差距"
        _set_card_copy(
            "compare",
            headline=f"参数对比：{len(compare_rows)} 条",
            detail=compare_detail,
            meta=compare_meta,
            button_text="看对比",
        )

        if selected_trade is not None:
            trade_detail = (
                f"焦点 {selected_trade.get('stock_name', '--')} | "
                f"{selected_trade.get('entry_date', '--')} -> {selected_trade.get('exit_date', '--')}"
            )
            trade_meta = f"退出 {selected_trade.get('exit_reason', '--')} | 下一步：先看逐笔样本，再回统计表核对纪律"
        elif trade_rows:
            first = trade_rows[0]
            trade_detail = (
                f"最新 {first.get('stock_name', '--')} | "
                f"{first.get('entry_date', '--')} -> {first.get('exit_date', '--')}"
            )
            trade_meta = f"逐笔 {len(trade_rows)} 条 | 下一步：点一条样本回看退出原因和持有天数"
        else:
            trade_detail = "等待生成逐笔样本"
            trade_meta = "下一步：先运行历史战法回测，再看逐笔样本和退出原因"
        _set_card_copy(
            "trade",
            headline=f"逐笔样本：{len(trade_rows)} 条",
            detail=trade_detail,
            meta=trade_meta,
            button_text="看逐笔",
        )

    def _refresh_detail_capability_overview_v1(self) -> None:
        cards = getattr(self, "detail_capability_cards", None)
        if not isinstance(cards, dict) or not cards:
            return

        def _set_card_copy(key: str, *, headline: str, detail: str, meta: str, button_text: str | None = None) -> None:
            copy_helper = getattr(self, "_set_capability_card_copy_v1", None)
            if callable(copy_helper):
                copy_helper(cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)
                return
            QuantHunterWindow._set_capability_card_copy_v1(self, cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)

        symbol = str(getattr(self, "active_symbol", "") or "").strip()
        stock_name = self._stock_name_for_symbol(symbol) if symbol else "等待联动"
        stock_id = self._stock_id_for_symbol(symbol) if symbol else "--"
        recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == symbol), None) if symbol else None
        latest_signal = next((item for item in reversed(getattr(self, "analyses", [])) if getattr(item, "label", "") != "NONE"), None) if symbol else None
        selected_signal = self._selected_detail_signal_snapshot() if hasattr(self, "_selected_detail_signal_snapshot") else None
        selected_trade = self._selected_detail_trade_snapshot() if hasattr(self, "_selected_detail_trade_snapshot") else None
        selected_history_name = self._selected_strategy_history_name() if hasattr(self, "_selected_strategy_history_name") else ""
        selected_history_trade = self._selected_strategy_history_trade_snapshot() if hasattr(self, "_selected_strategy_history_trade_snapshot") else None
        signal_count = int(self.signal_table.rowCount()) if hasattr(self, "signal_table") else 0
        trade_count = int(self.trades_table.rowCount()) if hasattr(self, "trades_table") else 0
        history_count = len(list(getattr(self, "strategy_history_rows", []) or []))
        compare_count = len(list(getattr(self, "strategy_history_compare_rows", []) or []))
        selected_history_trade_count = len(self._strategy_history_selected_trades()) if hasattr(self, "_strategy_history_selected_trades") else 0
        action_text = self._display_action(getattr(recommendation, "action", "WATCH")) if recommendation is not None else "等待联动"
        next_focus = str(getattr(recommendation, "next_focus", "") or "").strip() if recommendation is not None else ""

        _set_card_copy(
            "overview",
            headline=f"当前单票：{stock_name} ({stock_id} / {symbol or '--'})",
            detail=(
                f"当前动作 {action_text} | 主战法 {_recommendation_strategy_name(recommendation, default='待同步')}"
                if recommendation is not None
                else "等待机会池、信号或交易链路同步当前单票"
            ),
            meta=f"入口：单票结论 / 执行偏差 / 复盘结论 | 下一步：{next_focus or '先确定单票结论再看回放'}",
            button_text="看结论",
        )

        timeline_focus = ""
        if selected_signal is not None:
            timeline_focus = f"焦点信号：{selected_signal['date']} | {selected_signal['label']}"
        elif selected_trade is not None:
            timeline_focus = f"焦点成交：{selected_trade['entry_date']} -> {selected_trade['exit_date']}"
        elif latest_signal is not None:
            timeline_focus = f"最近信号：{getattr(latest_signal, 'date', '--')} | {self._display_label(getattr(latest_signal, 'label', 'NONE'))}"
        else:
            timeline_focus = "等待信号或成交记录载入"
        _set_card_copy(
            "timeline",
            headline=f"信号 {signal_count} 条 | 成交 {trade_count} 条",
            detail=timeline_focus,
            meta="入口：信号时间线 / 成交轨迹 | 下一步：点一条记录回看触发原因和执行质量",
            button_text="看回放",
        )

        history_focus_parts: list[str] = []
        if selected_history_name:
            history_focus_parts.append(f"当前战法：{selected_history_name}")
        if selected_history_trade is not None:
            history_focus_parts.append(f"焦点逐笔：{selected_history_trade['stock_name']}")
        if not history_focus_parts:
            history_focus_parts.append("等待运行历史战法统计")
        _set_card_copy(
            "history",
            headline=f"历史战法：{history_count} 组",
            detail=f"{' | '.join(history_focus_parts)} | 参数对比 {compare_count} 条 | 逐笔 {selected_history_trade_count} 条",
            meta="入口：统计 / 参数对比 / 逐笔表现 | 下一步：先看选中战法的收益和退出原因",
            button_text="看历史",
        )

