    def _open_scanner_watch_summary_v1(self, summary_key: str) -> None:
        route_map = {
            "watch": ("watchlist_widget", None),
            "summary": ("summary_table", "summary_table"),
            "monitor": ("monitor_table", "monitor_table"),
        }
        target, select_row = route_map.get(str(summary_key or "").strip(), ("watchlist_widget", None))
        self._navigate_to_workspace("scanner", target, select_row)

    def _open_scanner_monitor_summary_v1(self, summary_key: str) -> None:
        target_key = str(summary_key or "").strip()
        if target_key == "overview":
            symbol = self._selected_symbol_from_monitor_table() if hasattr(self, "_selected_symbol_from_monitor_table") else ""
            symbol = symbol or (self._selected_symbol_from_watchlist() if hasattr(self, "_selected_symbol_from_watchlist") else "") or str(getattr(self, "active_symbol", "") or "")
            if symbol and symbol in getattr(self, "universe_bars", {}):
                self.select_symbol(symbol)
            self._navigate_to_workspace("overview", "market_pool_table")
            return
        if target_key == "recommend":
            symbol = self._selected_symbol_from_monitor_table() if hasattr(self, "_selected_symbol_from_monitor_table") else ""
            symbol = symbol or (self._selected_symbol_from_watchlist() if hasattr(self, "_selected_symbol_from_watchlist") else "") or str(getattr(self, "active_symbol", "") or "")
            if symbol and hasattr(self, "_focus_symbol_in_recommend_workspace"):
                self._focus_symbol_in_recommend_workspace(symbol)
            else:
                self._navigate_to_workspace("recommend", "daily_pool_table", "daily_pool_table")
            return
        if target_key == "execution":
            symbol = self._selected_symbol_from_monitor_table() if hasattr(self, "_selected_symbol_from_monitor_table") else ""
            symbol = symbol or (self._selected_symbol_from_watchlist() if hasattr(self, "_selected_symbol_from_watchlist") else "") or str(getattr(self, "active_symbol", "") or "")
            if symbol and hasattr(self, "_focus_symbol_in_broker_workspace"):
                self._focus_symbol_in_broker_workspace(symbol)
            else:
                self._navigate_to_workspace("broker", "orders_table", "orders_table")
            return
        self._navigate_to_workspace("scanner", "monitor_table", "monitor_table")

    def _refresh_scanner_watch_summary_v1(self) -> None:
        cards = getattr(self, "scanner_watch_summary_cards", None)
        if not isinstance(cards, dict) or not cards:
            return

        def _set_card_copy(key: str, *, headline: str, detail: str, meta: str, button_text: str | None = None) -> None:
            copy_helper = getattr(self, "_set_capability_card_copy_v1", None)
            if callable(copy_helper):
                copy_helper(cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)
                return
            QuantHunterWindow._set_capability_card_copy_v1(self, cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)

        watch_count = self.watchlist_widget.count() if hasattr(self, "watchlist_widget") else 0
        summary_rows = list(getattr(self, "backtest_summaries", []) or [])
        summary_count = len(summary_rows)
        monitor_count = self.monitor_table.rowCount() if hasattr(self, "monitor_table") else 0
