        summary_symbol = self._selected_symbol_from_summary_table() if hasattr(self, "_selected_symbol_from_summary_table") else ""
        monitor_symbol = ""
        if hasattr(self, "monitor_table") and hasattr(self.monitor_table, "currentRow"):
            row = self.monitor_table.currentRow()
            if row >= 0:
                item = self.monitor_table.item(row, 2)
                monitor_symbol = item.text() if item else ""
        active_symbol = str(getattr(self, "active_symbol", "") or "")

        watch_focus = watch_symbol or active_symbol
        watch_focus_name = self._stock_name_for_symbol(watch_focus) if watch_focus else "等待观察焦点"
        _set_card_copy(
            "watch",
            headline=f"观察池：{watch_count} 只",
            detail=f"焦点 {watch_focus_name}" if watch_focus else "等待观察池同步",
            meta="入口：观察池 | 下一步：先确认是否继续跟踪，再决定是否补回测或进入监控",
            button_text="看观察",
        )

        summary_focus_symbol = summary_symbol or active_symbol or (str(getattr(summary_rows[0], "symbol", "") or "") if summary_rows else "")
        summary_focus = next((item for item in summary_rows if getattr(item, "symbol", "") == summary_focus_symbol), None)
        if summary_focus is not None:
            summary_focus_name = self._stock_name_for_symbol(getattr(summary_focus, "symbol", ""))
            summary_detail = f"焦点 {summary_focus_name} | 交易 {int(getattr(summary_focus, 'trades', 0) or 0)} 笔 | 收益 {float(getattr(summary_focus, 'total_return', 0.0) or 0.0):.2%}"
            summary_meta = f"入口：回测摘要 | 胜率 {float(getattr(summary_focus, 'win_rate', 0.0) or 0.0):.2%} | 下一步：先核对样本表现，再决定是否切入盘中监控"
        elif summary_focus_symbol:
            summary_focus_name = self._stock_name_for_symbol(summary_focus_symbol)
            summary_detail = f"焦点 {summary_focus_name} | 等待回测样本回填"
            summary_meta = "入口：回测摘要 | 下一步：先回填样本，再决定是否继续留在观察池"
        else:
            summary_detail = "等待回测摘要生成"
            summary_meta = "入口：回测摘要 | 下一步：先形成样本，再决定是否进入盘中监控"
        _set_card_copy(
            "summary",
            headline=f"回测摘要：{summary_count} 条",
            detail=summary_detail,
            meta=summary_meta,
            button_text="看回测",
        )

        monitor_focus = monitor_symbol or active_symbol
        monitor_focus_name = self._stock_name_for_symbol(monitor_focus) if monitor_focus else "等待监控焦点"
        _set_card_copy(
            "monitor",
            headline=f"盘中联动：{monitor_count} 条",
            detail=f"焦点 {monitor_focus_name}" if monitor_focus else "等待盘中监控同步",
            meta="入口：盘中监控 | 下一步：先核对动作和跳转，再决定是否联动机会池或打板",
            button_text="看监控",
        )

