    def _refresh_overview_capability_overview_v1(self) -> None:
        cards = getattr(self, "overview_capability_cards", None)
        if not isinstance(cards, dict) or not cards:
            return

        def _set_card_copy(key: str, *, headline: str, detail: str, meta: str, button_text: str | None = None) -> None:
            copy_helper = getattr(self, "_set_capability_card_copy_v1", None)
            if callable(copy_helper):
                copy_helper(cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)
                return
            QuantHunterWindow._set_capability_card_copy_v1(self, cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)

        market_count = self.market_pool_table.rowCount() if hasattr(self, "market_pool_table") else len(list(getattr(self, "daily_pool_rows", []) or []))
        rows = list(getattr(self, "daily_pool_rows", []) or [])
        top_row = rows[0] if rows else None
        active_symbol = str(getattr(self, "active_symbol", "") or getattr(top_row, "symbol", "") or "")
        active_name = self._stock_name_for_symbol(active_symbol) if active_symbol else (getattr(top_row, "stock_name", "") or "等待市场快照")
        active_id = self._stock_id_for_symbol(active_symbol) if active_symbol else (getattr(top_row, "stock_id", "") or "--")
        top_theme = (
            str(getattr(top_row, "mainline_tag", "") or getattr(top_row, "theme_name", "") or getattr(top_row, "strategy_tag", "") or "等待主线")
            if top_row is not None
            else "等待主线"
        )
        buy_count = sum(1 for row in rows if str(getattr(row, "action", "") or "").upper() == "BUY")
        news_total = sum(len(items) for items in getattr(self, "news_catalysts", {}).values())
        news_focus_items = list(getattr(self, "news_catalysts", {}).get(active_symbol, []) or []) if active_symbol else []
        if not news_focus_items:
            for items in getattr(self, "news_catalysts", {}).values():
                if items:
                    news_focus_items = list(items)
                    break
        news_item = news_focus_items[0] if news_focus_items else None
        news_title = str(getattr(news_item, "title", "") or "").strip() if news_item is not None else ""
        action_text = self._display_action(getattr(top_row, "action", "WATCH")) if top_row is not None else "观察"

        _set_card_copy(
            "market",
            headline=f"市场判断：{market_count} 只",
            detail=(
                f"焦点 {active_name} ({active_id} / {active_symbol})"
                if active_symbol
                else "等待市场快照与主图联动"
            ),
            meta="入口：市场总览 / 主图 / 机会池 | 下一步：先定结构、温度和交易区间",
            button_text="看总览",
        )
        _set_card_copy(
            "leaders",
            headline=f"主线龙头：{top_theme}",
            detail=(
                f"焦点 {getattr(top_row, 'stock_name', active_name) or active_name} | 可做 {buy_count} 只"
                if top_row is not None
                else "等待主线与前排同步"
            ),
            meta="入口：主线龙头 / 机会池 | 下一步：先看前排、承接和板块扩散",
            button_text="看龙头",
        )
        _set_card_copy(
            "news",
            headline=f"消息催化：{news_total} 条",
            detail=(f"最新 {news_title}" if news_title else "等待消息源和催化同步"),
            meta="入口：消息催化 / 来源状态 | 下一步：先核对来源，再看题材扩散",
            button_text="看消息",
        )
        _set_card_copy(
            "decision",
            headline=(f"买卖决策：{buy_count} 只可做" if rows else "买卖决策：等待联动"),
            detail=(
                f"焦点 {getattr(top_row, 'stock_name', active_name) or active_name} | 动作 {action_text}"
                if top_row is not None
                else "等待机会池与计划联动"
            ),
            meta="入口：买卖决策 / 机会池 / 交易链路 | 下一步：先看计划，再决定是否进执行中控",
            button_text="看决策",
        )

    def _open_auth_capability_v1(self, capability_key: str) -> None:
        target_key = str(capability_key or "").strip()
        if target_key == "next":
            self._navigate_to_workspace("recommend", "daily_pool_table", "daily_pool_table")
            return
        route_map = {
            "channel": "auth_form_box",
            "credential": "login_status_text",
            "bridge": "login_status_text",
        }
        target = route_map.get(target_key, "auth_form_box")
        self._navigate_to_workspace("auth", target)

    def _refresh_auth_capability_overview_v1(self) -> None:
        cards = getattr(self, "auth_capability_cards", None)
        if not isinstance(cards, dict) or not cards:
            return

        def _set_card_copy(key: str, *, headline: str, detail: str, meta: str, button_text: str | None = None) -> None:
            self._set_capability_card_copy_v1(cards, key, headline=headline, detail=detail, meta=meta, button_text=button_text)

        profile = None
        if hasattr(self, "current_broker_profile") and hasattr(self, "mode_combo"):
            try:
                profile = self.current_broker_profile()
            except Exception:
                profile = None
        if profile is None:
            profile = getattr(self.state, "broker_profile", None)
        channel_text = self.auth_channel_combo.currentText() if hasattr(self, "auth_channel_combo") else "东方财富"
        mode_text = self._display_mode(getattr(profile, "mode", "")) if profile is not None and hasattr(self, "_display_mode") else (getattr(profile, "mode", "") if profile is not None else "")
        username = str(getattr(profile, "username", "") or "").strip() if profile is not None else ""
        account_id = str(getattr(profile, "account_id", "") or "").strip() if profile is not None else ""
        strategy_id = str(getattr(profile, "strategy_id", "") or "").strip() if profile is not None else ""
        token_ready = bool(str(getattr(profile, "token", "") or "").strip()) if profile is not None else False
        bridge_python = str(getattr(profile, "sdk_python_path", "") or "").strip() if profile is not None else ""
        sdk_module = str(getattr(profile, "sdk_module", "") or "").strip() if profile is not None else ""
        missing_fields: list[str] = []
        if not username:
            missing_fields.append("账号")
        if not account_id:
            missing_fields.append("账户 ID")
        if not strategy_id:
            missing_fields.append("策略 ID")
        if not token_ready:
            missing_fields.append("SDK Token")
        if channel_text in {"GM", "自定义"} and not bridge_python:
            missing_fields.append("Bridge Python")

        _set_card_copy(
            "channel",
            headline=f"接入通道：{channel_text}",
            detail=f"模式 {mode_text or '未填写'} | 账户 {getattr(profile, 'account_name', '') or '未填写'}",
            meta="入口：接入表单 / 账号 / 策略 ID | 下一步：先核对通道、账号和模式",
            button_text="看通道",
        )
        _set_card_copy(
            "credential",
            headline=("凭据校验：参数已齐" if not missing_fields else f"凭据校验：待补 {len(missing_fields)} 项"),
            detail=("缺口 " + " / ".join(missing_fields[:3]) if missing_fields else "账号、账户 ID、策略 ID 与 Token 已齐"),
            meta="入口：凭据完整度 / 校验状态 | 下一步：补齐后执行接入校验",
            button_text="看校验",
        )
        bridge_ready = bool(bridge_python) if channel_text in {"GM", "自定义"} else True
        _set_card_copy(
            "bridge",
            headline=("Bridge 环境：已就绪" if bridge_ready else "Bridge 环境：待补"),
            detail=(f"{sdk_module or '未填写'} | {bridge_python or '等待 Bridge Python'}"),
            meta="入口：SDK 模块 / Bridge Python / 运行环境 | 下一步：先确认桥接解释器和模块",
            button_text="看桥接",
        )
        _set_card_copy(
            "next",
            headline=("后续入口：可联动机会池" if not missing_fields else "后续入口：先补参数"),
            detail=("完成校验后继续进入机会池与交易链路" if not missing_fields else "补齐凭据、Bridge 和策略 ID 后再联动机会池"),
            meta="入口：机会池 / 交易链路 | 下一步：接入通过后继续看机会池",
            button_text="看机会",
        )

    def _refresh_license_status_view(self) -> None:
        if not hasattr(self, "license_status_text"):
            return
        started = self.state.trial_started_at or datetime.now().date().isoformat()
        try:
            start_date = datetime.strptime(started, "%Y-%m-%d").date()
        except ValueError:
            start_date = datetime.now().date()
        days_used = max((datetime.now().date() - start_date).days, 0)
        trial_days = 14
        remaining = max(trial_days - days_used, 0)
        capabilities = self._license_capabilities()
        plan = str(capabilities.get("plan", self.state.license_plan or "TRIAL")).upper()
        plan_label = {
            "TRIAL": "试用版",
            "PRO": "专业版",
            "ENTERPRISE": "企业版",
        }.get(plan, plan)
        risk_profile_key = getattr(self.state, "strategy_risk_profile", "standard")
        risk_profile_label = RISK_PROFILE_LABELS.get(risk_profile_key, risk_profile_key)
        risk_profile_hint = risk_profile_brief(risk_profile_key)
        lines = [
            "授权与状态",
            f"- 当前方案：{plan_label} ({plan})",
            f"- 试用开始：{start_date.isoformat()}",
            f"- 试用剩余：{remaining} 天",
            f"- 版本能力：自动盘前报告 {'开启' if capabilities.get('auto_daily_plan_export') else '关闭'}，盘前候选上限 {int(capabilities.get('daily_plan_export_limit', 0))} 只",
            f"- 风险档位：{risk_profile_label} ({risk_profile_key})",
            f"- 档位说明：{risk_profile_hint}",
            f"- 关注题材：{', '.join(self.state.focus_themes) if self.state.focus_themes else '未设置'}",
            f"- 主线题材阈值：前 {self.state.strategy_top_theme_limit}",
            f"- 题材加权：{float(capabilities.get('focus_theme_boost', 0.0)):.0f}",
            f"- 盘前模板：{self.state.daily_plan_template}",
            f"- 模板仅关注题材：{'是' if self.state.daily_plan_focus_only else '否'}",
            f"- 盘前股票池上限：{min(self.state.daily_plan_candidate_limit, int(capabilities.get('daily_plan_export_limit', self.state.daily_plan_candidate_limit)))}",
            f"- 市场历史回看深度：{int(capabilities.get('market_history_limit', 0))}",
            f"- 监控摘要容量：{int(capabilities.get('monitor_summary_limit', 0))}",
            f"- 自动盘前报告：{'开启' if self.state.auto_daily_plan_export and bool(capabilities.get('auto_daily_plan_export')) else '关闭'}",
            "",
            "说明",
        ]
        if plan == "ENTERPRISE":
            lines.append("- 企业版已启用：自动盘前报告、增强题材加权和扩展题材面板。")
        elif plan == "PRO":
            lines.append("- 专业版已启用：自动盘前报告和题材优先加权已开放。")
        else:
            lines.append("- 试用版保留手动研究流程，自动盘前报告保持关闭。")
        lines.append("- 切换版本、保存配置或刷新市场后，状态会自动同步。")
        self._set_plain_text_if_changed(self.license_status_text, "\n".join(lines))

