    def _set_theme_combo_value(self, theme_key: str) -> None:
        theme_key = _normalize_terminal_theme_key(theme_key)
        for index in range(self.theme_combo.count()):
            if self.theme_combo.itemData(index) == theme_key:
                self.theme_combo.setCurrentIndex(index)
                return
        self.theme_combo.setCurrentIndex(0)

    def _set_density_combo_value(self, density_key: str) -> None:
        density_key = normalize_terminal_density(density_key)
        for index in range(self.density_combo.count()):
            if self.density_combo.itemData(index) == density_key:
                self.density_combo.setCurrentIndex(index)
                return
        self.density_combo.setCurrentIndex(0)

    def _terminal_density_profile(self) -> dict[str, object]:
        width = int(self.width() or self.minimumWidth() or TERMINAL_LAYOUT_BREAKPOINTS["width"]["standard"])
        height = int(self.height() or self.minimumHeight() or TERMINAL_LAYOUT_BREAKPOINTS["height"]["tall"])
        return terminal_density_profile(self.current_density, width=width, height=height)

    def _sync_terminal_density_ui(self) -> None:
        profile = self._terminal_density_profile()
        density_mode = str(profile.get("mode", self.current_density))
        density_hint_text = str(profile.get("hint", terminal_density_hint(density_mode)))
        density_label_text = str(profile.get("label", terminal_density_label(density_mode)))

        widgets = [
            self.centralWidget() if isinstance(self.centralWidget(), QWidget) else None,
            getattr(self, "shell_header", None),
            getattr(self, "shell_pulse_bar", None),
            getattr(self, "tabs", None),
            getattr(self, "theme_combo", None),
            getattr(self, "density_combo", None),
        ]
        widgets.extend(
            getattr(self, chip_name, {}).get("frame")
            for chip_name in (
                "shell_workspace_chip",
                "shell_focus_chip",
                "shell_market_chip",
                "shell_pipeline_chip",
                "shell_refresh_chip",
                "shell_runtime_chip",
            )
            if isinstance(getattr(self, chip_name, None), dict)
        )
        for widget in widgets:
            if not isinstance(widget, QWidget):
                continue
            if widget.property("terminalDensity") != density_mode:
                widget.setProperty("terminalDensity", density_mode)
                style = widget.style()
                if style is not None:
                    style.unpolish(widget)
                    style.polish(widget)
                widget.update()

        if hasattr(self, "density_title_label"):
            self.density_title_label.setToolTip(density_hint_text)
        if hasattr(self, "density_combo"):
            self.density_combo.setToolTip(density_hint_text)
        if hasattr(self, "top_badge"):
            self.top_badge.setToolTip(f"{density_label_text}密度：{density_hint_text}")

    def change_density(self, *_args: object) -> None:
        density_key = normalize_terminal_density(str(self.density_combo.currentData() or DEFAULT_TERMINAL_DENSITY))
        self.current_density = density_key
        self.state.ui_density = density_key
        self._sync_terminal_density_ui()
        if hasattr(self, "_apply_layout_polish_v19"):
            self._apply_layout_polish_v19()
        self._refresh_shell_header()
        self.save_state()

    def change_theme(self, *_args: object) -> None:
        theme_key = _normalize_terminal_theme_key(str(self.theme_combo.currentData() or DEFAULT_TERMINAL_THEME))
        self.current_theme = theme_key
        app = QApplication.instance()
        if app is not None:
            app.setPalette(_build_terminal_palette(theme_key))
        self._apply_theme(theme_key)
        self._sync_terminal_density_ui()
        self.save_state()



    def export_end_of_day_review_from_ui(self, show_dialog: bool = True):
        if not self.scan_rows and not self.daily_pool_rows:
            if show_dialog:
                QMessageBox.information(self, "提示", "请先完成股票池扫描。")
            return None

        trade_plan = QuantHunterWindow._current_trade_plan_cached(self)
        board_plan = QuantHunterWindow._current_board_plan_cached(self, top_n=5)
        output_dir = self._review_output_dir()
        artifacts = export_end_of_day_review(
            output_dir=output_dir,
            recommendations=self.daily_pool_rows,
            trade_plan=trade_plan,
            board_plan=board_plan,
            holdings=self.holdings,
            cash_snapshot=self.cash_snapshot,
            scan_rows=self.scan_rows,
            focus_themes=self.state.focus_themes,
            license_plan=self.state.license_plan,
            submission_records=self.order_submission_records,
            order_intents=self.order_intents,
            order_log=self.order_submission_log,
        )

        export_lines = [
            "收盘复盘日报已导出：",
            f"Markdown：{artifacts.markdown_path}",
            f"CSV：{artifacts.csv_path}",
            f"JSON：{artifacts.json_path}",
        ]
        if hasattr(self, "board_monitor_text"):
            existing = self.board_monitor_text.toPlainText().strip()
            merged = "\n".join([existing, "", *export_lines]) if existing else "\n".join(export_lines)
            self._set_plain_text_if_changed(self.board_monitor_text, merged)
        _qh_apply_status_text_to_widgets_v1(
            self,
            ["board_status_banner"],
            _qh_review_export_status_text_v1(
                action="end_of_day",
                artifacts=artifacts,
                scan_count=len(list(self.scan_rows or [])),
                pool_count=len(list(self.daily_pool_rows or [])),
            ),
        )
        if show_dialog:
            QMessageBox.information(self, "导出完成", "\n".join(export_lines))
        return artifacts

