    def _scan_universe_payload(
        self,
        folder: Path,
        params: StrategyParams,
    ) -> tuple[list[ScanRow], dict[str, list[PriceBar]], dict[str, list[DailyAnalysis]], dict[str, Path], list[SymbolBacktestSummary], list[str]]:
        scanner = UniverseScanner(params)
        rows, bars_by_symbol, analyses_by_symbol, paths_by_symbol = scanner.scan_folder(folder)
        summaries = scanner.summarize_backtests(bars_by_symbol, analyses_by_symbol)
        return rows, bars_by_symbol, analyses_by_symbol, paths_by_symbol, summaries, list(getattr(scanner, "last_scan_warnings", []) or [])

    def _scan_universe(self, folder: Path, quiet: bool = False, async_mode: bool = True) -> None:
        target_folder = Path(folder)
        if not target_folder.exists():
            self._handle_scan_error(f"股票目录不存在：{target_folder}", quiet)
            return
        try:
            params = self.current_strategy_params() if hasattr(self, "current_strategy_params") else StrategyParams()
        except Exception as exc:
            self._handle_scan_error(str(exc), quiet)
            return
        if async_mode:
            if hasattr(self, "scan_summary_label"):
                self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：正在后台刷新股票池、观察池与盘中监控焦点...")
            started = self._run_background_job(
                "scan_universe",
                lambda: self._scan_universe_payload(target_folder, params),
                lambda payload: self._apply_scan_universe_result(target_folder, payload),
                lambda message: self._handle_scan_error(message, quiet),
            )
            if not started and hasattr(self, "scan_summary_label"):
                self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：上一轮扫描仍在执行，本轮自动刷新已跳过。")
            self._refresh_shell_header()
            return
        try:
            payload = self._scan_universe_payload(target_folder, params)
        except Exception as exc:
            self._handle_scan_error(str(exc), quiet)
            return
        self._force_sync_daily_pool_after_scan_v81 = True
        try:
            self._apply_scan_universe_result(target_folder, payload)
        finally:
            self._force_sync_daily_pool_after_scan_v81 = False






    def _refresh_market_theme_options(self) -> None:
        if not hasattr(self, "market_theme_combo"):
            return
        themes = ["全部"] + sorted({(getattr(row, "theme_name", "") or row.strategy_tag) for row in getattr(self.market_screen_result, "algorithmic_pool", []) if (getattr(row, "theme_name", "") or row.strategy_tag)})
        current = self.market_theme_filter if self.market_theme_filter in themes else "全部"
        theme_signature = (tuple(themes), current)
        if getattr(self, "_market_theme_option_signature_v1", None) == theme_signature:
            self.market_theme_filter = current
            return
        self.market_theme_combo.blockSignals(True)
        self.market_theme_combo.clear()
        for theme in themes:
            self.market_theme_combo.addItem(theme)
        self.market_theme_combo.setCurrentText(current)
        self.market_theme_combo.blockSignals(False)
        self.market_theme_filter = current
        self._market_theme_option_signature_v1 = theme_signature
        if hasattr(self, "_refresh_market_search_completer_v1"):
            self._refresh_market_search_completer_v1()

    def _market_search_query_text(self) -> str:
        if hasattr(self, "market_search_input"):
            return str(self.market_search_input.text() or "").strip()
        return ""

    def _market_price_plan_brief_v1(self, recommendation) -> str:
        if recommendation is None:
            return "价位待同步"
        entry_price = float(getattr(recommendation, "entry_price", 0.0) or getattr(recommendation, "close", 0.0) or 0.0)
        stop_price = float(getattr(recommendation, "stop_price", 0.0) or 0.0)
        target_price = float(getattr(recommendation, "target_price", 0.0) or 0.0)
        parts: list[str] = []
        if entry_price > 0:
            parts.append(f"买 {entry_price:.2f}")
        if stop_price > 0:
            parts.append(f"损 {stop_price:.2f}")
        if target_price > 0:
            parts.append(f"目 {target_price:.2f}")
        return " / ".join(parts) if parts else "价位待同步"

    def _market_search_suggestion_entries_v1(self, limit: int = 160) -> list[str]:
        suggestions: list[str] = []
        seen: set[str] = set()

        def add(*values: object) -> bool:
            for raw in values:
                text = str(raw or "").strip()
                if not text:
                    continue
                key = text.lower()
                if key in seen:
                    continue
                seen.add(key)
                suggestions.append(text)
                if len(suggestions) >= max(int(limit or 0), 1):
                    return True
            return False

        for row in list(getattr(getattr(self, "market_screen_result", None), "algorithmic_pool", []) or []):
            if add(
                getattr(row, "stock_name", ""),
                getattr(row, "stock_id", "") or extract_stock_id(getattr(row, "symbol", "") or ""),
                getattr(row, "symbol", ""),
                getattr(row, "theme_name", "") or getattr(row, "strategy_tag", ""),
                getattr(row, "strategy_tag", ""),
            ):
                return suggestions[:limit]
        for row in list(getattr(self, "daily_pool_rows", []) or []):
            if add(
                getattr(row, "stock_name", ""),
                getattr(row, "stock_id", "") or extract_stock_id(getattr(row, "symbol", "") or ""),
                getattr(row, "symbol", ""),
                getattr(row, "mainline_tag", "") or getattr(row, "theme_name", ""),
                _recommendation_strategy_name(row, default=getattr(row, "primary_strategy", "") or getattr(row, "theme_name", "")),
            ):
                return suggestions[:limit]
        for symbol, snapshot in list((getattr(self, "market_snapshots", {}) or {}).items())[: max(int(limit or 0), 1)]:
            if add(
                getattr(snapshot, "stock_name", ""),
                getattr(snapshot, "stock_id", "") or extract_stock_id(symbol),
                symbol,
                getattr(snapshot, "strategy_tag", ""),
                getattr(snapshot, "fund_model", ""),
            ):
                return suggestions[:limit]
        for symbol in list(getattr(self, "universe_bars", {}).keys())[: max(int(limit or 0), 1)]:
            if add(
                self._stock_name_for_symbol(symbol) if hasattr(self, "_stock_name_for_symbol") else "",
                self._stock_id_for_symbol(symbol) if hasattr(self, "_stock_id_for_symbol") else extract_stock_id(symbol),
                symbol,
            ):
                return suggestions[:limit]
        for theme in list({str(item).strip() for item in list(getattr(self, "theme_aliases", {}).keys()) if str(item).strip()}):
            if add(theme):
                return suggestions[:limit]
        for strategy_name in STRATEGY_FILTER_LABELS:
            if strategy_name != "全部" and add(strategy_name):
                return suggestions[:limit]
        return suggestions[:limit]

    def _on_market_search_completion_selected_v1(self, text: str) -> None:
        selected = str(text or "").strip()
        if not selected:
            return
        if hasattr(self, "market_search_input"):
            self.market_search_input.setText(selected)
        self.search_market_symbol()

    def _refresh_market_search_completer_v1(self) -> None:
        if not hasattr(self, "market_search_input"):
            return
        suggestions = self._market_search_suggestion_entries_v1()
        signature = tuple(suggestions)
        if getattr(self, "_market_search_completer_signature_v1", None) == signature:
            return
        completer = QCompleter(suggestions, self.market_search_input)
        completer.setCaseSensitivity(Qt.CaseInsensitive)
        completer.setCompletionMode(QCompleter.PopupCompletion)
        try:
            completer.setFilterMode(Qt.MatchContains)
        except Exception:
            pass
        completer.setMaxVisibleItems(10)
        completer.activated.connect(self._on_market_search_completion_selected_v1)
        self.market_search_input.setCompleter(completer)
        self._market_search_completer_v1 = completer
        self._market_search_completer_signature_v1 = signature

