    def _handle_market_refresh_error(self, message: str, quiet: bool) -> None:
        handle_market_refresh_error(self, message, quiet, show_error_dialog_fn=QMessageBox.critical)
        self._refresh_shell_header()
        self._startup_market_loaded = True
        if getattr(self, "_startup_scan_loaded", False):
            self._finish_startup_loading("启动完成，可继续离线浏览")
        else:
            self._set_startup_progress(86, "远程行情未返回，已切到本地资源模式")

    def _apply_market_screen_result(
        self,
        result: MarketScreenResult,
        update_chart: bool = False,
        feed_state: dict[str, str] | None = None,
    ) -> None:
        preserved_search_payloads = self._captured_manual_market_search_payloads_v1() if hasattr(self, "_captured_manual_market_search_payloads_v1") else []
        preserved_focus_symbol = str(getattr(self, "_manual_market_focus_symbol_v1", "") or "").strip()
        self._symbol_data_revision += 1
        self._startup_market_loaded = True
        self._set_startup_progress(92, "行情候选已返回，正在刷新图表与工作台...")
        apply_market_screen_result(
            self,
            result,
            update_chart=update_chart,
            feed_state=feed_state,
            cache_cls=LocalMarketCache,
            extract_stock_id_fn=extract_stock_id,
            stock_profile_cls=StockProfile,
            project_root=PROJECT_ROOT,
        )
        for payload in preserved_search_payloads:
            try:
                self._apply_market_search_loaded_payload_v1(payload)
            except Exception:
                continue
        if preserved_focus_symbol and preserved_focus_symbol in getattr(self, "universe_bars", {}):
            self.select_symbol(preserved_focus_symbol, origin="search")
            self._set_market_search_status_v1(
                self._market_search_action_text_v1(
                    symbol=preserved_focus_symbol,
                    stock_name=self._stock_name_for_symbol(preserved_focus_symbol),
                    route="local",
                )
            )
        self._refresh_shell_header()
        if getattr(self, "_startup_scan_loaded", False):
            self._finish_startup_loading("行情与资源加载完成，可以开始使用")
        else:
            self._set_startup_progress(96, "行情已加载，正在等待本地资源整理完成...")

