    def _workspace_tabs(self) -> dict[str, QWidget]:
        return {
            "overview": self.overview_tab,
            "auth": self.auth_tab,
            "recommend": self.recommend_tab,
            "broker": self.broker_tab,
            "paper": self.paper_tab,
            "scanner": self.scanner_tab,
            "board": self.board_tab,
            "detail": self.detail_tab,
            "config": self.config_tab,
        }

    def _workspace_name_for_index(self, index: int) -> str:
        if 0 <= index < len(WORKSPACE_TAB_ORDER):
            return WORKSPACE_LABEL_BY_KEY.get(WORKSPACE_TAB_ORDER[index], "工作区")
        return "工作区"

    def _activate_workspace_stage_for_widget(self, workspace_key: str, widget_name: str | None = None) -> None:
        target = str(widget_name or "").strip()
        if not target:
            return
        stage_mappings = {
            "recommend": (
                ("recommend_workflow_tabs", {
                    0: {"recommend_empty_box", "recommend_controls_section", "recommend_pool_box", "daily_pool_table"},
                    1: {"recommend_dispatch_splitter", "recommend_dispatch_text", "recommend_focus_review_text", "recommend_queue_text", "recommend_ai_review_text"},
                    2: {
                        "recommend_deep_summary_box",
                        "recommend_summary_splitter",
                        "recommend_stage_container",
                        "theme_heat_table",
                        "leader_table",
                        "trade_plan_table",
                        "position_advice_table",
                        "recommend_message_center_table",
                        "recommend_message_center_box",
                        "strategy_pack_box",
                        "strategy_detail_box",
                        "strategy_detail_text",
                        "strategy_path_box",
                        "summary_cards_box",
                    },
                }),
            ),
            "broker": (
                ("broker_stage_tabs", {
                    0: {"broker_cockpit_section", "broker_summary_box", "broker_metrics_box", "broker_execution_box", "broker_capability_box"},
                    1: {"broker_workbench_splitter", "broker_middle_splitter", "orders_table", "broker_order_focus_text", "holdings_table"},
                    2: {"broker_posttrade_section", "execution_table", "order_result_text", "broker_recap_text"},
                    3: {"broker_setup_drawer", "broker_control_splitter", "broker_status_box", "broker_status_text"},
                }),
            ),
            "scanner": (
                ("scanner_stage_tabs", {
                    0: {"scanner_capability_box", "scan_table"},
                    1: {"scanner_watch_summary_box", "watchlist_widget", "summary_table"},
                    2: {"scanner_monitor_summary_box", "monitor_table", "monitor_summary_text"},
                }),
            ),
            "paper": (
                ("paper_stage_tabs", {
                    0: {"paper_trading_box", "paper_trading_status_label", "paper_equity_chart_view", "paper_trading_text", "paper_capability_box"},
                    1: {"paper_positions_table", "paper_ledger_table", "paper_trading_splitter"},
                    2: {"paper_strategy_table", "paper_patrol_table", "paper_analytics_splitter", "paper_experiment_text"},
                }),
            ),
            "board": (
                ("board_stage_tabs", {
                    0: {"board_capability_box", "board_table", "board_text"},
                    1: {"board_monitor_table", "board_monitor_text"},
                }),
            ),
            "detail": (
                ("detail_stage_tabs", {
                    0: {
                        "detail_summary_box",
                        "detail_recap_splitter",
                        "detail_metrics_box",
                        "metrics_text",
                        "detail_decision_text",
                        "detail_execution_text",
                        "detail_conclusion_text",
                        "detail_capability_box",
                    },
                    1: {"signal_table", "trades_table"},
                    2: {
                        "strategy_history_table",
                        "strategy_history_compare_table",
                        "strategy_history_trade_table",
                        "strategy_history_rank_table",
                        "strategy_history_leaderboard_table",
                    },
                }),
            ),
            "config": (
                ("config_stage_tabs", {
                    0: {"configStrategyBox", "configLicenseBox", "configRiskSnapshotBox"},
                    1: {"configStrategyCatalogBox", "configStrategyListBox", "configStrategyEditorBox"},
                    2: {"configNewsSourceBox", "configAiReviewBox"},
                    3: {"configNotesBox"},
                }),
            ),
        }
        for tab_attr, tab_map in stage_mappings.get(workspace_key, ()):
            tab_widget = getattr(self, tab_attr, None)
            if not isinstance(tab_widget, QTabWidget):
                continue
            for index, names in tab_map.items():
                if target in names and index < tab_widget.count():
                    if tab_widget.currentIndex() != index:
                        tab_widget.setCurrentIndex(index)
                    return

    def _select_first_row(self, widget_name: str | None) -> None:
        if not widget_name:
            return
        widget = getattr(self, widget_name, None)
        if widget is not None and hasattr(widget, "rowCount") and widget.rowCount() > 0:
            selector = getattr(self, "_select_table_row_if_needed", None)
            if callable(selector):
                selector(widget, 0)
            elif hasattr(widget, "selectRow"):
                widget.selectRow(0)

    def _navigate_to_workspace(self, workspace_key: str, widget_name: str | None = None, select_row: str | None = None) -> None:
        if hasattr(self, "tabs"):
            target_tab = self._workspace_tabs().get(workspace_key)
            if target_tab is not None:
                self.tabs.setCurrentWidget(target_tab)
        self._activate_workspace_stage_for_widget(workspace_key, widget_name or select_row)
        self._focus_widget_later(getattr(self, widget_name, None) if widget_name else None)
        self._select_first_row(select_row)

    def _on_workspace_tab_changed(self, index: int) -> None:
        current_name = self._workspace_name_for_index(index)
        if hasattr(self, "top_badge"):
            self.top_badge.setText(f"量化猎手 Pro v2.2 · {current_name}")
        self._refresh_shell_header()
        if hasattr(self, "market_status_label") and getattr(self, "tabs", None) and self.tabs.currentWidget() is self.overview_tab:
            status_text = self.market_status_label.text()
            view_part = ""
            if " | 视图：" in status_text:
                status_text, view_part = status_text.split(" | 视图：", 1)
            page_part = f" | 页面：{current_name}"
            if view_part:
                page_part += f" | 视图：{view_part}"
            self.market_status_label.setText(f"{status_text.split(' | 页面：', 1)[0]}{page_part}")

    def _focus_widget_later(self, widget: QWidget | None) -> None:
        if widget is None:
            return
        def _focus_and_reveal() -> None:
            widget.setFocus()
            parent = widget.parentWidget()
            while parent is not None:
                if isinstance(parent, QScrollArea):
                    content = parent.widget()
                    if isinstance(content, QWidget):
                        local_pos = widget.mapTo(content, QPointF(0, 0).toPoint())
                        margin = 18
                        parent.ensureVisible(
                            max(local_pos.x() - margin, 0),
                            max(local_pos.y() - margin, 0),
                            xmargin=margin,
                            ymargin=margin,
                        )
                    break
                parent = parent.parentWidget()
        QTimer.singleShot(0, _focus_and_reveal)

    def _on_workspace_tab_changed(self, index: int) -> None:
        current_name = self._workspace_name_for_index(index)
        if hasattr(self, "_refresh_startup_loading_visibility_for_workspace"):
            self._refresh_startup_loading_visibility_for_workspace()
        self._refresh_shell_header()
        if hasattr(self, "market_status_label") and getattr(self, "tabs", None) and self.tabs.currentWidget() is self.overview_tab:
            status_text = self.market_status_label.text()
            view_part = ""
            if " | 视图：" in status_text:
                status_text, view_part = status_text.split(" | 视图：", 1)
            page_part = f" | 页面：{current_name}"
            if view_part:
                page_part += f" | 视图：{view_part}"
            self._set_label_text_if_changed(self.market_status_label, f"{status_text.split(' | 页面：', 1)[0]}{page_part}")
        self._qh_skip_shell_header_in_status_refresh_v1 = True
        self._refresh_workspace_status_labels()
        if hasattr(self, "_sync_chart_action_note_card_visibility_v1"):
            self._sync_chart_action_note_card_visibility_v1(restart_timer=False)
        if hasattr(self, "_emit_market_chart_restore_feedback_if_ready_v1"):
            self._emit_market_chart_restore_feedback_if_ready_v1()

    def activate_overview_quick_action(self, focus: str) -> None:
        self.set_overview_focus(focus)
        route = OVERVIEW_QUICK_ROUTE_SPECS.get(
            focus,
            {"workspace": "overview", "widget": "intraday_chart_view"},
        )
        self._navigate_to_workspace(
            str(route.get("workspace", "overview")),
            str(route.get("widget")) if route.get("widget") else None,
            str(route.get("select_row")) if route.get("select_row") else None,
        )
        if hasattr(self, "overview_command_text"):
            existing = self.overview_command_text.toPlainText().strip()
            prefix = f"当前视图：{focus}"
            if existing:
                lines = existing.splitlines()
                if lines and lines[0].startswith("当前视图："):
                    lines[0] = prefix
                else:
                    lines = [prefix, ""] + lines
                self._set_plain_text_if_changed(self.overview_command_text, "\n".join(lines))
        if hasattr(self, "market_status_label"):
            status_text = self.market_status_label.text().split(" | 快捷：", 1)[0]
            self._set_label_text_if_changed(self.market_status_label, f"{status_text} | 快捷：{focus}")

    def set_overview_focus(self, focus: str) -> None:
        self.overview_focus_mode = focus or "市场总览"
        for button in getattr(self, "overview_quick_buttons", {}).values():
            button.blockSignals(True)
            button.setChecked(button.text() == self.overview_focus_mode)
            button.blockSignals(False)

        main_sizes = {
            "市场总览": [360, 1020, 360],
            "龙头池": [300, 1160, 320],
            "涨跌分布": [430, 950, 320],
            "资金方向": [320, 1080, 320],
            "题材热度": [320, 930, 430],
            "交易决策": [300, 900, 480],
        }.get(self.overview_focus_mode, [360, 1020, 360])
        left_sizes = {
            "市场总览": [1, 1, 1],
            "龙头池": [1, 1, 1],
            "涨跌分布": [110, 160, 260],
            "资金方向": [150, 110, 150],
            "题材热度": [120, 100, 220],
            "交易决策": [110, 110, 180],
        }.get(self.overview_focus_mode, [1, 1, 1])
        mini_sizes = {
            "市场总览": [1, 1],
            "龙头池": [1, 1],
            "涨跌分布": [1, 1],
            "资金方向": [3, 2],
            "题材热度": [1, 1],
            "交易决策": [2, 1],
        }.get(self.overview_focus_mode, [1, 1])

        if hasattr(self, "overview_main_splitter"):
            self._configure_splitter(self.overview_main_splitter, main_sizes)
        if hasattr(self, "overview_left_notes_splitter"):
            self._configure_splitter(self.overview_left_notes_splitter, left_sizes)
        if hasattr(self, "overview_mini_chart_splitter"):
            self._configure_splitter(self.overview_mini_chart_splitter, mini_sizes)

        focus_widget = {
            "龙头池": getattr(self, "market_pool_table", None),
            "涨跌分布": getattr(self, "market_breadth_text", None),
            "资金方向": getattr(self, "market_capital_text", None),
            "题材热度": getattr(self, "market_theme_brief_text", None),
            "交易决策": getattr(self, "market_decision_text", None),
        }.get(self.overview_focus_mode)
        if focus_widget is not None:
            focus_widget.setFocus()

        if hasattr(self, "market_status_label"):
            status_text = self.market_status_label.text()
            if " | 页面：" in status_text:
                base_text, page_suffix = status_text.split(" | 页面：", 1)
                page_text = page_suffix.split(" | 视图：", 1)[0]
                self._set_label_text_if_changed(self.market_status_label, f"{base_text} | 页面：{page_text} | 视图：{self.overview_focus_mode}")
            else:
                base_text = status_text.split(" | 视图：", 1)[0].strip()
                self._set_label_text_if_changed(self.market_status_label, f"{base_text} | 视图：{self.overview_focus_mode}")

    def set_market_timeframe(self, timeframe: str) -> None:
        self.market_timeframe_mode = timeframe or "日线"
        matched = False
        for button in getattr(self, "timeframe_buttons", {}).values():
            checked = button.text() == self.market_timeframe_mode
            matched = matched or checked
            button.blockSignals(True)
            button.setChecked(checked)
            button.blockSignals(False)
        if not matched and getattr(self, "timeframe_buttons", None):
            fallback = next(iter(self.timeframe_buttons.values()))
            self.market_timeframe_mode = fallback.text()
            fallback.setChecked(True)

        intraday_height = 320 if self.market_timeframe_mode != "日线" else 260
        daily_height = 360 if self.market_timeframe_mode != "日线" else 420
        if hasattr(self, "intraday_chart_view"):
            self.intraday_chart_view.setMinimumHeight(intraday_height)
            chart = self.intraday_chart_view.chart()
            if chart is not None:
                chart.setTitle("市场代理走势" if self.market_timeframe_mode == "日线" else f"{self.market_timeframe_mode} 走势")
        if hasattr(self, "daily_chart_view"):
            self.daily_chart_view.setMinimumHeight(daily_height)
            chart = self.daily_chart_view.chart()
            if chart is not None:
                chart.setTitle("日线主图" if self.market_timeframe_mode == "日线" else f"{self.market_timeframe_mode} 主图")
        if hasattr(self, "fund_chart_view"):
            chart = self.fund_chart_view.chart()
            if chart is not None:
                chart.setTitle("主力资金" if self.market_timeframe_mode == "日线" else f"{self.market_timeframe_mode} 资金")
        if hasattr(self, "momentum_chart_view"):
            chart = self.momentum_chart_view.chart()
            if chart is not None:
                chart.setTitle("龙头动能" if self.market_timeframe_mode == "日线" else f"{self.market_timeframe_mode} 动能")

        if self.active_symbol and self.active_symbol in self.universe_bars:
            self._render_market_dashboard(self.active_symbol)
        elif getattr(self.market_screen_result, "algorithmic_pool", []):
            preferred = self.market_screen_result.algorithmic_pool[0].symbol
            if preferred in self.universe_bars:
                self._render_market_dashboard(preferred)

    def set_market_history_window(self, window_label: str) -> None:
        self.market_history_window = window_label or "近1年"
        matched = False
        for button in getattr(self, "history_window_buttons", {}).values():
            checked = button.text() == self.market_history_window
            matched = matched or checked
            button.blockSignals(True)
            button.setChecked(checked)
            button.blockSignals(False)
        if not matched and getattr(self, "history_window_buttons", None):
            fallback = next(iter(self.history_window_buttons.values()))
            self.market_history_window = fallback.text()
            fallback.setChecked(True)
        self.market_chart_offset = 0
        if hasattr(self, "market_status_label"):
            base = self.market_status_label.text().split(" | 窗口：", 1)[0]
            self._set_label_text_if_changed(self.market_status_label, f"{base} | 窗口：{self.market_history_window}")
        if self.active_symbol and self.active_symbol in self.universe_bars:
            self._render_market_dashboard(self.active_symbol)

    def _current_market_chart_symbol(self) -> str:
        current_symbol = self.active_symbol if self.active_symbol in self.universe_bars else ""
        if not current_symbol and getattr(self.market_screen_result, "algorithmic_pool", []):
            candidate = self.market_screen_result.algorithmic_pool[0].symbol
            current_symbol = candidate if candidate in self.universe_bars else ""
        return current_symbol

    def _market_chart_navigation_metrics(self, symbol: str, chart_series=None, snapshot=None) -> tuple[list[PriceBar], int, int, int, int]:
        bars = self._market_chart_bars(symbol, snapshot, chart_series)
        target_size = self._market_history_target_size(len(bars)) if bars else 0
        fine_step = max(1, min(12 if self._is_intraday_market_timeframe() else 5, target_size // 8 if target_size else 1))
        coarse_step = max(4 if self._is_intraday_market_timeframe() else 1, target_size // 3 if target_size else 1)
        max_offset = max((len(bars) - target_size + coarse_step - 1) // coarse_step, 0) if bars else 0
        return bars, target_size, fine_step, coarse_step, max_offset

    @staticmethod
    def _market_chart_range_text(visible_bars: list[PriceBar], timeframe: str) -> str:
        if not visible_bars:
            return "--"
        start = visible_bars[0].date
        end = visible_bars[-1].date
        if timeframe in {"分时", "1分", "5分", "15分", "30分", "60分"}:
            start_text = start[-5:] if len(start) >= 5 else start
            end_text = end[-5:] if len(end) >= 5 else end
        elif timeframe == "月线":
            start_text = start[:7]
            end_text = end[:7]
        else:
            start_text = start
            end_text = end
        return start_text if start_text == end_text else f"{start_text} ~ {end_text}"

    @staticmethod
    def _market_chart_visible_summary(visible_bars: list[PriceBar]) -> str:
        if not visible_bars:
            return "可视摘要 --"
        highs = [bar.high for bar in visible_bars]
        lows = [bar.low for bar in visible_bars]
        highest = max(highs)
        lowest = min(lows)
        first_close = visible_bars[0].close
        last_close = visible_bars[-1].close
        change_pct = ((last_close - first_close) / first_close * 100.0) if abs(first_close) > 1e-9 else 0.0
        amplitude_pct = ((highest - lowest) / lowest * 100.0) if lowest > 1e-9 else 0.0
        structure_text = QuantHunterWindow._market_structure_summary(visible_bars)
        rhythm_text = QuantHunterWindow._market_rhythm_summary(visible_bars)
        return (
            f"可视摘要 高 {highest:.2f} / 低 {lowest:.2f} / "
            f"振幅 {amplitude_pct:.2f}% / 收盘变化 {change_pct:+.2f}% / {structure_text} / {rhythm_text}"
        )

    def _refresh_market_chart_navigation_state(self, symbol: str, chart_series=None, snapshot=None) -> None:
        if not symbol:
            return
        bars, _, _, _, max_offset = self._market_chart_navigation_metrics(symbol, chart_series, snapshot)
        visible_bars, _ = self._windowed_market_bars(symbol, bars, [])
        range_text = self._market_chart_range_text(visible_bars, self._normalize_market_timeframe())
        summary_text = self._market_chart_visible_summary(visible_bars)
        resonance_text = self._market_multi_timeframe_summary(symbol)
        structure_text = self._market_structure_summary(visible_bars)
        rhythm_text = self._market_rhythm_summary(visible_bars)
        breakout_values = [self._market_breakout_reference(visible_bars, index, lookback=10) for index in range(len(visible_bars))]
        breakout_states = [
            self._classify_market_breakout(
                bar,
                breakout_values[index],
                visible_bars[index - 1].close if index > 0 else None,
            )[0]
            for index, bar in enumerate(visible_bars)
        ]
        candle_text = self._latest_market_candle_tag_summary(visible_bars, breakout_values, breakout_states)
        score_text = self._market_chart_score_summary(structure_text, rhythm_text, candle_text, resonance_text)
        trade_zone_text = self._format_market_trade_zone(self._market_trade_zone_summary(visible_bars, score_text))
        at_latest = self.market_chart_offset <= 0
        at_oldest = self.market_chart_offset >= max_offset
        screen_index = 1 if max_offset <= 0 else min(self.market_chart_offset, max_offset) + 1
        screen_total = max_offset + 1 if max_offset > 0 else 1

        prev_button = getattr(self, "market_chart_prev_button", None)
        next_button = getattr(self, "market_chart_next_button", None)
        reset_button = getattr(self, "market_chart_reset_button", None)
        for button, enabled, role, tooltip in [
            (prev_button, not at_oldest, "ghost" if not at_oldest else "tonal", "继续向左看更早数据" if not at_oldest else "已经到最左侧边界"),
            (next_button, not at_latest, "ghost" if not at_latest else "tonal", "继续向右看更近数据" if not at_latest else "已经在最新位置"),
            (reset_button, not at_latest, "tonal", "回最新窗口" if not at_latest else "当前已经是最新窗口"),
        ]:
            if button is None:
                continue
            button.setEnabled(enabled)
            button.setToolTip(tooltip)
            self._set_button_role(button, role)
        if prev_button is not None:
            self._set_label_text_if_changed(prev_button, "向左翻一屏")
            prev_button.setToolTip("向左翻一屏，看更早的数据。按 PageUp 也可翻屏，Shift+左键 可细步进。" if not at_oldest else "已经到最左侧边界")
        if next_button is not None:
            self._set_label_text_if_changed(next_button, "向右翻一屏")
            next_button.setToolTip("向右翻一屏，看更近的数据。按 PageDown 也可翻屏，Shift+右键 可细步进。" if not at_latest else "已经在最新位置")
        if reset_button is not None:
            self._set_label_text_if_changed(reset_button, "回最新")
            reset_button.setToolTip("回最新窗口。按 Home 可快速重置。" if not at_latest else "当前已经是最新窗口")

        annotation_label, annotation_hint = self._market_strategy_annotation_mode_hint(
            getattr(self, "market_strategy_annotation_mode", "FULL")
        )
        annotation_detail = self._market_strategy_annotation_mode_detail(
            getattr(self, "market_strategy_annotation_mode", "FULL")
        )
        preset_label = self._market_chart_preset_label(getattr(self, "market_chart_preset", "BALANCED"))
        filter_banner = self._chart_action_note_filter_banner_v1() if hasattr(self, "_chart_action_note_filter_banner_v1") else "历史筛选：全部"
        filter_active = filter_banner != "历史筛选：全部"

        if hasattr(self, "market_status_label"):
            status_text = self.market_status_label.text()
            base = status_text.split(" | 区间：", 1)[0].split(" | 视窗：", 1)[0].split(" | 视窗偏移：", 1)[0]
            if max_offset <= 0:
                view_text = "第 1 屏 / 共 1 屏"
            elif at_latest:
                view_text = f"第 {screen_index} 屏 / 共 {screen_total} 屏 | 已在最新位置"
            elif at_oldest:
                view_text = f"第 {screen_index} 屏 / 共 {screen_total} 屏 | 已到最左侧边界"
            else:
                view_text = f"第 {screen_index} 屏 / 共 {screen_total} 屏"
            filter_suffix = f" | {filter_banner}" if filter_active else ""
            status_label_text = f"{base} | 区间：{range_text} | 视窗：{view_text}{filter_suffix}"
            status_tooltip = (
                f"{status_label_text}\n"
                f"当前图表预设：{preset_label}\n"
                f"当前战法标注：{annotation_label} / {annotation_hint}\n"
                f"{filter_banner}\n"
                f"{annotation_detail}\n"
                "快捷键：1 完整，2 计划，3 关闭，A 循环切换，Alt+Left/Right 回看提示，Alt+C 清除筛选。"
            )
            self._set_label_text_if_changed(self.market_status_label, status_label_text, tooltip=status_tooltip)
        if hasattr(self, "market_chart_nav_label"):
            nav_text = (
                f"K 线导航：{self._normalize_market_timeframe()} | {self.market_history_window} | "
                f"第 {screen_index} 屏 / 共 {screen_total} 屏 | 预设 {preset_label} | 标注 {annotation_label}/{annotation_hint} | "
                f"{filter_banner} | 区间 {range_text} | {trade_zone_text} | {score_text} | {summary_text} | {resonance_text} | "
                f"PageUp/PageDown 翻屏 | Shift+左右细步进 | Home 重置 | 1/2/3 战法标注 | A 循环切换 | Alt+左右回看提示 | Alt+C 清筛"
            )
            nav_tooltip = (
                f"{nav_text}\n"
                f"当前图表预设：{preset_label}\n"
                f"当前战法标注：{annotation_label} / {annotation_hint}\n"
                f"{filter_banner}\n"
                f"{annotation_detail}"
            )
            self._set_label_text_if_changed(self.market_chart_nav_label, nav_text, tooltip=nav_tooltip)
            restore_feedback = str(getattr(self, "_pending_market_chart_restore_feedback_v1", "") or "").strip()
            pending_feedback = str(getattr(self, "_market_chart_feedback_text", "") or "").strip()
            combined_feedback = " | ".join(part for part in [restore_feedback, pending_feedback] if part)
            if combined_feedback:
                self._set_label_text_if_changed(
                    self.market_chart_nav_label,
                    f"{nav_text} | {combined_feedback}",
                    tooltip=f"{nav_tooltip}\n临时反馈：{combined_feedback}",
                )
                self._market_chart_feedback_text = ""
                self._pending_market_chart_restore_feedback_v1 = ""
                timer = getattr(self, "_market_chart_feedback_timer", None)
                if timer is None:
                    timer = QTimer(self)
                    timer.setSingleShot(True)
                    timer.timeout.connect(self._clear_market_chart_feedback)
                    self._market_chart_feedback_timer = timer
                timer.start(1600)

    def _show_market_chart_feedback(self, message: str) -> None:
        self._market_chart_feedback_text = message or ""

    def _clear_market_chart_feedback(self) -> None:
        current_symbol = self._current_market_chart_symbol()
        if current_symbol:
            chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(current_symbol)
            snapshot = getattr(self.market_screen_result, "snapshots", {}).get(current_symbol)
            self._refresh_market_chart_navigation_state(current_symbol, chart_series, snapshot)

    def _apply_market_primary_chart_expanded_state(self) -> None:
        expanded = bool(getattr(self, "market_primary_chart_expanded", False))
        primary_tabs = getattr(self, "overview_primary_chart_tabs", None)
        mini_tabs = getattr(self, "overview_mini_chart_tabs", None)
        left_panel = getattr(self, "overview_left_panel", None)
        zoom_button = getattr(self, "market_chart_zoom_button", None)

        if isinstance(primary_tabs, QTabWidget):
            if expanded:
                primary_tabs.setCurrentIndex(0)
            primary_tabs.setMaximumHeight(16777215)
        if isinstance(mini_tabs, QWidget):
            mini_tabs.setVisible(not expanded)
        if isinstance(left_panel, QWidget):
            left_panel.setMinimumWidth(236 if expanded else 264)
        if isinstance(zoom_button, QPushButton):
            zoom_button.blockSignals(True)
            zoom_button.setText("还原主图" if expanded else "放大主图")
            zoom_button.setToolTip("恢复主图和副图的默认布局。" if expanded else "展开 K 线主图并收起副图，便于专注看主图走势。")
            self._set_button_role(zoom_button, "accent" if expanded else "ghost")
            zoom_button.blockSignals(False)

    def set_market_primary_chart_expanded(
        self,
        expanded: bool,
        *,
        feedback: bool = True,
        save: bool = True,
        update_preset: bool = True,
    ) -> None:
        target = bool(expanded)
        current = bool(getattr(self, "market_primary_chart_expanded", False))
        self.market_primary_chart_expanded = target
        QuantHunterWindow._apply_market_primary_chart_expanded_state(self)
        if hasattr(self, "state"):
            self.state.market_primary_chart_expanded = target
        if hasattr(self, "_apply_layout_polish_v19"):
            self._apply_layout_polish_v19()
        if update_preset:
            self._sync_market_chart_preset_state(persist=save)
        elif save:
            self.save_state()
        if feedback and target != current:
            self._show_market_chart_feedback("已放大 K 线主图" if target else "已恢复默认图表布局")

    def toggle_market_primary_chart_expanded(self) -> None:
        QuantHunterWindow.set_market_primary_chart_expanded(
            self,
            not bool(getattr(self, "market_primary_chart_expanded", False)),
        )

    def open_market_chart_focus_dialog(self) -> None:
        if bool(getattr(self, "market_chart_focus_dialog_open", False)):
            return
        chart_view = getattr(self, "daily_chart_view", None)
        origin_layout = getattr(self, "overview_daily_chart_layout", None)
        if not isinstance(chart_view, QChartView) or not isinstance(origin_layout, QVBoxLayout):
            return

        context = _qh_market_chart_dialog_context_v1(self)
        _qh_apply_market_chart_dialog_status_v1(self, route_key="focus_dialog", context=context)
        self.market_chart_focus_dialog_open = True
        dialog = QDialog(self)
        dialog.setWindowTitle(
            f"全屏看图 - {str(getattr(self, 'market_header_label', None).text() if hasattr(getattr(self, 'market_header_label', None), 'text') else getattr(self, 'active_symbol', '') or 'K线主图')}"
        )
        dialog.setModal(True)
        dialog.resize(1440, 920)

        layout = QVBoxLayout(dialog)
        layout.setContentsMargins(18, 18, 18, 18)
        layout.setSpacing(12)

        title_label = QLabel(_qh_market_chart_dialog_title_text_v1(context, route_key="focus_dialog"))
        title_label.setAccessibleName("marketChartFocusTitle")
        title_label.setObjectName("workspaceTitle")
        layout.addWidget(title_label)

        hint_label = QLabel(_qh_market_chart_dialog_intro_text_v1(context, route_key="focus_dialog"))
        hint_label.setAccessibleName("marketChartFocusHint")
        hint_label.setObjectName("inlineHint")
        hint_label.setWordWrap(True)
        hint_label.setToolTip(hint_label.text())
        layout.addWidget(hint_label)

        button_row = QHBoxLayout()
        button_row.setContentsMargins(0, 0, 0, 0)
        button_row.setSpacing(8)
        close_button = QPushButton("回主界面")
        self._set_button_role(close_button, "accent")
        close_button.clicked.connect(dialog.accept)
        button_row.addStretch(1)
        button_row.addWidget(close_button)
        layout.addLayout(button_row)

        previous_parent = chart_view.parentWidget()
        previous_layout = previous_parent.layout() if previous_parent is not None else None
        if previous_layout is not None:
            previous_layout.removeWidget(chart_view)
        chart_view.setMinimumHeight(0)
        chart_view.setMaximumHeight(16777215)
        chart_view.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Expanding)
        layout.addWidget(chart_view, stretch=1)

        self._show_market_chart_feedback("已进全屏看图")
        try:
            dialog.setWindowState(dialog.windowState() | Qt.WindowMaximized)
            dialog.exec()
        finally:
            layout.removeWidget(chart_view)
            origin_layout.addWidget(chart_view)
            chart_view.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Fixed)
            self.market_chart_focus_dialog_open = False
            if hasattr(self, "_apply_layout_polish_v19"):
                self._apply_layout_polish_v19()
            current_symbol = self._current_market_chart_symbol()
            if current_symbol:
                self._render_market_dashboard(current_symbol)
            self._show_market_chart_feedback("已退全屏看图")

    def shift_market_chart_window(self, step_delta: int, *, fine: bool = False) -> None:
        current_symbol = self._current_market_chart_symbol()
        if not current_symbol:
            return
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(current_symbol)
        snapshot = getattr(self.market_screen_result, "snapshots", {}).get(current_symbol)
        _, _, fine_step, coarse_step, max_offset = self._market_chart_navigation_metrics(current_symbol, chart_series, snapshot)
        step = fine_step if fine else coarse_step
        previous_offset = getattr(self, "market_chart_offset", 0)
        self.market_chart_offset = max(0, min(previous_offset + step_delta, max_offset))
        if max_offset <= 0:
            feedback = "当前窗口已覆盖全部数据"
        elif self.market_chart_offset == previous_offset and step_delta > 0:
            feedback = "已经到最左侧边界"
        elif self.market_chart_offset == previous_offset and step_delta < 0:
            feedback = "已经在最新位置"
        elif fine:
            feedback = "已细步进到相邻窗口"
        elif step_delta > 0:
            feedback = "已向左翻一屏"
        else:
            feedback = "已向右翻一屏"
        self._show_market_chart_feedback(feedback)
        self._render_market_dashboard(current_symbol)

    def keyPressEvent(self, event) -> None:
        if getattr(self, "tabs", None) is not None and self.tabs.currentWidget() is self.overview_tab:
            fine = bool(event.modifiers() & Qt.ShiftModifier)
            no_modifier = event.modifiers() in {Qt.NoModifier, Qt.KeypadModifier}
            alt_modifier = bool(event.modifiers() & Qt.AltModifier)
            if alt_modifier and self._market_hotkeys_available():
                if event.key() == Qt.Key_Left and self._can_step_market_chart_action_note_history_v1(-1):
                    self._step_market_chart_action_note_history_v1(-1)
                    event.accept()
                    return
                if event.key() == Qt.Key_Right and self._can_step_market_chart_action_note_history_v1(1):
                    self._step_market_chart_action_note_history_v1(1)
                    event.accept()
                    return
                if event.key() == Qt.Key_C and self._chart_action_note_filter_source_v1():
                    self._clear_chart_action_note_source_filter_v1()
                    event.accept()
                    return
            if event.key() == Qt.Key_PageUp:
                self.shift_market_chart_window(1, fine=False)
                event.accept()
                return
            if event.key() == Qt.Key_PageDown:
                self.shift_market_chart_window(-1, fine=False)
                event.accept()
                return
            if event.key() == Qt.Key_Left:
                self.shift_market_chart_window(1, fine=fine)
                event.accept()
                return
            if event.key() == Qt.Key_Right:
                self.shift_market_chart_window(-1, fine=fine)
                event.accept()
                return
            if event.key() == Qt.Key_Home:
                self.reset_market_chart_window()
                event.accept()
                return
            if no_modifier and self._market_hotkeys_available():
                if event.key() == Qt.Key_F:
                    self.open_market_chart_focus_dialog()
                    event.accept()
                    return
                if event.key() == Qt.Key_1:
                    self.set_market_strategy_annotation_mode("FULL")
                    event.accept()
                    return
                if event.key() == Qt.Key_2:
                    self.set_market_strategy_annotation_mode("PLAN")
                    event.accept()
                    return
                if event.key() == Qt.Key_3:
                    self.set_market_strategy_annotation_mode("OFF")
                    event.accept()
                    return
                if event.key() == Qt.Key_A:
                    self.cycle_market_strategy_annotation_mode(1)
                    event.accept()
                    return
        super().keyPressEvent(event)

    def toggle_market_overlay(self, overlay_name: str, *, save: bool = True, update_preset: bool = True) -> None:
        if not overlay_name:
            return
        if overlay_name in self.market_overlay_modes:
            if len(self.market_overlay_modes) > 1:
                self.market_overlay_modes.remove(overlay_name)
                self._show_market_chart_feedback(f"已关闭 {overlay_name} 叠加")
            else:
                self._show_market_chart_feedback("至少保留一个主图叠加指标")
        else:
            self.market_overlay_modes.add(overlay_name)
            self._show_market_chart_feedback(f"已开启 {overlay_name} 叠加")
        for name, button in getattr(self, "market_overlay_buttons", {}).items():
            checked = name in self.market_overlay_modes
            button.blockSignals(True)
            button.setChecked(checked)
            button.blockSignals(False)
            self._set_button_role(button, "tonal" if checked else "ghost")
        if hasattr(self, "state"):
            self.state.market_overlay_modes = sorted(self.market_overlay_modes)
        if update_preset:
            self._sync_market_chart_preset_state(persist=save)
        elif save:
            self.save_state()
        if self.active_symbol and self.active_symbol in self.universe_bars:
            self._render_market_dashboard(self.active_symbol)

    def set_market_strategy_annotation_mode(
        self,
        mode: str,
        *,
        save: bool = True,
        feedback: bool = True,
        update_preset: bool = True,
    ) -> None:
        self.market_strategy_annotation_mode = self._normalize_market_strategy_annotation_mode(mode)
        mode_label, mode_hint = self._market_strategy_annotation_mode_hint(self.market_strategy_annotation_mode)
        for name, button in getattr(self, "market_annotation_mode_buttons", {}).items():
            checked = name == self.market_strategy_annotation_mode
            button.blockSignals(True)
            button.setChecked(checked)
            button.blockSignals(False)
            self._set_button_role(button, "accent" if checked else "ghost")
        if hasattr(self, "state"):
            self.state.market_strategy_annotation_mode = self.market_strategy_annotation_mode
        if update_preset:
            self._sync_market_chart_preset_state(persist=save)
        elif save:
            self.save_state()
        if feedback:
            self._show_market_chart_feedback(
                f"战法标注已切换为 {mode_label} / {mode_hint}"
            )
        if self.active_symbol and self.active_symbol in self.universe_bars:
            self._render_market_dashboard(self.active_symbol)

    def cycle_market_strategy_annotation_mode(self, step: int = 1) -> None:
        modes = ["FULL", "PLAN", "OFF"]
        current = self._normalize_market_strategy_annotation_mode(getattr(self, "market_strategy_annotation_mode", "FULL"))
        try:
            index = modes.index(current)
        except ValueError:
            index = 0
        self.set_market_strategy_annotation_mode(modes[(index + step) % len(modes)])

    def _market_hotkeys_available(self) -> bool:
        focus = QApplication.focusWidget()
        if isinstance(focus, (QLineEdit, QTextEdit, QComboBox)):
            return False
        return True

    def set_market_secondary_indicator(
        self,
        indicator_name: str,
        *,
        save: bool = True,
        feedback: bool = True,
        update_preset: bool = True,
    ) -> None:
        self.market_secondary_indicator_mode = indicator_name or "MACD"
        for name, button in getattr(self, "secondary_indicator_buttons", {}).items():
            checked = name == self.market_secondary_indicator_mode
            button.blockSignals(True)
            button.setChecked(checked)
            button.blockSignals(False)
            self._set_button_role(button, "accent" if checked else "ghost")
        if hasattr(self, "state"):
            self.state.market_secondary_indicator_mode = str(self.market_secondary_indicator_mode or "MACD").upper()
        if update_preset:
            self._sync_market_chart_preset_state(persist=save)
        elif save:
            self.save_state()
        if feedback:
            self._show_market_chart_feedback(f"副图指标已切换为 {self.market_secondary_indicator_mode}")
        if self.active_symbol and self.active_symbol in self.universe_bars:
            self._update_indicator_chart(self.active_symbol)

    def _refresh_trade_plan(self) -> None:
        if not hasattr(self, "trade_plan_table"):
            return
        plan = QuantHunterWindow._current_trade_plan_cached(self)
        self.current_trade_plan = plan
        self._emit_market_path_alerts(plan)
        recommendation_map = {item.symbol: item for item in getattr(self, "daily_pool_rows", [])}
        trade_plan_signature = tuple(
            (
                "优先执行" if row_index == 0 else f"候选 {row_index + 1}",
                item.stock_name,
                item.stock_id,
                item.symbol,
                self._display_action(item.action),
                item.stock_pool or "--",
                item.opportunity_tier or "--",
                f"{item.execution_readiness:.1f}",
                f"{item.confidence:.0%}",
                f"{item.planned_entry:.2f}",
                f"{item.planned_stop:.2f}",
                f"{item.planned_target:.2f}",
                f"{item.suggested_budget:,.0f}",
                item.next_focus or "--",
                trade_plan_execution_hint(item, recommendation_map.get(item.symbol)),
                item.rationale,
            )
            for row_index, item in enumerate(plan.decisions)
        )
        if getattr(self, "_trade_plan_table_signature", None) != trade_plan_signature:
            updates_enabled = self.trade_plan_table.updatesEnabled()
            self.trade_plan_table.setUpdatesEnabled(False)
            self.trade_plan_table.blockSignals(True)
            try:
                self.trade_plan_table.setColumnCount(16)
                self.trade_plan_table.setRowCount(len(plan.decisions))
                for row_index, row_values in enumerate(trade_plan_signature):
                    for column, value in enumerate(row_values):
                        self.trade_plan_table.setItem(row_index, column, QTableWidgetItem(value))
            finally:
                self.trade_plan_table.blockSignals(False)
                self.trade_plan_table.setUpdatesEnabled(updates_enabled)
            self._trade_plan_table_signature = trade_plan_signature
        if hasattr(self, "trade_plan_focus_label"):
            if plan.decisions:
                lead = plan.decisions[0]
                self.trade_plan_focus_label.setText(
                    f"今日第一计划：{lead.stock_name} | {lead.opportunity_tier or '待确认'} | 执行准备 {lead.execution_readiness:.1f} | 审查 继续复核"
                )
            else:
                self.trade_plan_focus_label.setText(TRADE_PLAN_DEFAULT_FOCUS_TEXT)
        if hasattr(self, "trade_plan_empty_hint"):
            if plan.decisions:
                self.trade_plan_empty_hint.hide()
            else:
                reason_lines = [note for note in plan.notes if "没有" in note or "等待" in note or "观察" in note]
                hint = reason_lines[0] if reason_lines else "当前没有满足条件的新开仓计划，请先关注市场方向和现有持仓。"
                self.trade_plan_empty_hint.setText(hint)
                self.trade_plan_empty_hint.show()
        if hasattr(self, "trade_plan_empty_actions"):
            self.trade_plan_empty_actions.setVisible(not bool(plan.decisions))
        self._refresh_action_flow_cards(plan)
        self._refresh_priority_cards(plan)
        self._refresh_recommend_summary_cards(plan)
        self._refresh_workspace_status_labels()
        if hasattr(self, "trade_plan_text"):
            risk_key = getattr(self.state, "strategy_risk_profile", "standard")
            risk_label = RISK_PROFILE_LABELS.get(risk_key, risk_key)
            risk_hint = risk_profile_brief(risk_key)
            lines = [
                f"市场状态：{plan.market_sentiment} ({plan.sentiment_score:.1f})",
                f"交易环境：{plan.market_pulse.market_regime} | 风险等级：{plan.market_pulse.risk_level}",
                f"风控档位：{risk_label} | {risk_hint}",
                f"仓位上限：{plan.market_pulse.max_total_exposure:.0%} | 最多新开仓：{plan.max_new_positions}",
                "",
            ]
            if self.state.focus_themes:
                lines.append(f"当前关注主线：{', '.join(self.state.focus_themes)}")
                lines.append("")
            if plan.decisions:
                lead = plan.decisions[0]
                lead_row = next((row for row in self.daily_pool_rows if row.stock_id == lead.stock_id), None)
                lines.append(f"第一执行计划：{lead.stock_name} ({lead.stock_id} / {lead.symbol})")
                lines.extend(trade_decision_focus_lines(lead, lead_row))
                phase_labels = one_day_hold_phase_labels(lead, lead_row)
                if phase_labels:
                    lines.append("一日持股检查：")
                    lines.extend(f"- {label}" for label in phase_labels)
                lines.append(f"执行动作：{self._display_action(lead.action)}")
                lines.append(f"核心逻辑：{lead.rationale}")
                if len(plan.decisions) > 1:
                    backup = " / ".join(
                        f"{item.stock_name}({item.opportunity_tier or '观察'})" for item in plan.decisions[1:3]
                    )
                    if backup:
                        lines.extend(["", f"备选计划：{backup}"])
            else:
                lines.append("今日结论：暂无可执行新仓计划。")
                lines.append("优先事项：先看市场强弱，再处理已有持仓。")
            note_lines = [note for note in plan.notes if note]
            if note_lines:
                lines.extend(["", "补充提示："])
                lines.extend(f"- {note}" for note in note_lines[:4])
            self._set_plain_text_if_changed(self.trade_plan_text, "\n".join(lines))
        if hasattr(self, "market_pulse_text"):
            pulse = plan.market_pulse
            self._set_plain_text_if_changed(
                self.market_pulse_text,
                "\n".join(
                    [
                        f"市场温度：{pulse.sentiment_label}",
                        f"情绪分数：{pulse.sentiment_score:.1f}",
                        f"市场周期：{pulse.market_regime}",
                        f"风险等级：{pulse.risk_level}",
                        f"总仓位上限：{pulse.max_total_exposure:.0%}",
                        f"买入占比：{pulse.buy_ratio:.0%}",
                        f"候选均分：{pulse.average_total_score:.1f}",
                        f"强势候选数：{pulse.strong_candidates}",
                        f"风险提示候选数：{pulse.caution_candidates}",
                    ]
                )
            )
        if hasattr(self, "position_advice_table"):
            self.current_position_advice = list(plan.position_advice)
            position_advice_signature = tuple(
                (
                    item.stock_name,
                    item.stock_id,
                    item.symbol,
                    self._display_action(item.action),
                    getattr(item, "mainline_flow_signal", "") or getattr(item, "mainline_stage", "") or "--",
                    f"{item.confidence:.0%}",
                    f"{item.current_price:.2f}",
                    f"{item.cost_price:.2f}",
                    f"{item.pnl_pct:.2%}",
                    position_advice_check_item(item, recommendation_map.get(item.symbol)),
                    item.rationale,
                )
                for item in plan.position_advice
            )
            if getattr(self, "_position_advice_table_signature", None) != position_advice_signature:
                updates_enabled = self.position_advice_table.updatesEnabled()
                self.position_advice_table.setUpdatesEnabled(False)
                self.position_advice_table.blockSignals(True)
                try:
                    self.position_advice_table.setColumnCount(11)
                    self.position_advice_table.setRowCount(len(plan.position_advice))
                    for row_index, row_values in enumerate(position_advice_signature):
                        for column, value in enumerate(row_values):
                            self.position_advice_table.setItem(row_index, column, QTableWidgetItem(value))
                finally:
                    self.position_advice_table.blockSignals(False)
                    self.position_advice_table.setUpdatesEnabled(updates_enabled)
                self._position_advice_table_signature = position_advice_signature
        if hasattr(self, "position_advice_text"):
            if plan.position_advice:
                sell_count = sum(1 for item in plan.position_advice if item.action == "SELL")
                reduce_count = sum(1 for item in plan.position_advice if item.action == "REDUCE")
                hold_count = sum(1 for item in plan.position_advice if item.action == "HOLD")
                one_day_symbols = [
                    item.stock_name
                    for item in plan.position_advice
                    if _recommendation_strategy_name(recommendation_map.get(item.symbol), default="") in {"一日持股法", "尾盘买入法"}
                ]
                lines = [
                    f"持仓建议概览：卖出 {sell_count} 只，减仓 {reduce_count} 只，继续持有 {hold_count} 只。",
                    "请结合止盈、止损与盘中异动变化继续观察，必要时优先执行减仓或卖出。",
                ]
                if one_day_symbols:
                    lines.append(
                        f"短隔夜检查：{', '.join(one_day_symbols)} 先看尾盘或次日开盘是否符合节奏，不及预期优先兑现，不做拖仓。"
                    )
                    lead_one_day = next(
                        (
                            item
                            for item in plan.position_advice
                            if _recommendation_strategy_name(recommendation_map.get(item.symbol), default="") in {"一日持股法", "尾盘买入法"}
                        ),
                        None,
                    )
                    if lead_one_day is not None:
                        lines.extend(f"- {label}" for label in one_day_hold_phase_labels(lead_one_day, recommendation_map.get(lead_one_day.symbol)))
                self._set_plain_text_if_changed(
                    self.position_advice_text,
                    "\n".join(lines)
                )
            else:
                self._set_plain_text_if_changed(self.position_advice_text, "当前没有持仓数据，导入持仓 CSV 或同步券商账户后会生成建议。")

    def _populate_existing_views_from_market(self) -> None:
        if hasattr(self, "_refresh_market_search_completer_v1"):
            self._refresh_market_search_completer_v1()
        if hasattr(self, "scan_table"):
            self._fill_scan_rows()
        if hasattr(self, "summary_table"):
            self._fill_backtest_summaries()
        if hasattr(self, "daily_pool_table"):
            self._populate_daily_pool_table()
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(
                self.recommend_status_label,
                f"推荐状态：已切换为程序自动筛选股票池，共 {len(self.daily_pool_rows)} 只候选 | 当前结论：继续复核 | 下一步：先锁定前排票。",
            )
        if hasattr(self, "daily_pool_focus_label"):
            if self.daily_pool_rows:
                top = self.daily_pool_rows[0]
                self._set_label_text_if_changed(
                    self.daily_pool_focus_label,
                    f"当前焦点：{top.stock_name} | {top.opportunity_tier or '待确认'} | 主线 {top.mainline_tag or top.theme_name or '待确认'} | 审查 继续复核",
                )
            else:
                self._set_label_text_if_changed(self.daily_pool_focus_label, RECOMMEND_DEFAULT_FOCUS_TEXT)
        if hasattr(self, "_refresh_scanner_capability_overview_v1"):
            self._refresh_scanner_capability_overview_v1()
        if hasattr(self, "daily_pool_text"):
            if self.daily_pool_rows:
                top = self.daily_pool_rows[0]
                tradable_count = sum(1 for row in self.daily_pool_rows[:5] if row.action == "BUY")
                backup = " / ".join(row.stock_name for row in self.daily_pool_rows[1:4])
                lines = [
                    "今日优先候选",
                    f"第一目标：{top.stock_name} ({top.stock_id} / {top.symbol})",
                    f"可执行判断：{self._display_action(top.action)} | 总分 {top.total_score:.1f}",
                ]
                grade = one_day_hold_grade(top)
                if grade:
                    lines.append(f"隔日博弈等级：{grade}")
                lines.extend(recommendation_focus_lines(top))
                lines.append(f"触发逻辑：{top.catalyst or '量价共振 + 资金聚焦'}")
                lines.append(f"核心理由：{top.rationale}")
                lines.append(f"前五候选中可执行数量：{tradable_count}")
                if backup:
                    lines.append(f"备选关注：{backup}")
                self._set_plain_text_if_changed(self.daily_pool_text, "\n".join(lines))
            else:
                self._set_plain_text_if_changed(
                    self.daily_pool_text,
                    "综合机会池\n当前结论：继续复核\n风险：暂无清晰主线，候选尚未生成\n下一步：先刷新市场、确认主线并重算机会池。",
                )
        self._refresh_trade_plan()
        self._refresh_board_mode()
        self._refresh_intraday_monitor()
        if hasattr(self, "_refresh_overview_capability_overview_v1"):
            self._refresh_overview_capability_overview_v1()
        self._refresh_scanner_focus_status()
        self._refresh_recommend_focus_status()

    def _on_trade_plan_selection_changed(self) -> None:
        if not hasattr(self, "trade_plan_table") or not hasattr(self, "daily_pool_table"):
            return
        row_index = self.trade_plan_table.currentRow()
        if row_index < 0:
            return
        stock_id_item = self.trade_plan_table.item(row_index, 2)
        stock_id = stock_id_item.text() if stock_id_item else ""
        if not stock_id:
            return
        selected = self._select_daily_pool_row_by_stock_id(stock_id)
        self._refresh_recommendation_focus_panels(selected)

    def _refresh_trade_plan(self) -> None:
        if not hasattr(self, "trade_plan_table"):
            return
        plan = QuantHunterWindow._current_trade_plan_cached(self)
        self.current_trade_plan = plan
        self._emit_market_path_alerts(plan)
        table_rows: list[list[str]] = []
        for row_index, item in enumerate(plan.decisions):
            status = "优先执行" if row_index == 0 else f"候选 {row_index + 1}"
            values = [
                status,
                item.stock_name,
                item.stock_id,
                item.symbol,
                self._display_action(item.action),
                item.stock_pool or "--",
                item.opportunity_tier or "--",
                f"{item.execution_readiness:.1f}",
                f"{item.confidence:.0%}",
                f"{item.planned_entry:.2f}",
                f"{item.planned_stop:.2f}",
                f"{item.planned_target:.2f}",
                f"{item.suggested_budget:,.0f}",
                item.next_focus or "--",
                item.rationale,
            ]
            table_rows.append(values)
        table_signature = tuple(tuple(row) for row in table_rows)
        previous_signature = tuple(getattr(self, "_trade_plan_table_signature", ()))
        if previous_signature != table_signature:
            updates_enabled = self.trade_plan_table.updatesEnabled()
            self.trade_plan_table.setUpdatesEnabled(False)
            self.trade_plan_table.blockSignals(True)
            try:
                self.trade_plan_table.setRowCount(len(table_rows))
                for row_index, values in enumerate(table_rows):
                    if row_index < len(previous_signature) and previous_signature[row_index] == table_signature[row_index]:
                        continue
                    for column, value in enumerate(values):
                        item = self.trade_plan_table.item(row_index, column)
                        if item is None:
                            self.trade_plan_table.setItem(row_index, column, QTableWidgetItem(value))
                        elif item.text() != value:
                            item.setText(value)
            finally:
                self.trade_plan_table.blockSignals(False)
                self.trade_plan_table.setUpdatesEnabled(updates_enabled)
            self._trade_plan_table_signature = table_signature
        if hasattr(self, "trade_plan_focus_label"):
            if plan.decisions:
                lead = plan.decisions[0]
                QuantHunterWindow._set_label_text_if_changed(
                    self,
                    self.trade_plan_focus_label,
                    f"今日第一计划：{lead.stock_name} | {lead.opportunity_tier or '待确认'} | 执行准备 {lead.execution_readiness:.1f}"
                )
            else:
                QuantHunterWindow._set_label_text_if_changed(self, self.trade_plan_focus_label, TRADE_PLAN_DEFAULT_FOCUS_TEXT)
        if hasattr(self, "trade_plan_empty_hint"):
            if plan.decisions:
                self.trade_plan_empty_hint.hide()
            else:
                reason_lines = [note for note in plan.notes if "没有" in note or "等待" in note or "观察" in note]
                hint = reason_lines[0] if reason_lines else "当前没有满足条件的新开仓计划，请先关注市场方向和现有持仓。"
                QuantHunterWindow._set_label_text_if_changed(self, self.trade_plan_empty_hint, hint)
                self.trade_plan_empty_hint.show()
        if hasattr(self, "trade_plan_empty_actions"):
            self.trade_plan_empty_actions.setVisible(not bool(plan.decisions))
        self._refresh_action_flow_cards(plan)
        self._refresh_priority_cards(plan)
        self._refresh_recommend_summary_cards(plan)
        if hasattr(self, "trade_plan_text"):
            risk_key = getattr(self.state, "strategy_risk_profile", "standard")
            risk_label = RISK_PROFILE_LABELS.get(risk_key, risk_key)
            risk_hint = risk_profile_brief(risk_key)
            lines = [
                f"市场状态：{plan.market_sentiment} ({plan.sentiment_score:.1f})",
                f"交易环境：{plan.market_pulse.market_regime} | 风险等级：{plan.market_pulse.risk_level}",
                f"风控档位：{risk_label} | {risk_hint}",
                f"仓位上限：{plan.market_pulse.max_total_exposure:.0%} | 最多新开仓：{plan.max_new_positions}",
                "",
            ]
            if self.state.focus_themes:
                lines.append(f"当前关注主线：{', '.join(self.state.focus_themes)}")
                lines.append("")
            if plan.decisions:
                lead = plan.decisions[0]
                lead_row = next((row for row in self.daily_pool_rows if row.stock_id == lead.stock_id), None)
                lines.append(f"第一执行计划：{lead.stock_name} ({lead.stock_id} / {lead.symbol})")
                lines.extend(trade_decision_focus_lines(lead, lead_row))
                lines.append(f"执行动作：{self._display_action(lead.action)}")
                lines.append(f"核心逻辑：{lead.rationale}")
                if len(plan.decisions) > 1:
                    backup = " / ".join(
                        f"{item.stock_name}({item.opportunity_tier or '观察'})" for item in plan.decisions[1:3]
                    )
                    if backup:
                        lines.extend(["", f"备选计划：{backup}"])
            else:
                lines.append("今日结论：暂无可执行新仓计划。")
                lines.append("优先事项：先看市场强弱，再处理已有持仓。")
            note_lines = [note for note in plan.notes if note]
            if note_lines:
                lines.extend(["", "补充提示："])
                lines.extend(f"- {note}" for note in note_lines[:4])
            QuantHunterWindow._set_plain_text_if_changed(self, self.trade_plan_text, "\n".join(lines))
        if hasattr(self, "market_pulse_text"):
            pulse = plan.market_pulse
            self._set_plain_text_if_changed(
                self.market_pulse_text,
                "\n".join(
                    [
                        f"市场温度：{pulse.sentiment_label}",
                        f"情绪分数：{pulse.sentiment_score:.1f}",
                        f"市场周期：{pulse.market_regime}",
                        f"风险等级：{pulse.risk_level}",
                        f"总仓位上限：{pulse.max_total_exposure:.0%}",
                        f"买入占比：{pulse.buy_ratio:.0%}",
                        f"候选均分：{pulse.average_total_score:.1f}",
                        f"强势候选数：{pulse.strong_candidates}",
                        f"风险提示候选数：{pulse.caution_candidates}",
                    ]
                )
            )
        if hasattr(self, "position_advice_table"):
            self.current_position_advice = list(plan.position_advice)
            position_advice_signature = tuple(
                (
                    item.stock_name,
                    item.stock_id,
                    item.symbol,
                    self._display_action(item.action),
                    f"{item.confidence:.0%}",
                    f"{item.current_price:.2f}",
                    f"{item.cost_price:.2f}",
                    f"{item.pnl_pct:.2%}",
                    item.rationale,
                )
                for item in plan.position_advice
            )
            previous_position_signature = tuple(getattr(self, "_position_advice_table_signature", ()))
            updates_enabled = self.position_advice_table.updatesEnabled()
            self.position_advice_table.setUpdatesEnabled(False)
            self.position_advice_table.blockSignals(True)
            try:
                self.position_advice_table.setRowCount(len(plan.position_advice))
                for row_index, item in enumerate(plan.position_advice):
                    if row_index < len(previous_position_signature) and previous_position_signature[row_index] == position_advice_signature[row_index]:
                        continue
                    values = list(position_advice_signature[row_index])
                    for column, value in enumerate(values):
                        cell_item = self.position_advice_table.item(row_index, column)
                        if cell_item is None:
                            self.position_advice_table.setItem(row_index, column, QTableWidgetItem(value))
                        elif cell_item.text() != value:
                            cell_item.setText(value)
            finally:
                self.position_advice_table.blockSignals(False)
                self.position_advice_table.setUpdatesEnabled(updates_enabled)
            self._position_advice_table_signature = position_advice_signature
        if hasattr(self, "position_advice_text"):
            if plan.position_advice:
                sell_count = sum(1 for item in plan.position_advice if item.action == "SELL")
                reduce_count = sum(1 for item in plan.position_advice if item.action == "REDUCE")
                hold_count = sum(1 for item in plan.position_advice if item.action == "HOLD")
                self._set_plain_text_if_changed(
                    self.position_advice_text,
                    "\n".join(
                        [
                            f"持仓处理概览：卖出 {sell_count} 只，减仓 {reduce_count} 只，继续持有 {hold_count} 只。",
                            "说明：当出现诱多陷阱、跌破防守位或高位浮盈回落时，会优先给出减仓或卖出建议。",
                        ]
                    )
                )
            else:
                self._set_plain_text_if_changed(
                    self.position_advice_text,
                    "当前没有持仓数据，导入持仓 CSV 后会显示卖出和格局建议。"
                )

