    def _queue_symbol_to_watchlist(self, symbol: str) -> None:
        if symbol and symbol not in self.state.watchlist:
            self.state.watchlist.append(symbol)
            self.state.watchlist.sort()
            self._refresh_watchlist()
            self.save_state()

