    def _refresh_live_workspace_summary_panels(self) -> None:
        if hasattr(self, "scanner_live_summary_headline"):
            scan_count = self.scan_table.rowCount() if hasattr(self, "scan_table") else 0
            watch_count = self.watchlist_widget.count() if hasattr(self, "watchlist_widget") else 0
            monitor_count = self.monitor_table.rowCount() if hasattr(self, "monitor_table") else 0
            auto_refresh = "开启" if hasattr(self, "auto_refresh_checkbox") and self.auto_refresh_checkbox.isChecked() else "关闭"
            self._set_label_text_if_changed(self.scanner_live_summary_headline, f"扫描 {scan_count} / 观察 {watch_count} / 监控 {monitor_count}")
            self._set_label_text_if_changed(self.scanner_live_summary_detail, f"盘中自动刷新：{auto_refresh} | 最近刷新：{getattr(self, 'last_refresh_label', QLabel('--')).text()}")
            self._set_label_text_if_changed(self.scanner_live_summary_meta, f"当前股票池：{getattr(self, 'universe_label', QLabel('--')).text()}")

        if hasattr(self, "scanner_live_summary_headline"):
            scanner_focus = self._stock_name_for_symbol(self.active_symbol) if getattr(self, "active_symbol", "") else universe_text
            self._set_label_text_if_changed(self.scanner_live_summary_headline, f"当前状态：扫描 {scan_count} / 观察 {watch_count} / 监控 {monitor_count} | 自动刷新 {auto_refresh}")
            self._set_label_text_if_changed(self.scanner_live_summary_detail, f"焦点：{scanner_focus}")
            self._set_label_text_if_changed(self.scanner_live_summary_meta, f"下一步：{'继续看监控动作与候选去向' if scan_count else '先执行扫描，再确认焦点标的'}")

        if hasattr(self, "board_live_summary_headline"):
            candidate_count = self.board_table.rowCount() if hasattr(self, "board_table") else 0
            monitor_count = self.board_monitor_table.rowCount() if hasattr(self, "board_monitor_table") else 0
            auto_export = "开启" if hasattr(self, "auto_review_export_checkbox") and self.auto_review_export_checkbox.isChecked() else "关闭"
            self._set_label_text_if_changed(self.board_live_summary_headline, f"候选 {candidate_count} / 监控 {monitor_count}")
            self._set_label_text_if_changed(self.board_live_summary_detail, f"收盘导出：{auto_export} | 焦点联动：扫描 / 推荐 / 复盘")
            self._set_label_text_if_changed(self.board_live_summary_meta, getattr(self, "board_focus_label", QLabel("等待焦点同步")).text() if hasattr(self, "board_focus_label") else "等待焦点同步")

        if hasattr(self, "board_live_summary_headline"):
            self._set_label_text_if_changed(self.board_live_summary_headline, f"当前状态：候选 {candidate_count} / 监控 {board_monitor_count} | 收盘导出 {auto_export}")
            self._set_label_text_if_changed(self.board_live_summary_detail, f"焦点：{board_focus_text}")
            self._set_label_text_if_changed(self.board_live_summary_meta, f"下一步：{'核对回封质量与执行动作' if (candidate_count or board_monitor_count) else '先刷新候选，再确认监控焦点'}")

        if hasattr(self, "detail_live_summary_headline"):
            signal_count = self.signal_table.rowCount() if hasattr(self, "signal_table") else 0
            trade_count = self.trades_table.rowCount() if hasattr(self, "trades_table") else 0
            active_symbol = getattr(self, "active_symbol", "") or "未选中"
            self._set_label_text_if_changed(self.detail_live_summary_headline, f"当前标的：{active_symbol}")
            self._set_label_text_if_changed(self.detail_live_summary_detail, f"近期信号 {signal_count} 条 | 交易记录 {trade_count} 条")
            self._set_label_text_if_changed(self.detail_live_summary_meta, getattr(self, "active_symbol_label", QLabel("当前标的：未选择")).text())

        if hasattr(self, "detail_live_summary_headline"):
            self._set_label_text_if_changed(self.detail_live_summary_headline, f"当前状态：近期信号 {signal_count} 条 | 交易记录 {trade_count} 条")
            self._set_label_text_if_changed(self.detail_live_summary_detail, f"焦点：{active_symbol_text}")
            self._set_label_text_if_changed(self.detail_live_summary_meta, f"下一步：{'核对决策、执行与结论' if active_symbol != '未选中' else '先从机会池、扫描或执行中控联动一只股票'}")

        if hasattr(self, "config_live_summary_headline"):
            plan_text = self.state.license_plan or "TRIAL"
            top_theme_limit, max_total_exposure, _ = self._current_strategy_runtime_config()
            self._set_label_text_if_changed(self.config_live_summary_headline, f"方案：{plan_text} | 主线前排 {top_theme_limit}")
            risk_key = getattr(self.state, "strategy_risk_profile", "standard")
            risk_hint = risk_profile_brief(risk_key)
            pool_impact = risk_pool_impact_text(getattr(self, "last_daily_pool_meta", {}))
            pool_projection = risk_profile_projection_text(risk_key, getattr(self, "last_daily_pool_meta", {}))
            self._set_label_text_if_changed(self.config_live_summary_detail, f"总仓位上限：{max_total_exposure:.2f} | 模板：{self.daily_plan_template_combo.currentText() if hasattr(self, 'daily_plan_template_combo') else '--'} | {pool_impact}")
            focus_theme_text = self.focus_themes_input.text().strip() if hasattr(self, "focus_themes_input") else ""
            risk_text = self.strategy_risk_profile_combo.currentText() if hasattr(self, "strategy_risk_profile_combo") else getattr(self.state, "strategy_risk_profile", "standard")
            self._set_label_text_if_changed(self.config_live_summary_meta, f"风险档位：{risk_text} | {risk_hint} | {pool_projection} | 关注题材：{focus_theme_text or '未设置'}")
            self._set_label_text_if_changed(self.config_live_summary_headline, f"当前状态：方案 {plan_text} | 消息源 {news_label}")
            self._set_label_text_if_changed(self.config_live_summary_detail, f"焦点：风险 {risk_text} | 模板 {template_text} | 关注主题 {focus_theme_text or '未设置'}")
            self._set_label_text_if_changed(self.config_live_summary_meta, f"下一步：保存后刷新机会池 | {pool_impact} | 最近消息载入：{loaded_at}")
            self._refresh_risk_snapshot_cards()

    def _refresh_workspace_focus_banners(self) -> None:
        target_symbol = self.active_symbol or self._selected_symbol_from_watchlist() or self._selected_board_symbol() or ""
        stock_name = self._stock_name_for_symbol(target_symbol) if target_symbol else "等待联动"
        stock_id = self._stock_id_for_symbol(target_symbol) if target_symbol else "--"
        recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == target_symbol), None) if target_symbol else None
        scan_row = next((row for row in getattr(self, "scan_rows", []) if getattr(row, "symbol", "") == target_symbol), None) if target_symbol else None
        tone = self._focus_banner_tone(symbol=target_symbol, recommendation=recommendation, scan_row=scan_row)
        if hasattr(self, "overview_focus_banner"):
            market_count = self.market_pool_table.rowCount() if hasattr(self, "market_pool_table") else 0
            text = f"总览焦点：{stock_name} ({stock_id} / {target_symbol}) | 龙头池 {market_count} | 与机会池联动 | 审查 继续复核" if target_symbol else "总览焦点：等待从龙头池、机会池或扫描页联动一只股票 | 审查 继续复核"
            self._set_focus_banner_state(self.overview_focus_banner, tone if target_symbol else 'idle', text)
        if hasattr(self, "recommend_focus_banner"):
            pool_count = self.daily_pool_table.rowCount() if hasattr(self, "daily_pool_table") else 0
            strategy_name = _recommendation_strategy_name(recommendation, default="") if recommendation is not None else ""
            text = f"推荐焦点：{stock_name} ({stock_id} / {target_symbol}) | 机会池 {pool_count} | 策略 {strategy_name or '等待策略同步'} | 审查 继续复核" if target_symbol else "推荐焦点：等待从机会池、龙头榜或交易计划联动一只股票 | 审查 继续复核"
            self._set_focus_banner_state(self.recommend_focus_banner, tone if target_symbol else 'idle', text)
        if hasattr(self, "scanner_focus_banner"):
            scan_count = self.scan_table.rowCount() if hasattr(self, "scan_table") else 0
            watch_count = self.watchlist_widget.count() if hasattr(self, "watchlist_widget") else 0
            text = f"扫描焦点：{stock_name} ({stock_id} / {target_symbol}) | 扫描 {scan_count} | 观察 {watch_count} | 审查 继续复核" if target_symbol else "扫描焦点：等待从扫描榜、观察池或盘中监控联动标的 | 审查 继续复核"
            self._set_focus_banner_state(self.scanner_focus_banner, tone if target_symbol else 'idle', text)
        if hasattr(self, "board_focus_banner"):
            candidate_count = self.board_table.rowCount() if hasattr(self, "board_table") else 0
            monitor_count = self.board_monitor_table.rowCount() if hasattr(self, "board_monitor_table") else 0
            text = f"打板焦点：{stock_name} ({stock_id} / {target_symbol}) | 候选 {candidate_count} | 监控 {monitor_count} | 审查 继续复核" if target_symbol else "打板焦点：等待扫描页或机会池同步强势候选 | 审查 继续复核"
            self._set_focus_banner_state(self.board_focus_banner, tone if target_symbol else 'idle', text)
        if hasattr(self, "detail_focus_banner"):
            signal_count = self.signal_table.rowCount() if hasattr(self, "signal_table") else 0
            trade_count = self.trades_table.rowCount() if hasattr(self, "trades_table") else 0
            text = f"复盘焦点：{stock_name} ({stock_id} / {target_symbol}) | 信号 {signal_count} | 成交 {trade_count} | 审查 继续复核" if target_symbol else "复盘焦点：等待扫描、机会池或涨停策略同步单票标的 | 审查 继续复核"
            self._set_focus_banner_state(self.detail_focus_banner, tone if target_symbol else 'idle', text)

    def _focus_banner_tone(self, symbol: str = "", recommendation=None, scan_row=None) -> str:
        if not symbol:
            return "idle"
        action = str(getattr(recommendation, "action", "") or getattr(scan_row, "action", "") or "").upper()
        risk_flag = str(getattr(recommendation, "mainline_risk_flag", "") or "")
        if action in {"SELL", "REDUCE"} or any(token in risk_flag for token in ["红", "高", "风险"]):
            return "risk"
        if action == "BUY":
            return "buy"
        if action == "WATCH" or action:
            return "watch"
        return "idle"

    def _refresh_overview_focus_cards(self, symbol: str, snapshot, recommendation) -> None:
        if not hasattr(self, "overview_summary_cards"):
            return
        if recommendation is not None:
            theme_name = getattr(recommendation, "mainline_tag", "") or getattr(recommendation, "theme_name", "") or "待确认"
            role_name = self._display_mainline_role(getattr(recommendation, "mainline_role", "") or "")
            strategy_name = _recommendation_strategy_name(recommendation)
            action_label = self._display_action(getattr(recommendation, "action", "WATCH"))
            catalyst = getattr(recommendation, "catalyst", "") or "等待消息与量价共振"
            decision_score = _recommendation_decision_score(recommendation)
            self.overview_summary_cards["theme"].set_data(theme_name, f"{recommendation.stock_name} | {role_name} | 位次 {getattr(recommendation, 'mainline_rank', getattr(recommendation, 'theme_rank', '--'))}")
            self.overview_summary_cards["source"].set_data(strategy_name, f"{action_label} | 催化 {catalyst}")
            self.overview_summary_cards["capital"].set_data(f"{float(getattr(recommendation, 'mainline_window_score', 0.0) or 0.0):.1f}", f"总分 {float(getattr(recommendation, 'total_score', 0.0) or 0.0):.1f} | 风险 {getattr(recommendation, 'mainline_risk_flag', '') or '待评估'}")
            self.overview_summary_cards["decision"].set_data(action_label, f"决策分 {decision_score:.1f} | 执行准备 {float(getattr(recommendation, 'execution_readiness', 0.0) or 0.0):.1f}")
            return
        if snapshot is not None:
            self.overview_summary_cards["theme"].set_data(snapshot.strategy_tag or "待确认", f"{snapshot.stock_name} | 热度 {snapshot.heat_score:.1f} | 动能 {snapshot.momentum_bias:.1f}")
            self.overview_summary_cards["source"].set_data(snapshot.fund_model or "待确认", f"{snapshot.stock_id} | 涨跌 {snapshot.pct_change:.2f}% | 换手 {snapshot.turnover:.2f}%")
            self.overview_summary_cards["capital"].set_data(f"{snapshot.main_inflow / 1e8:.2f} 亿", f"热度 {snapshot.heat_score:.1f} | 动能 {snapshot.momentum_bias:.1f} | 换手 {snapshot.turnover:.2f}%")
            self.overview_summary_cards["decision"].set_data("观察", f"{snapshot.strategy_tag} | 涨跌 {snapshot.pct_change:.2f}% | 先看量价承接")
            return
        stock_name = self._stock_name_for_symbol(symbol) if symbol else "等待行情接入"
        self.overview_summary_cards["theme"].set_data("等待行情接入", f"当前结论：继续复核 | {stock_name} | 等待主线题材、龙头位次与前排数量刷新。")
        self.overview_summary_cards["source"].set_data("等待行情接入", "当前结论：继续复核 | 等待远程行情、缓存或示例数据接入。")
        self.overview_summary_cards["capital"].set_data("等待窗口", "当前结论：继续复核 | 下一步 先刷新市场")
        self.overview_summary_cards["decision"].set_data("先观察", "当前结论：继续复核 | 下一步 暂不做动作判断")

    def _refresh_overview_left_intel_cards(self, symbol: str, snapshot, recommendation) -> None:
        target_symbol = str(symbol or "").strip()
        if not target_symbol:
            target_symbol = str(getattr(recommendation, "symbol", "") or "")
        latest_news = self._latest_news_item_for_symbol(target_symbol) if hasattr(self, "_latest_news_item_for_symbol") else None
        news_items = [latest_news] if latest_news is not None else []
        confidence = news_confidence_label(news_items)
        source_name = str(getattr(latest_news, "source", "") or "来源待确认") if latest_news is not None else "来源待确认"
        source_label = news_source_visual_label(source_name) if latest_news is not None else "消息线索"
        published_at = str(getattr(latest_news, "published_at", "") or "时间待同步") if latest_news is not None else "时间待同步"
        title = str(getattr(latest_news, "title", "") or "") if latest_news is not None else ""
        summary = str(getattr(latest_news, "summary", "") or "").replace("\r", " ").replace("\n", " ").strip() if latest_news is not None else ""
        recommendation_copy = QuantHunterWindow._news_recommended_action_copy_safe_v57(self, latest_news) if latest_news is not None else "建议：先看主线、量价和验证焦点"
        news_text = (
            "\n".join(
                [
                    f"结论：{source_label} | {confidence}",
                    f"来源：{source_name} | {published_at}",
                    f"标题：{title}",
                    f"建议：{recommendation_copy.split('：', 1)[-1].strip()}",
                ]
            )
            if latest_news is not None
            else "\n".join(
                [
                    "结论：等待最近消息",
                    "状态：当前焦点还没有可靠来源，系统会优先补最近快讯、公告或兜底消息。",
                    "建议：先看买点、防守和验证焦点。",
                ]
            )
        )
        if summary and latest_news is not None:
            news_text += f"\n摘要：{summary[:56]}"
        if hasattr(self, "overview_top_news_text"):
            self._set_plain_text_if_changed(self.overview_top_news_text, news_text)
        if hasattr(self, "overview_top_news_source_button"):
            self._update_news_action_button(self.overview_top_news_source_button, latest_news)
        if hasattr(self, "overview_top_news_detail_button"):
            self._update_news_detail_button(self.overview_top_news_detail_button, latest_news)

        ai_text_widget = getattr(self, "overview_top_ai_text", None)
        if ai_text_widget is not None:
            config = self._current_ai_review_config() if hasattr(self, "_current_ai_review_config") else SimpleNamespace(model="--", api_key="")
            model_name = str(getattr(config, "model", "--") or "--")
            api_key_ready = bool(str(getattr(config, "api_key", "") or "").strip())
            current_row = recommendation or (next((item for item in getattr(self, "daily_pool_rows", []) if getattr(item, "symbol", "") == target_symbol), None) if target_symbol else None)
            current_name = getattr(current_row, "stock_name", "") or (self._stock_name_for_symbol(target_symbol) if target_symbol and hasattr(self, "_stock_name_for_symbol") else target_symbol or "等待焦点同步")
            pending_symbol = str(getattr(self, "ai_review_pending_symbol", "") or "")
            last_symbol = str(getattr(self, "ai_review_last_symbol", "") or "")
            last_error = str(getattr(self, "ai_review_last_error", "") or "")
            cached_result = (getattr(self, "ai_review_results_by_symbol", {}) or {}).get(target_symbol) if target_symbol else None
            if pending_symbol and pending_symbol == target_symbol:
                ai_text = "\n".join(
                    [
                        f"结论：正在评测 {current_name}",
                        f"模型：{model_name} | 触发 {str(getattr(self, 'ai_review_last_trigger', '') or 'manual')}",
                        "下一步：先等流式内容完成，再判断要不要继续推进。",
                    ]
                )
            elif cached_result is not None:
                ai_text = "\n".join(
                    [
                        f"结论：最近已评测 {current_name}",
                        f"模型：{model_name} | 缓存 {len(getattr(self, 'ai_review_results_by_symbol', {}) or {})} 条",
                        f"摘要：{str(getattr(cached_result, 'summary', '') or '继续复核').strip()[:72]}",
                        "下一步：去机会池看完整评测，再决定是否送审或转交易。",
                    ]
                )
            elif last_error and last_symbol == target_symbol:
                ai_text = "\n".join(
                    [
                        f"结论：AI评测最近失败 {current_name}",
                        f"模型：{model_name}",
                        f"原因：{last_error[:72]}",
                        "下一步：先去 AI 设置核对 Key、模型和超时，再重跑当前焦点。",
                    ]
                )
            elif not api_key_ready:
                ai_text = "\n".join(
                    [
                        "结论：AI评测待启用",
                        f"模型：{model_name} | API Key 待补",
                        "下一步：先点 AI 设置补 Key，再回来评测当前焦点。",
                    ]
                )
            else:
                ai_text = "\n".join(
                    [
                        f"结论：可直接评测 {current_name}",
                        f"模型：{model_name}",
                        "下一步：点“评测当前焦点”，优先复核这只票值不值得推进。",
                    ]
                )
            self._set_plain_text_if_changed(ai_text_widget, ai_text)

    def _refresh_recommend_story_panels(self, row: RecommendationRow | None = None) -> None:
        current = row or self._selected_daily_pool_recommendation()
        if current is None:
            if hasattr(self, "daily_pool_text") and not self.daily_pool_text.toPlainText().strip():
                self._set_plain_text_if_changed(self.daily_pool_text, "机会池将在刷新后生成，默认最多展示 5 只可执行候选。")
            if hasattr(self, "strategy_path_text") and not self.strategy_path_text.toPlainText().strip():
                self._set_plain_text_if_changed(self.strategy_path_text, "等待生成机会池后更新主线推演路径。")
            self._refresh_recommend_bucket_panels(None)
            return

        theme_name = getattr(current, "mainline_tag", "") or getattr(current, "theme_name", "") or "待确认"
        role_name = getattr(current, "mainline_role", "") or ""
        flow_signal = getattr(current, "mainline_flow_signal", "") or "待确认"
        stage_name = getattr(current, "mainline_stage", "") or "待确认"
        readiness = float(getattr(current, "execution_readiness", 0.0) or 0.0)
        confidence = float(getattr(current, "confidence_score", 0.0) or 0.0)
        stock_pool = getattr(current, "stock_pool", "") or "程序自动筛选池"
        catalyst = getattr(current, "catalyst", "") or "量价共振 + 资金回流"
        next_focus = getattr(current, "next_focus", "") or "继续盯主线强度、量能承接和回流节奏。"
        invalidation = getattr(current, "invalidation_reason", "") or "跌破防守位或主线切换时重新评估。"

        if hasattr(self, "daily_pool_text"):
            lines = [
                "今日优先候选",
                f"焦点标的：{current.stock_name} ({current.stock_id} / {current.symbol})",
                f"主线：{theme_name} | 阶段：{stage_name} | 角色：{self._display_mainline_role(role_name)}",
                f"动作：{self._display_action(getattr(current, 'action', 'WATCH'))} | 总分 {current.total_score:.1f}",
                f"执行准备：{readiness:.1f} | 置信：{confidence:.1f} | 股票池：{stock_pool}",
                f"催化：{catalyst}",
                f"逻辑：{getattr(current, 'rationale', '') or '等待更清晰的主线与量价确认。'}",
            ]
            self._set_plain_text_if_changed(self.daily_pool_text, "\n".join(lines))

        if hasattr(self, "strategy_path_text"):
            lines = [
                f"主线推演：{current.stock_name}",
                f"第一步：主线 {theme_name} 当前处于 {stage_name}，信号为 {flow_signal}。",
                f"第二步：当前角色是 {self._display_mainline_role(role_name)}，先看是否继续维持前排强度。",
                f"第三步：若执行准备 {readiness:.1f} 持续抬升，可考虑按 {_recommendation_strategy_name(current)} 计划推进。",
                f"第四步：重点观察 {next_focus}",
                f"失效条件：{invalidation}",
            ]
            self._set_plain_text_if_changed(self.strategy_path_text, "\n".join(lines))
        self._refresh_recommend_bucket_panels(current)

    def _on_daily_pool_selection_changed(self) -> None:
        current = self._selected_daily_pool_recommendation()
        if current is not None and getattr(current, "symbol", "") in self.universe_bars:
            self.select_symbol(current.symbol, origin="recommend")
        self._refresh_recommendation_focus_panels()
        self._refresh_strategy_focus_detail()

    def select_symbol(self, symbol: str, origin: str = "") -> None:
        if symbol not in self.universe_bars:
            return
        previous_symbol = getattr(self, "active_symbol", "")
        current_revision = int(getattr(self, "_symbol_data_revision", 0) or 0)
        if (
            symbol == getattr(self, "active_symbol", "")
            and symbol == getattr(self, "_last_rendered_symbol", "")
            and current_revision == int(getattr(self, "_last_rendered_symbol_revision", -1) or -1)
        ):
            self._sync_symbol_across_workspaces(symbol, origin=origin)
            return
        if previous_symbol and previous_symbol != symbol:
            self._clear_market_chart_action_note(previous_symbol)
        self.active_symbol = symbol
        self.bars = self.universe_bars[symbol]
        self.analyses = self.universe_analyses[symbol]
        if hasattr(self, "active_symbol_label"):
            self._set_label_text_if_changed(self.active_symbol_label, f"当前标的：{symbol}")
        self.state.selected_symbol = symbol
        self._refresh_signal_panel()
        self.run_backtest_for_active(quiet=True)
        if self._should_render_market_dashboard_now():
            self._pending_market_dashboard_symbol = ""
            self._render_market_dashboard(symbol)
        else:
            self._pending_market_dashboard_symbol = symbol
        self._refresh_detail_workspace_panels()
        self._sync_symbol_across_workspaces(symbol, origin=origin)
        self._last_rendered_symbol = symbol
        self._last_rendered_symbol_revision = current_revision
        self._refresh_workspace_focus_banners()
        self._refresh_live_workspace_summary_panels()
        if hasattr(self, "_refresh_overview_capability_overview_v1"):
            self._refresh_overview_capability_overview_v1()
        self.save_state()

    def _should_render_market_dashboard_now(self) -> bool:
        if not hasattr(self, "tabs") or not hasattr(self, "overview_tab"):
            return True
        return self.tabs.currentWidget() is self.overview_tab

    def _flush_pending_market_dashboard_render(self) -> None:
        symbol = str(getattr(self, "_pending_market_dashboard_symbol", "") or "")
        if not symbol or symbol not in getattr(self, "universe_bars", {}):
            return
        self._pending_market_dashboard_symbol = ""
        self._render_market_dashboard(symbol)

    def _schedule_market_auxiliary_render(self, symbol: str) -> None:
        if not symbol:
            return
        self._pending_market_aux_symbol = symbol
        if not hasattr(self, "_market_aux_render_timer"):
            timer = QTimer(self)
            timer.setSingleShot(True)
            timer.timeout.connect(self._flush_pending_market_auxiliary_render)
            self._market_aux_render_timer = timer
        self._market_aux_render_timer.start(0)

    def _flush_pending_market_auxiliary_render(self) -> None:
        symbol = str(getattr(self, "_pending_market_aux_symbol", "") or "")
        if not symbol or symbol != getattr(self, "active_symbol", ""):
            return
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        self._pending_market_aux_symbol = ""
        self._update_fund_chart(symbol, chart_series)
        self._update_momentum_chart(symbol, chart_series)
        self._update_indicator_chart(symbol)

    def _render_market_dashboard(self, symbol: str) -> None:
        snapshot = self.market_snapshots.get(symbol)
        recommendation = next((item for item in self.daily_pool_rows if item.symbol == symbol), None)
        chart_series = getattr(self.market_screen_result, "chart_series_by_symbol", {}).get(symbol)
        display_bars = self._market_chart_bars(symbol, snapshot, chart_series)
        visible_bars, _ = self._windowed_market_bars(symbol, display_bars, [])
        structure_summary = self._market_structure_summary(visible_bars)
        rhythm_summary = self._market_rhythm_summary(visible_bars)
        breakout_values = [self._market_breakout_reference(visible_bars, index, lookback=10) for index in range(len(visible_bars))]
        breakout_states = [
            self._classify_market_breakout(
                bar,
                breakout_values[index],
                visible_bars[index - 1].close if index > 0 else None,
            )[0]
            for index, bar in enumerate(visible_bars)
        ]
        latest_candle_tag_summary = self._latest_market_candle_tag_summary(visible_bars, breakout_values, breakout_states)
        resonance_summary = self._market_multi_timeframe_summary(symbol)
        score_summary = self._market_chart_score_summary(structure_summary, rhythm_summary, latest_candle_tag_summary, resonance_summary)
        trade_zone_summary = self._format_market_trade_zone(self._market_trade_zone_summary(visible_bars, score_summary))
        rhythm_headline = f"{structure_summary} | {rhythm_summary} | {latest_candle_tag_summary} | {resonance_summary} | {score_summary} | {trade_zone_summary}"

        def _compact_copy(text: str, limit: int) -> str:
            clean = " ".join(str(text or "").split())
            return clean if len(clean) <= limit else clean[: max(1, limit - 1)] + "…"

        def _trade_zone_parts(summary_text: str) -> tuple[str, str]:
            raw = str(summary_text or "").replace("交易区间", "").strip()
            if not raw:
                return ("待价位带", "先刷新市场或选中焦点标的")
            parts = [part.strip() for part in raw.split("/") if part.strip()]
            if not parts:
                return (_compact_copy(raw, 12), "")
            headline = parts[0]
            detail = " / ".join(parts[1:3]) if len(parts) > 1 else ""
            return (_compact_copy(headline, 12), _compact_copy(detail, 18))

        rhythm_brief = f"结构 {structure_summary} | 节奏 {rhythm_summary} | 评分 {score_summary}"
        signal_brief = f"结构 {structure_summary} | 节奏 {rhythm_summary} | K线 {latest_candle_tag_summary} | 共振 {resonance_summary}"
        setup_brief = (
            f"买 {(recommendation.entry_price or recommendation.close):.2f} / 止 {(recommendation.stop_price or recommendation.close * 0.95):.2f} / "
            f"目 {(recommendation.target_price or recommendation.close * 1.08):.2f}"
            if recommendation is not None
            else f"窗口 {self.market_history_window} | 周期 {self.market_timeframe_mode}"
        )
        if hasattr(self, "market_header_label"):
            title = symbol if snapshot is None else f"{snapshot.stock_name}  {snapshot.stock_id}  {symbol}"
            self._set_label_text_if_changed(self.market_header_label, title)
        if hasattr(self, "market_subheader_label"):
            sub = "程序自动筛选出的龙头候选"
            if snapshot is not None:
                sub = (
                    f"{snapshot.strategy_tag} | {snapshot.fund_model} | 热 {snapshot.heat_score:.1f} | "
                    f"涨 {snapshot.pct_change:.2f}% | 净流 {snapshot.main_inflow / 1e8:.2f} 亿"
                )
            else:
                sub = f"{sub} | 结构 {structure_summary} | 节奏 {rhythm_summary}"
            self._set_label_text_if_changed(self.market_subheader_label, sub)
        if hasattr(self, "market_signal_label") and snapshot is not None:
            self._set_label_text_if_changed(
                self.market_signal_label,
                f"{snapshot.fund_model} | {snapshot.strategy_tag} | 动 {snapshot.momentum_bias:.1f} | {signal_brief}",
            )
        elif hasattr(self, "market_signal_label"):
            self._set_label_text_if_changed(
                self.market_signal_label,
                f"主线待确认 | {signal_brief}",
            )
        if hasattr(self, "market_quote_label"):
            if snapshot is not None:
                latest_price = snapshot.latest_price
                open_high_low = f"开 {snapshot.open_price:.2f} / 高 {snapshot.high_price:.2f} / 低 {snapshot.low_price:.2f} / 收 {latest_price:.2f}"
                self._set_label_text_if_changed(
                    self.market_quote_label,
                    f"{open_high_low} | 交易区间 {setup_brief} | 结构 {structure_summary}",
                )
            else:
                self._set_label_text_if_changed(
                    self.market_quote_label,
                    f"窗口 {self.market_history_window} | 周期 {self.market_timeframe_mode} | "
                    f"叠加 {'/'.join(self._ordered_market_overlays(self.market_overlay_modes)) or '关闭'} | "
                    f"战法 {self._market_strategy_annotation_mode_hint(getattr(self, 'market_strategy_annotation_mode', 'FULL'))[0]}"
                    f"({self._market_strategy_annotation_mode_hint(getattr(self, 'market_strategy_annotation_mode', 'FULL'))[1]}) | "
                    f"结构 {structure_summary}",
                )
        if hasattr(self, "market_focus_metric_labels"):
            has_chart_focus = bool(visible_bars)
            structure_value = _compact_copy(structure_summary, 10) if has_chart_focus else "待图表"
            structure_accent = (
                f"节奏 {_compact_copy(rhythm_summary, 12)} | 评 {_compact_copy(score_summary, 10)}"
                if has_chart_focus
                else f"窗口 {self.market_history_window} | 周期 {self.market_timeframe_mode}"
            )
            zone_value, zone_accent = _trade_zone_parts(trade_zone_summary if has_chart_focus else "")
            if recommendation is not None:
                zone_value = f"买 {(recommendation.entry_price or recommendation.close):.2f}"
                zone_accent = _compact_copy(f"止 {(recommendation.stop_price or recommendation.close * 0.95):.2f} / 目 {(recommendation.target_price or recommendation.close * 1.08):.2f}", 18)
            momentum_value = _compact_copy(latest_candle_tag_summary, 12) if has_chart_focus else "待共振"
            momentum_accent = f"共振 {_compact_copy(resonance_summary, 12)}" if has_chart_focus else "等待K线与多周期共振"
            flow_value = f"{snapshot.main_inflow / 1e8:.2f} 亿" if snapshot is not None else "待资金"
            flow_accent = (
                f"热 {snapshot.heat_score:.1f} / 换 {snapshot.turnover:.2f}%"
                if snapshot is not None
                else "等待资金画像"
            )
            self._set_label_text_if_changed(self.market_focus_metric_labels["structure"], structure_value)
            self._set_label_text_if_changed(self.market_focus_metric_accents["structure"], structure_accent)
            self._set_label_text_if_changed(self.market_focus_metric_labels["zone"], zone_value)
            self._set_label_text_if_changed(self.market_focus_metric_accents["zone"], zone_accent)
            self._set_label_text_if_changed(self.market_focus_metric_labels["momentum"], momentum_value)
            self._set_label_text_if_changed(self.market_focus_metric_accents["momentum"], momentum_accent)
            self._set_label_text_if_changed(self.market_focus_metric_labels["flow"], flow_value)
            self._set_label_text_if_changed(self.market_focus_metric_accents["flow"], flow_accent)
        self._update_intraday_chart(symbol, snapshot, chart_series)
        self._update_daily_chart(symbol)
        self._update_market_text_panels(symbol, snapshot, recommendation)
        self._refresh_overview_focus_cards(symbol, snapshot, recommendation)
        self._refresh_market_chart_navigation_state(symbol, chart_series, snapshot)
        self._set_market_chart_hover_summary("")
        self._schedule_market_auxiliary_render(symbol)

    def _normalize_recommend_workspace_texts(self) -> None:
        title_map = {
            "recommend_dispatch_text": "\u6267\u884c\u5206\u53d1",
            "recommend_focus_review_text": "\u5355\u7968\u5ba1\u67e5",
            "recommend_queue_text": "\u961f\u5217\u6982\u89c8",
            "strategy_detail_text": "\u6218\u6cd5\u660e\u7ec6",
            "strategy_path_text": "\u4e3b\u7ebf\u63a8\u6f14",
            "daily_pool_text": "\u4eca\u65e5\u4f18\u5148\u5019\u9009",
        }
        for attr_name, title in title_map.items():
            widget = getattr(self, attr_name, None)
            if widget is None:
                continue
            parent = widget.parentWidget()
            while parent is not None and not isinstance(parent, QGroupBox):
                parent = parent.parentWidget()
            if isinstance(parent, QGroupBox):
                parent.setTitle(title)

        if hasattr(self, "recommend_stage_tabs"):
            for index, label in enumerate(["\u6267\u884c", "\u7b56\u7565", "\u590d\u76d8"]):
                if index < self.recommend_stage_tabs.count():
                    self.recommend_stage_tabs.setTabText(index, label)

        button_map = {
            "show_core_execution_bucket": "\u53ea\u770b\u4e3b\u7ebf\u524d\u6392",
            "show_watch_bucket": "\u53ea\u770b\u89c2\u5bdf\u6c60",
            "show_risk_bucket": "\u53ea\u770b\u98ce\u9669\u6c60",
        }
        legacy_aliases = {
            "\u53ea\u770b\u4e3b\u7ebf\u524d\u6392": "show_core_execution_bucket",
            "\u53ea\u770b\u89c2\u5bdf\u6c60": "show_watch_bucket",
            "\u53ea\u770b\u98ce\u9669\u6c60": "show_risk_bucket",
            "\u53ea\u770b\u56de\u907f\u6c60": "show_risk_bucket",
        }
        for button in self.findChildren(QPushButton):
            text = button.text().strip()
            if text in legacy_aliases:
                button.setText(button_map[legacy_aliases[text]])
            elif text == "\u5bfc\u51fa\u8fd0\u884c\u65e5\u5fd7":
                button.setText("\u5bfc\u51fa\u65e5\u5fd7")

        title_aliases = {
            "\u4e70\u5165": "\u4e70\u5165",
            "\u89c2\u5bdf": "\u89c2\u5bdf",
            "\u51cf\u4ed3": "\u51cf\u4ed3",
            "\u79bb\u573a": "\u79bb\u573a",
            "\u5e02\u573a\u60c5\u7eea": "\u5e02\u573a\u60c5\u7eea",
            "\u4e3b\u7ebf\u9898\u6750": "\u4e3b\u7ebf\u9898\u6750",
            "\u9ad8\u4f18\u5148\u7b56\u7565": "\u9ad8\u4f18\u5148\u7b56\u7565",
            "\u7126\u70b9\u6807\u7684": "\u7126\u70b9\u6807\u7684",
        }
        for card_map_name in ["action_flow_cards", "priority_cards"]:
            card_map = getattr(self, card_map_name, None)
            if not card_map:
                continue
            for card in card_map.values():
                title_label = getattr(card, "title_label", None)
                if title_label is not None and title_label.text().strip() in title_aliases:
                    title_label.setText(title_aliases[title_label.text().strip()])

        strategy_combo = getattr(self, "strategy_detail_combo", None)
        if strategy_combo is not None:
            labels = ["\u9f99\u5934\u6a21\u578b", "\u4e3b\u529b\u96f7\u8fbe", "\u64d2\u9f99\u6253\u677f", "\u4ef7\u503c\u4f4e\u5438", "\u4e00\u65e5\u6301\u80a1\u6cd5", "\u6398\u9f99\u51b3\u7b56"]
            current = strategy_combo.currentText()
            strategy_combo.blockSignals(True)
            strategy_combo.clear()
            strategy_combo.addItems(labels)
            strategy_combo.setCurrentText(current if current in labels else labels[0])
            strategy_combo.blockSignals(False)

