    def load_universe_folder(self) -> None:
        start_dir = str(Path(self.state.universe_dir).expanduser()) if getattr(self.state, "universe_dir", "") else str(PROJECT_ROOT)
        selected_dir = QFileDialog.getExistingDirectory(self, "选择股票目录", start_dir)
        if not selected_dir:
            return
        folder = Path(selected_dir)
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(self.scan_summary_label, f"扫描状态：载入中 | 股票目录 {folder.name or folder} | 当前结论：继续复核 | 下一步：等待扫描完成。")
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(self.recommend_status_label, "推荐状态：等待回流 | 本地扫描结果待写回 | 当前结论：继续复核 | 下一步：自动重算机会池。")
        if hasattr(self, "last_refresh_label"):
            self._set_label_text_if_changed(self.last_refresh_label, "最近刷新：正在扫描本地股票目录")
        self.state.universe_dir = str(folder)
        self.save_state()
        self._scan_universe(folder, quiet=False, async_mode=True)

    def load_sample_universe(self) -> None:
        sample_dir = SAMPLE_DIR
        if not sample_dir.exists():
            QMessageBox.warning(self, "样例缺失", f"未找到样例目录：{sample_dir}")
            return
        if hasattr(self, "recommend_empty_meta"):
            self._set_label_text_if_changed(self.recommend_empty_meta, "正在载入样例股票池与参考资料，完成后会自动生成综合机会池。")
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：载入中 | 示例资料待联动 | 当前结论：继续复核 | 下一步：等待扫描结果写回。")
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(self.recommend_status_label, "推荐状态：重建中 | 样例资料待写回 | 当前结论：继续复核 | 下一步：等待机会池生成。")
        if hasattr(self, "last_refresh_label"):
            self._set_label_text_if_changed(self.last_refresh_label, "最近刷新：正在载入样例股票池")
        self.load_sample_reference_data()
        self.state.universe_dir = str(sample_dir)
        self.save_state()
        self._scan_universe(sample_dir, quiet=False, async_mode=True)

    def rescan_universe(self) -> None:
        target_value = str(getattr(self.state, "universe_dir", "") or "").strip()
        if not target_value:
            self.load_universe_folder()
            return
        target_dir = Path(target_value)
        if not target_dir.exists():
            QMessageBox.warning(self, "目录不存在", f"当前股票目录不存在：{target_dir}")
            self.load_universe_folder()
            return
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：重扫中 | 市场与观察池待更新 | 当前结论：继续复核 | 下一步：等待监控写回。")
        if hasattr(self, "last_refresh_label"):
            self._set_label_text_if_changed(self.last_refresh_label, "最近刷新：正在执行重新扫描")
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(self.recommend_status_label, "推荐状态：等待重扫 | 新结果待回流 | 当前结论：继续复核 | 下一步：自动刷新机会池。")
        self._scan_universe(target_dir, quiet=False, async_mode=True)

    def generate_order_suggestions(self) -> None:
        if not self.scan_rows:
            QMessageBox.information(self, "提示", "请先完成股票池扫描。")
            return
        try:
            per_trade_budget = float(self.per_trade_budget_input.text().strip())
        except ValueError:
            QMessageBox.critical(self, "参数错误", "单笔预算必须填写数字。")
            return
        if hasattr(self, "broker_status_banner"):
            self._set_label_text_if_changed(
                self.broker_status_banner,
                "交易状态：生成中 | 委托建议待写回 | 当前结论：继续复核 | 下一步：等待风险测算完成。",
            )
        rows = self.scan_rows if not self.state.watchlist else [row for row in self.scan_rows if row.symbol in self.state.watchlist]
        self.order_intents = EastmoneyBrokerAdapter().build_order_intents(rows, per_trade_budget)
        self._fill_orders()
        self._refresh_broker_order_focus()
        self._refresh_submission_focus()
        if self.order_intents:
            top_intent = self.order_intents[0]
            detail = f"已生成 {len(self.order_intents)} 笔委托建议，等待提交确认。"
            if hasattr(self, "_stock_name_for_symbol"):
                detail = f"已围绕 {self._stock_name_for_symbol(top_intent.symbol)} 生成 {len(self.order_intents)} 笔委托建议"
            if hasattr(self, "orders_focus_label"):
                self._set_label_text_if_changed(
                    self.orders_focus_label,
                    f"委托焦点：已生成 {len(self.order_intents)} 笔委托建议，优先关注 {self._stock_name_for_symbol(top_intent.symbol)}",
                )
            self._refresh_broker_status(extra=f"已生成 {len(self.order_intents)} 笔委托建议，等待提交确认。")
            _qh_apply_broker_action_status_v1(
                self,
                action="generate_orders",
                count=len(self.order_intents),
                detail=detail,
            )
        else:
            self._refresh_broker_status(extra="当前参数下暂无新的买入建议。")

    def confirm_and_submit_orders(self) -> None:
        if not self.order_intents:
            self.generate_order_suggestions()
        if not self.order_intents:
            return
        profile = self.current_broker_profile()
        adapter = EastmoneyBrokerAdapter()
        if not OrderConfirmationDialog.confirm(profile, self.order_intents, adapter, self):
            self._refresh_broker_status(extra="本次提交已取消，仍保留委托建议供你继续复核。")
            return

        submit_time = datetime.now().strftime("%Y-%m-%d %H:%M:%S")
        try:
            results = adapter.submit_order_intents(profile, self.order_intents)
        except Exception as exc:
            fallback_path = adapter.export_order_plan(
                self.order_intents,
                profile.export_dir,
                recommendations=getattr(self, "daily_pool_rows", []),
                execution_summary=getattr(self, "last_broker_execution_summary", {}) or {},
            )
            failure_lines = [
                f"[{submit_time}] SDK 下单失败：{exc}",
                f"[{submit_time}] 已回退导出 CSV：{fallback_path}",
            ]
            for item in self.order_intents:
                recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == item.symbol), None)
                self._append_submission_record(
                    timestamp=submit_time,
                    order_status="FAILED",
                    fill_status="REJECTED",
                    order_id="",
                    symbol=item.symbol,
                    side=item.side,
                    price=f"{item.price:.3f}",
                    quantity=str(item.quantity),
                    failure_reason=str(exc),
                    message=str(exc),
                    planned_price=f"{float(getattr(item, 'price', 0.0) or 0.0):.3f}" if float(getattr(item, "price", 0.0) or 0.0) > 0 else "",
                    planned_quantity=str(int(getattr(item, "quantity", 0) or 0)) if int(getattr(item, "quantity", 0) or 0) > 0 else "",
                    planned_stop_price=f"{float(getattr(item, 'stop_price', 0.0) or 0.0):.3f}" if float(getattr(item, "stop_price", 0.0) or 0.0) > 0 else "",
                    planned_target_price=f"{float(getattr(item, 'target_price', 0.0) or 0.0):.3f}" if float(getattr(item, "target_price", 0.0) or 0.0) > 0 else "",
                    opportunity_tier=str(getattr(recommendation, "opportunity_tier", "") or getattr(item, "opportunity_tier", "") or ""),
                    planned_risk_reward_ratio=f"{float(getattr(item, 'risk_reward_ratio', 0.0) or 0.0):.2f}" if float(getattr(item, "risk_reward_ratio", 0.0) or 0.0) > 0 else "",
                    portfolio_fit_score=f"{float(getattr(recommendation, 'portfolio_fit_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "portfolio_fit_score", 0.0) or 0.0) > 0 else "",
                    diversification_score=f"{float(getattr(recommendation, 'diversification_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "diversification_score", 0.0) or 0.0) > 0 else "",
                    concentration_penalty_score=f"{float(getattr(recommendation, 'concentration_penalty_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "concentration_penalty_score", 0.0) or 0.0) > 0 else "",
                )
            for line in failure_lines:
                self._append_order_result(line)
            self._refresh_broker_status(extra="\n".join(failure_lines))
            self._refresh_submission_focus()
            QMessageBox.warning(self, "下单失败", f"{exc}\n\n已回退导出 CSV：\n{fallback_path}")
            return

        normalized_results = [
            normalize_submission_result(result, symbol=item.symbol, expected_quantity=int(getattr(item, "quantity", 0) or 0))
            for item, result in zip(self.order_intents, results)
        ]
        success_lines = [f"[{submit_time}] SDK 下单完成：共 {len(normalized_results)} 笔"]
        success_lines.extend(f"[{submit_time}] {item['display_text']}" for item in normalized_results)
        for item, normalized in zip(self.order_intents, normalized_results):
            recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == item.symbol), None)
            self._append_submission_record(
                timestamp=submit_time,
                order_status=str(normalized.get("order_status", "SUBMITTED") or "SUBMITTED"),
                fill_status=str(normalized.get("fill_status", "PENDING") or "PENDING"),
                order_id=str(normalized.get("order_id", "") or ""),
                symbol=item.symbol,
                side=item.side,
                price=f"{item.price:.3f}",
                quantity=str(item.quantity),
                failure_reason="",
                message=str(normalized.get("message", "") or ""),
                planned_price=f"{float(getattr(item, 'price', 0.0) or 0.0):.3f}" if float(getattr(item, "price", 0.0) or 0.0) > 0 else "",
                planned_quantity=str(int(getattr(item, "quantity", 0) or 0)) if int(getattr(item, "quantity", 0) or 0) > 0 else "",
                planned_stop_price=f"{float(getattr(item, 'stop_price', 0.0) or 0.0):.3f}" if float(getattr(item, "stop_price", 0.0) or 0.0) > 0 else "",
                planned_target_price=f"{float(getattr(item, 'target_price', 0.0) or 0.0):.3f}" if float(getattr(item, "target_price", 0.0) or 0.0) > 0 else "",
                opportunity_tier=str(getattr(recommendation, "opportunity_tier", "") or getattr(item, "opportunity_tier", "") or ""),
                planned_risk_reward_ratio=f"{float(getattr(item, 'risk_reward_ratio', 0.0) or 0.0):.2f}" if float(getattr(item, "risk_reward_ratio", 0.0) or 0.0) > 0 else "",
                portfolio_fit_score=f"{float(getattr(recommendation, 'portfolio_fit_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "portfolio_fit_score", 0.0) or 0.0) > 0 else "",
                diversification_score=f"{float(getattr(recommendation, 'diversification_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "diversification_score", 0.0) or 0.0) > 0 else "",
                concentration_penalty_score=f"{float(getattr(recommendation, 'concentration_penalty_score', 0.0) or 0.0):.0f}" if recommendation is not None and float(getattr(recommendation, "concentration_penalty_score", 0.0) or 0.0) > 0 else "",
                fill_price=str(normalized.get("fill_price", "") or ""),
                fill_quantity=str(normalized.get("fill_quantity", "") or ""),
            )
        for line in success_lines:
            self._append_order_result(line)
        self.sync_broker_via_sdk(quiet=True)
        self._refresh_broker_status(extra="\n".join(success_lines))
        self._refresh_submission_focus()
        QMessageBox.information(self, "下单完成", "\n".join(item["display_text"] for item in normalized_results))

