def _qh_refresh_login_status(self: QuantHunterWindow) -> None:
    if not hasattr(self, "login_status_text"):
        return
    profile = self.current_broker_profile() if "account_name" in getattr(self, "broker_inputs", {}) else self.state.broker_profile
    channel_text = self.auth_channel_combo.currentText() if hasattr(self, "auth_channel_combo") else "东方财富"
    channel_key = str(self.auth_channel_combo.currentData() or "") if hasattr(self, "auth_channel_combo") else ""
    account_name = self.login_inputs.get("account_name").text().strip() if "account_name" in getattr(self, "login_inputs", {}) else ""
    username = self.login_inputs.get("username").text().strip() if "username" in getattr(self, "login_inputs", {}) else ""
    account_id = self.login_inputs.get("account_id").text().strip() if "account_id" in getattr(self, "login_inputs", {}) else ""
    strategy_id = self.login_inputs.get("strategy_id").text().strip() if "strategy_id" in getattr(self, "login_inputs", {}) else ""
    sdk_module = self.login_inputs.get("sdk_module").text().strip() if "sdk_module" in getattr(self, "login_inputs", {}) else ""
    bridge_python = self.login_inputs.get("sdk_python_path").text().strip() if "sdk_python_path" in getattr(self, "login_inputs", {}) else ""
    token_ready = "已填写" if "token" in getattr(self, "login_inputs", {}) and self.login_inputs["token"].text().strip() else "未填写"
    missing_fields = []
    if not account_name:
        missing_fields.append("账户名称")
    if not username:
        missing_fields.append("登录账号")
    if not account_id:
        missing_fields.append("账户 ID")
    if not strategy_id:
        missing_fields.append("策略 ID")
    if token_ready != "已填写":
        missing_fields.append("SDK Token")
    if channel_key in {"gm", "custom"}:
        if not sdk_module:
            missing_fields.append("SDK 模块")
        if not bridge_python:
            missing_fields.append("Bridge Python")
    mode_text = self._display_mode(getattr(profile, "mode", "") or "manual") if hasattr(self, "_display_mode") else (getattr(profile, "mode", "") or "manual")
    readiness = "可进入校验" if not missing_fields else "待补齐接入参数"
    lines = [
        "登录与通道说明",
        "",
        f"- 当前通道：{channel_text}",
        f"- 账户名称：{account_name or '未填写'}",
        f"- 登录账号：{username or '未填写'}",
        f"- 账户 ID：{account_id or '未填写'}",
        f"- 策略 ID：{strategy_id or '未填写'}",
        f"- 委托模式：{mode_text or '未配置'}",
        f"- SDK Token：{token_ready}",
        f"- SDK 模块：{sdk_module or '未填写'}",
        f"- Bridge Python：{bridge_python or '未填写'}",
        f"- 接入准备度：{readiness}",
        "",
        "接入原则",
        "- 这里维护东方财富、GM 或自定义通道的登录参数，方便后续扩展。",
        "- 程序只保存配置与工作流状态，不绕过券商侧登录校验和风控校验。",
        "- 真实下单仍保持人工确认优先，适合先做盘中决策、委托准备和执行复盘。",
    ]
    if missing_fields:
        lines.extend(["", f"下一步：优先补齐 {', '.join(missing_fields)}，再点“校验接入”进入执行中控。"])
    else:
        lines.extend(["", "下一步：先点“校验接入”，确认桥接环境与保护项，再进入机会池和执行中控链路。"])
    self._set_plain_text_if_changed(self.login_status_text, "\n".join(lines))
    if hasattr(self, "auth_status_banner"):
        banner_text = (
            f"接入状态：{channel_text} | 待补 {', '.join(missing_fields[:3])} | 下一步：补齐后再校验接入。"
            if missing_fields
            else f"接入状态：{channel_text} | 参数已齐 | 下一步：校验接入后联动机会池与交易。"
        )
        self._set_label_text_if_changed(self.auth_status_banner, banner_text)
    if hasattr(self, "auth_desk_summary_subtitle"):
        self._set_label_text_if_changed(
            self.auth_desk_summary_subtitle,
            focus_strip_subtitle(
                "参数未齐" if missing_fields else "接入参数已齐",
                ", ".join(missing_fields[:3]) if missing_fields else f"{channel_text} / {mode_text or '未填写'}",
                "补齐后校验接入" if missing_fields else "执行接入校验并联动机会池",
            ),
        )
    if hasattr(self, "auth_summary_metric_labels"):
        bridge_ready = bool(bridge_python) if channel_key in {"gm", "custom"} else True
        summary_values = {
            "channel": (channel_text, f"模式 {mode_text or '未填写'}"),
            "credential": (
                "待补参数" if missing_fields else "参数已齐",
                " / ".join(missing_fields[:3]) if missing_fields else "账号、账户 ID、策略 ID 与 Token 已齐",
            ),
            "bridge": (
                "已就绪" if bridge_ready else "待补 Bridge",
                (
                    f"{sdk_module or '未填写'} | {bridge_python or '等待 Bridge Python'}"
                    if channel_key in {"gm", "custom"}
                    else "东方财富默认可直接走本地接入"
                ),
            ),
            "next": (
                "校验接入" if not missing_fields else "先补参数",
                "参数齐备后先校验，再联动机会池与交易" if not missing_fields else "先补齐缺口，再做接入校验",
            ),
        }
        for key, (value, accent) in summary_values.items():
            if key in self.auth_summary_metric_labels:
                self._set_label_text_if_changed(self.auth_summary_metric_labels[key], value)
            if hasattr(self, "auth_summary_metric_accents") and key in self.auth_summary_metric_accents:
                self._set_label_text_if_changed(self.auth_summary_metric_accents[key], accent)
    save_button = getattr(self, "auth_save_button", None)
    validate_button = getattr(self, "auth_validate_button", None)
    broker_button = getattr(self, "auth_to_broker_button", None)
    recommend_button = getattr(self, "auth_to_recommend_button", None)
    missing_preview = " / ".join(missing_fields[:3]) if missing_fields else ""
    can_validate = not missing_fields
    if isinstance(save_button, QPushButton):
        QuantHunterWindow._set_widget_enabled_if_changed(self, save_button, True)
        if hasattr(self, "_set_button_role"):
            self._set_button_role(save_button, "tonal" if can_validate else "accent")
        save_tip = (
            "先保存当前接入参数，避免校验前丢失刚刚修改的内容。"
            if can_validate
            else f"建议先保存当前输入，再继续补齐：{missing_preview}。"
        )
        self._set_label_text_if_changed(save_button, "保存接入", tooltip=save_tip)
    if isinstance(validate_button, QPushButton):
        QuantHunterWindow._set_widget_enabled_if_changed(self, validate_button, can_validate)
        if hasattr(self, "_set_button_role"):
            self._set_button_role(validate_button, "accent" if can_validate else "tonal")
        validate_tip = (
            f"参数已齐，先校验 {channel_text} 接入，再继续联动机会池与交易。"
            if can_validate
            else f"还缺 {missing_preview}，补齐后才能执行接入校验。"
        )
        self._set_label_text_if_changed(validate_button, "校验接入", tooltip=validate_tip)
    if isinstance(broker_button, QPushButton):
        QuantHunterWindow._set_widget_enabled_if_changed(self, broker_button, True)
        broker_tip = (
            "参数已齐，可以先去交易看执行链路；更稳妥的顺序仍是先点校验接入。"
            if can_validate
            else "可以先浏览交易链路，但真实联动前建议先补齐参数并校验接入。"
        )
        self._set_label_text_if_changed(broker_button, "去交易", tooltip=broker_tip)
    if isinstance(recommend_button, QPushButton):
        QuantHunterWindow._set_widget_enabled_if_changed(self, recommend_button, True)
        recommend_tip = (
            "参数已齐，可以先看机会池；更稳妥的顺序仍是先点校验接入。"
            if can_validate
            else "可以先浏览机会池，但真实联动前建议先补齐参数并校验接入。"
        )
        self._set_label_text_if_changed(recommend_button, "看机会", tooltip=recommend_tip)
    if hasattr(self, "overview_playbook_text"):
        if missing_fields:
            self._set_plain_text_if_changed(
                self.overview_playbook_text,
                "\n".join(
                    [
                        "今天先做什么",
                        f"1. 先补齐接入信息：{', '.join(missing_fields)}",
                        "2. 再刷新市场和机会池，确认主线与机会分层。",
                        "3. 最后进入执行中控复核委托、风险灯和仓位。",
                    ]
                ),
            )
        else:
            self._set_plain_text_if_changed(
                self.overview_playbook_text,
                "\n".join(
                    [
                        "今天先做什么",
                        "1. 先刷新市场，确认主线、风险灯和当前焦点标的。",
                        "2. 再看机会池的置信度、执行准备和失效条件。",
                        "3. 最后进入执行中控复核委托、仓位与回执。",
                    ]
                ),
            )
    if hasattr(self, "_refresh_auth_capability_overview_v1"):
        self._refresh_auth_capability_overview_v1()


