def _qh_broker_submission_focus_signature_v55(
    *,
    symbol: str,
    stock_id: str,
    stock_name: str,
    record,
    recommendation,
    intent,
    price_brief: str,
    news_lines: list[str],
    channel_text: str,
) -> tuple:
    recommendation = recommendation or None
    intent = intent or None
    return (
        str(symbol or ""),
        str(stock_id or ""),
        str(stock_name or ""),
        str(record.get("timestamp", "") or ""),
        str(record.get("order_status", "") or ""),
        str(record.get("fill_status", "") or ""),
        str(record.get("failure_reason", "") or ""),
        str(record.get("message", "") or ""),
        str(record.get("side", "") or ""),
        str(record.get("quantity", "") or ""),
        str(record.get("price", "") or ""),
        str(getattr(recommendation, "action", "") or ""),
        str(getattr(recommendation, "mainline_flow_signal", "") or ""),
        str(getattr(recommendation, "mainline_stage", "") or ""),
        str(getattr(recommendation, "mainline_tag", "") or getattr(recommendation, "theme_name", "") or ""),
        str(getattr(recommendation, "mainline_role", "") or ""),
        str(getattr(recommendation, "entry_price", "") or ""),
        str(getattr(recommendation, "stop_price", "") or ""),
        str(getattr(recommendation, "target_price", "") or ""),
        str(getattr(intent, "symbol", "") or ""),
        str(getattr(intent, "side", "") or ""),
        str(getattr(intent, "status", "") or ""),
        str(price_brief or ""),
        tuple(str(line or "") for line in news_lines or []),
        str(channel_text or ""),
    )


def _qh_focus_symbol_in_broker_workspace(self: QuantHunterWindow, symbol: str) -> None:
    if not symbol:
        return
    stock_name = self._stock_name_for_symbol(symbol)
    stock_id = self._stock_id_for_symbol(symbol)
    execution_status = str((getattr(self, "execution_status_by_symbol", {}) or {}).get(symbol, "") or "")
    self._queue_symbol_to_watchlist(symbol)
    self._navigate_to_workspace("broker", "orders_table")
    has_scan_rows = bool(getattr(self, "scan_rows", []))
    if has_scan_rows:
        self.generate_order_suggestions()
        order_selected = self._select_order_intent_row_for_symbol(symbol)
        execution_selected = self._select_execution_row_for_symbol(symbol)
        target_widget = _qh_broker_link_target_v40(
            execution_status=execution_status,
            order_selected=bool(order_selected),
            execution_selected=bool(execution_selected),
        )
        banner_text, focus_text = _qh_broker_link_copy_v39(
            stock_name=stock_name,
            stock_id=stock_id,
            symbol=symbol,
            execution_status=execution_status,
            has_scan_rows=True,
            has_linked_records=bool(order_selected or execution_selected),
        )
    else:
        target_widget = "orders_table"
        banner_text, focus_text = _qh_broker_link_copy_v39(
            stock_name=stock_name,
            stock_id=stock_id,
            symbol=symbol,
            execution_status=execution_status,
            has_scan_rows=False,
            has_linked_records=False,
        )
    self._navigate_to_workspace("broker", target_widget, target_widget)
    self._refresh_broker_order_focus()
    self._refresh_submission_focus()
    if hasattr(self, "broker_status_banner"):
        self._set_label_text_if_changed(self.broker_status_banner, banner_text, tooltip=banner_text)
    if hasattr(self, "orders_focus_label"):
        self._set_label_text_if_changed(self.orders_focus_label, focus_text, tooltip=focus_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()


def _qh_detail_route_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    symbol = ""
    selected_intent = self._selected_order_intent() if hasattr(self, "_selected_order_intent") else None
    if selected_intent is not None:
        symbol = str(getattr(selected_intent, "symbol", "") or "")
    if not symbol and hasattr(self, "_explicit_recommendation_focus"):
        focus_recommendation = self._explicit_recommendation_focus()
        symbol = str(getattr(focus_recommendation, "symbol", "") or "") if focus_recommendation is not None else ""
    if not symbol:
        symbol = str(getattr(self, "active_symbol", "") or "")

    recommendation = None
    if hasattr(self, "_explicit_recommendation_focus"):
        focus_recommendation = self._explicit_recommendation_focus()
        if focus_recommendation is not None and str(getattr(focus_recommendation, "symbol", "") or "") == symbol:
            recommendation = focus_recommendation
    if recommendation is None and symbol:
        recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == symbol), None)

    order_intent = selected_intent if selected_intent is not None and str(getattr(selected_intent, "symbol", "") or "") == symbol else None
    if order_intent is None and symbol:
        order_intent = next((item for item in getattr(self, "order_intents", []) if getattr(item, "symbol", "") == symbol), None)

    execution_row = None
    if symbol:
        for attr_name in ("order_submission_records", "submission_records", "execution_records"):
            records = list(getattr(self, attr_name, []) or [])
            execution_row = next(
                (
                    row
                    for row in records
                    if str((row.get("symbol", "") if isinstance(row, dict) else getattr(row, "symbol", "")) or "") == symbol
                ),
                None,
            )
            if execution_row is not None:
                break

    selected_signal = self._selected_detail_signal_snapshot() if hasattr(self, "_selected_detail_signal_snapshot") else None
    latest_signal = selected_signal
    if latest_signal is None and symbol:
        analyses = list(getattr(self, "analyses", []) or [])
        if analyses:
            latest_signal = next(
                (
                    item
                    for item in reversed(analyses)
                    if str(getattr(item, "symbol", "") or "") in {"", symbol}
                    and str(getattr(item, "label", "") or "") != "NONE"
                ),
                None,
            )

    history_summary = self._strategy_history_selected_summary() if hasattr(self, "_strategy_history_selected_summary") else None
    history_trade = self._selected_strategy_history_trade_snapshot() if hasattr(self, "_selected_strategy_history_trade_snapshot") else None
    has_history_context = bool(history_summary is not None or history_trade is not None or getattr(self, "strategy_history_report", None) is not None)

    stock_name = self._stock_name_for_symbol(symbol) if symbol and hasattr(self, "_stock_name_for_symbol") else "--"
    stock_id = self._stock_id_for_symbol(symbol) if symbol and hasattr(self, "_stock_id_for_symbol") else "--"
    return SimpleNamespace(
        symbol=symbol,
        stock_name=stock_name,
        stock_id=stock_id,
        recommendation=recommendation,
        order_intent=order_intent,
        execution_row=execution_row,
        latest_signal=latest_signal,
        has_history_context=has_history_context,
    )


def _qh_detail_to_recommend_status_text_v1(context: SimpleNamespace) -> str:
    if not context.symbol:
        return "推荐状态：已从复盘切到机会池 | 当前焦点票待同步 | 当前结论：继续复核 | 下一步：先锁定一只股票，再回看主线、计划和复盘结论。"
    symbol_brief = f"{context.stock_name} ({context.stock_id})"
    if context.recommendation is not None:
        return f"推荐状态：已从复盘带着 {symbol_brief} 回到机会池 | 计划已同步 | 当前结论：继续复核 | 下一步：继续核对主线、计划价位和下一步动作。"
    if context.latest_signal is not None:
        return f"推荐状态：已从复盘带着 {symbol_brief} 回到机会池 | 信号已同步但计划待补齐 | 当前结论：继续复核 | 下一步：先确认主线、计划价位和动作建议。"
    if context.order_intent is not None or context.execution_row is not None:
        return f"推荐状态：已从复盘带着 {symbol_brief} 回到机会池 | 执行链路已先行 | 当前结论：继续复核 | 下一步：先补齐今天的主线和计划，再回头复核执行是否合理。"
    if context.has_history_context:
        return f"推荐状态：已从复盘带着 {symbol_brief} 回到机会池 | 历史画像已就绪 | 当前结论：继续复核 | 下一步：先把今天的主线和计划补齐，再对照历史画像。"
    return f"推荐状态：已从复盘带着 {symbol_brief} 回到机会池 | 当前计划待同步 | 当前结论：继续复核 | 下一步：先确认主线、计划位和动作建议。"


