def _qh_refresh_detail_workspace_panels_v80(self: QuantHunterWindow) -> None:
    symbol = ""
    order_focus = self._selected_order_intent() if hasattr(self, "_selected_order_intent") else None
    if order_focus is not None:
        symbol = str(getattr(order_focus, "symbol", "") or "")
    if not symbol and hasattr(self, "_explicit_recommendation_focus"):
        focus_recommend = self._explicit_recommendation_focus()
        symbol = str(getattr(focus_recommend, "symbol", "") or "") if focus_recommend is not None else ""
    if not symbol:
        symbol = getattr(self, "active_symbol", "") or ""
    if not symbol:
        refresh_detail_empty_state_runtime(self)
        if hasattr(self, "_refresh_live_workspace_summary_panels"):
            self._refresh_live_workspace_summary_panels()
        if hasattr(self, "_refresh_workspace_focus_banners"):
            self._refresh_workspace_focus_banners()
        return
    _ORIGINAL_QH_REFRESH_DETAIL_WORKSPACE_PANELS_V80(self)


