def _qh_apply_commercial_table_layout_v8(self: QuantHunterWindow) -> None:
    table_specs = TERMINAL_TABLE_LAYOUT_SPECS
    density_profile = self._terminal_density_profile() if hasattr(self, "_terminal_density_profile") else {}
    table_row_scale = float(density_profile.get("table_row_scale", 1.0) or 1.0)
    table_header_scale = float(density_profile.get("table_header_scale", 1.0) or 1.0)
    table_min_height_scale = float(density_profile.get("table_min_height_scale", 1.0) or 1.0)
    table_breakpoint_shift = int(density_profile.get("table_breakpoint_shift", 0) or 0)
    density_mode = str(density_profile.get("mode", DEFAULT_TERMINAL_DENSITY) or DEFAULT_TERMINAL_DENSITY)
    tone_by_attr = {
        "market_pool_table": "overview",
        "leader_table": "overview",
        "daily_pool_table": "recommend",
        "trade_plan_table": "recommend",
        "orders_table": "broker",
        "execution_table": "broker",
        "scan_table": "scanner",
        "summary_table": "scanner",
        "monitor_table": "scanner",
        "board_table": "board",
        "board_monitor_table": "board",
    }

    for attr_name, spec in table_specs.items():
        table = getattr(self, attr_name, None)
        if not isinstance(table, QTableWidget):
            continue

        table.setWordWrap(False)
        table.setTextElideMode(Qt.ElideRight)
        table.setAlternatingRowColors(True)
        table.setShowGrid(False)
        table.setVerticalScrollMode(QAbstractItemView.ScrollPerPixel)
        table.setHorizontalScrollMode(QAbstractItemView.ScrollPerPixel)
        table.setVerticalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        table.setHorizontalScrollBarPolicy(Qt.ScrollBarAsNeeded)
        table.setSelectionBehavior(QAbstractItemView.SelectRows)
        table.setSelectionMode(QAbstractItemView.SingleSelection)
        page_tone = tone_by_attr.get(attr_name, "")
        if page_tone and table.property("pageTone") != page_tone:
            table.setProperty("pageTone", page_tone)
        if "min_height" in spec:
            scaled_min_height = int(round(int(spec["min_height"]) * table_min_height_scale))
            table.setMinimumHeight(max(180, scaled_min_height))
        if isinstance(table, TerminalTableWidget):
            table.set_empty_state(
                str(spec.get("empty_title", "") or ""),
                str(spec.get("empty_hint", "") or ""),
            )

        header = table.horizontalHeader()
        header.setMinimumSectionSize(56)
        header.setStretchLastSection(False)
        header.setDefaultAlignment(Qt.AlignLeft | Qt.AlignVCenter)
        header_height = max(28, int(round(int(spec.get("header_height", 40)) * table_header_scale)))
        header.setFixedHeight(header_height)
        header.setHighlightSections(False)
        row_height = max(28, int(round(int(spec.get("row_height", 44)) * table_row_scale)))
        table.verticalHeader().setDefaultSectionSize(row_height)
        for column in range(table.columnCount()):
            header.setSectionResizeMode(column, QHeaderView.Interactive)
        if attr_name in {"orders_table", "execution_table"}:
            table.setAlternatingRowColors(False)

        viewport_width = int(table.viewport().width() or 0)
        table_width = int(table.width() or 0)
        window_width = int(getattr(self, "width", lambda: 0)() or 0)
        measured_width = max(viewport_width, table_width)
        adjusted_spec = dict(spec)
        compact_breakpoint = int(spec.get("compact_breakpoint", 0) or 0)
        ultra_compact_breakpoint = int(spec.get("ultra_compact_breakpoint", 0) or 0)
        if measured_width <= 0:
            # Before the table receives a real layout width, keep full headers instead of
            # prematurely collapsing into compact labels during startup.
            available_width = max(compact_breakpoint + 1, ultra_compact_breakpoint + 1, 1200)
        else:
            available_width = max(measured_width, window_width if table.isVisible() else 0)
        if compact_breakpoint:
            adjusted_spec["compact_breakpoint"] = compact_breakpoint + table_breakpoint_shift
        if ultra_compact_breakpoint:
            adjusted_spec["ultra_compact_breakpoint"] = ultra_compact_breakpoint + table_breakpoint_shift
        visibility_stage, active_hidden, visibility_priority = terminal_table_hidden_columns(
            adjusted_spec,
            available_width=available_width,
            density_mode=density_mode,
            column_count=table.columnCount(),
        )
        table._qh_visibility_stage_v80 = visibility_stage
        table._qh_visibility_priority_map_v80 = visibility_priority

        for column in range(table.columnCount()):
            table.setColumnHidden(column, column in active_hidden)
        for column, width in spec.get("widths", {}).items():
            if column < table.columnCount() and column not in active_hidden:
                table.setColumnWidth(column, width)

        stretch_column = spec.get("stretch_column")
        if isinstance(stretch_column, int) and stretch_column < table.columnCount():
            header.setSectionResizeMode(stretch_column, QHeaderView.Stretch)

        delegate = TerminalColumnAlignmentDelegate(
            left_columns=set(spec.get("left_columns", [])),
            center_columns=set(spec.get("center_columns", [])),
            right_columns=set(spec.get("right_columns", [])),
            emphasis_columns=set(spec.get("emphasis_columns", [])),
            primary_numeric_columns=set(spec.get("primary_numeric_columns", [])),
            parent=table,
        )
        table.setItemDelegate(delegate)
        table._qh_terminal_alignment_delegate_v79 = delegate

        for column in range(table.columnCount()):
            item = table.horizontalHeaderItem(column)
            if item is None:
                continue
            default_headers = getattr(table, "_qh_default_header_labels_v80", None)
            if not isinstance(default_headers, list) or len(default_headers) != table.columnCount():
                default_headers = [
                    table.horizontalHeaderItem(index).text() if table.horizontalHeaderItem(index) is not None else ""
                    for index in range(table.columnCount())
                ]
                table._qh_default_header_labels_v80 = default_headers
            label = str(spec.get("header_labels", {}).get(column, default_headers[column] if column < len(default_headers) else item.text()) or item.text())
            if visibility_stage in {"watch", "ultra"}:
                label = str(spec.get("ultra_compact_header_labels", {}).get(column, spec.get("compact_header_labels", {}).get(column, label)) or label)
            elif visibility_stage == "compact":
                label = str(spec.get("compact_header_labels", {}).get(column, label) or label)
            if item.text() != label:
                item.setText(label)
            if column in set(spec.get("right_columns", [])):
                item.setTextAlignment(Qt.AlignRight | Qt.AlignVCenter)
            elif column in set(spec.get("center_columns", [])):
                item.setTextAlignment(Qt.AlignCenter)
            else:
                item.setTextAlignment(Qt.AlignLeft | Qt.AlignVCenter)
            tooltip = str(spec.get("header_tooltips", {}).get(column, "") or "")
            if tooltip:
                item.setToolTip(tooltip)


def _qh_apply_workspace_compactness_v33(
    self: QuantHunterWindow,
    *,
    narrow_overview: bool = False,
    compact_height: bool = False,
    ultra_compact_height: bool = False,
) -> None:
    compact_mode = narrow_overview or compact_height
    very_compact = ultra_compact_height or (narrow_overview and compact_height)

    for attr_name, heights in {
        "overview_command_text": (180, 146, 120),
        "overview_execution_text": (180, 146, 120),
        "recommend_dispatch_text": (240, 192, 156),
        "recommend_focus_review_text": (268, 206, 168),
        "recommend_queue_text": (240, 192, 156),
        "recommend_decision_summary_text": (304, 236, 192),
        "daily_pool_text": (220, 146, 118),
        "trade_plan_text": (160, 132, 108),
        "market_pulse_text": (176, 136, 112),
        "position_advice_text": (168, 136, 112),
        "recommend_core_bucket_text": (176, 138, 110),
        "recommend_watch_bucket_text": (176, 138, 110),
        "recommend_risk_bucket_text": (176, 138, 110),
        "strategy_detail_text": (156, 128, 104),
        "strategy_path_text": (184, 138, 112),
        "recommend_review_text": (214, 164, 132),
        "recommend_next_day_text": (214, 164, 132),
        "recommend_ai_review_text": (214, 164, 132),
        "broker_status_text": (252, 196, 154),
        "broker_order_focus_text": (232, 180, 140),
        "broker_recap_text": (176, 136, 112),
        "order_result_text": (176, 144, 120),
    }.items():
        widget = getattr(self, attr_name, None)
        if not isinstance(widget, QTextEdit):
            continue
        full_height, compact_value, ultra_value = heights
        target = ultra_value if very_compact else (compact_value if compact_mode else full_height)
        widget.setMinimumHeight(min(widget.minimumHeight(), target))
        widget.setMaximumHeight(target)

    cockpit_parent = getattr(self, "overview_command_text", None)
    if isinstance(cockpit_parent, QTextEdit):
        cockpit_splitter = cockpit_parent.parentWidget()
        if isinstance(cockpit_splitter, QSplitter) and cockpit_splitter.count() == 2:
            splitter_height = cockpit_splitter.height()
            target_height = max(splitter_height - 4, 72) if splitter_height > 0 else (96 if very_compact else 118)
            for attr_name in ("overview_command_text", "overview_execution_text"):
                widget = getattr(self, attr_name, None)
                if isinstance(widget, QTextEdit):
                    widget.setMinimumHeight(min(widget.minimumHeight(), target_height))
                    widget.setMaximumHeight(target_height)
                    widget.setSizePolicy(QSizePolicy.Expanding, QSizePolicy.Ignored)
            cockpit_splitter.setMinimumHeight(target_height)
            cockpit_splitter.setMaximumHeight(target_height)

    for attr_name, heights in {
        "recommend_status_label": (50, 44, 40),
        "daily_pool_focus_label": (46, 40, 36),
        "trade_plan_focus_label": (46, 40, 36),
        "recommend_stage_status_label": (46, 38, 34),
        "broker_status_banner": (52, 44, 38),
        "orders_focus_label": (46, 40, 36),
    }.items():
        widget = getattr(self, attr_name, None)
        if not isinstance(widget, QLabel):
            continue
        full_height, compact_value, ultra_value = heights
        target = ultra_value if very_compact else (compact_value if compact_mode else full_height)
        widget.setMinimumHeight(target)
        widget.setMaximumHeight(max(target + 16, target))
        widget.setWordWrap(True)

    recommend_stage_container = getattr(self, "recommend_stage_container", None)
    if isinstance(recommend_stage_container, QWidget):
        stage_layout = recommend_stage_container.layout()
        if isinstance(stage_layout, QVBoxLayout):
            stage_layout.setSpacing(8 if compact_mode else 14)

    for splitter_name, compact_sizes, compact_mins, ultra_sizes, ultra_mins in (
        ("recommend_dispatch_splitter", [280, 360, 220], [200, 220, 180], [240, 300, 180], [180, 180, 140]),
        ("recommend_summary_splitter", [320, 560], [220, 260], [280, 480], [180, 220]),
        ("recommend_recap_middle_splitter", [280, 420], [180, 220], [240, 340], [160, 180]),
        ("recommend_recap_bottom_splitter", [280, 420], [180, 220], [240, 340], [160, 180]),
        ("recommend_review_splitter", [320, 320], [220, 220], [280, 280], [180, 180]),
        ("broker_middle_splitter", [340, 560], [220, 240], [300, 440], [180, 180]),
        ("broker_order_focus_splitter", [420, 240], [240, 160], [320, 200], [180, 140]),
    ):
        splitter = getattr(self, splitter_name, None)
        if not isinstance(splitter, QSplitter):
            continue
        if very_compact:
            self._apply_splitter_layout_v19(splitter, ultra_sizes, ultra_mins)
        elif compact_mode:
            self._apply_splitter_layout_v19(splitter, compact_sizes, compact_mins)

    overview_main_splitter = getattr(self, "overview_main_splitter", None)
    if isinstance(overview_main_splitter, QSplitter):
        if very_compact:
            self._apply_splitter_layout_v19(overview_main_splitter, [200, 700, 240], [180, 420, 200])
        elif compact_mode:
            self._apply_splitter_layout_v19(overview_main_splitter, [220, 840, 260], [190, 500, 220])

    for attr_name, min_height in {
        "daily_pool_table": 260 if very_compact else (300 if compact_mode else 360),
        "trade_plan_table": 220 if very_compact else (260 if compact_mode else 320),
        "position_advice_table": 220 if very_compact else (250 if compact_mode else 280),
        "theme_heat_table": 180 if very_compact else (200 if compact_mode else 240),
        "leader_table": 180 if very_compact else (200 if compact_mode else 240),
        "orders_table": 240 if very_compact else (280 if compact_mode else 320),
        "execution_table": 196 if very_compact else (224 if compact_mode else 248),
    }.items():
        table = getattr(self, attr_name, None)
        if isinstance(table, QTableWidget):
            table.setMinimumHeight(min_height)


