def _qh_open_detail_to_overview_v11(self: QuantHunterWindow) -> None:
    context = _qh_detail_route_context_v1(self)
    if context.symbol and hasattr(self, "_focus_symbol_everywhere"):
        self._focus_symbol_everywhere(context.symbol, origin="detail")
    elif context.symbol and context.symbol in getattr(self, "universe_bars", {}):
        self.select_symbol(context.symbol)
    self._navigate_to_workspace("overview", "market_pool_table")
    status_text = _qh_detail_to_overview_status_text_v1(context)
    if hasattr(self, "market_status_label"):
        self._set_label_text_if_changed(self.market_status_label, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "市场总览", "复盘 -> 总览")


