def _qh_selected_recommend_route_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    current = self._current_recommend_focus() if hasattr(self, "_current_recommend_focus") else None
    symbol = str(getattr(current, "symbol", "") or "") if current is not None else ""
    order_intent = next((item for item in getattr(self, "order_intents", []) if getattr(item, "symbol", "") == symbol), None) if symbol else None
    execution_row = None
    if symbol:
        for attr_name in ("order_submission_records", "submission_records", "execution_records"):
            records = list(getattr(self, attr_name, []) or [])
            execution_row = next(
                (
                    row
                    for row in records
                    if str((row.get("symbol", "") if isinstance(row, dict) else getattr(row, "symbol", "")) or "") == symbol
                ),
                None,
            )
            if execution_row is not None:
                break
    return SimpleNamespace(
        current=current,
        symbol=symbol,
        stock_name=str(getattr(current, "stock_name", "") or "--"),
        stock_id=str(getattr(current, "stock_id", "") or "--"),
        recommendation=current,
        order_intent=order_intent,
        execution_row=execution_row,
    )


def _qh_selected_recommend_to_broker_status_text_v1(context: SimpleNamespace) -> str:
    if context.current is None:
        return "交易状态：已从机会池切到执行中控 | 当前焦点票待同步 | 当前结论：继续复核 | 下一步：先在机会池锁定一只股票，再生成委托建议。"
    symbol_brief = f"{context.stock_name} ({context.stock_id})"
    if context.execution_row is not None:
        return f"交易状态：已从机会池带着 {symbol_brief} 去交易 | 当前已有回执链路 | 当前结论：继续复核 | 下一步：继续盯回执、成交和执行偏差。"
    if context.order_intent is not None:
        return f"交易状态：已从机会池带着 {symbol_brief} 去交易 | 委托建议已生成 | 当前结论：继续复核 | 下一步：先核对价格、数量和风控，再决定是否送审或提交。"
    return f"交易状态：已从机会池带着 {symbol_brief} 去交易 | 机会池计划已同步 | 当前结论：继续复核 | 下一步：先把计划补成委托建议。"


def _qh_selected_recommend_to_detail_copy_v1(context: SimpleNamespace) -> str:
    if context.current is None:
        return "复盘结论\n\n当前状态：已从机会池切到复盘 | 当前焦点票待同步。\n下一步：先在机会池锁定一只股票，再进入复盘看信号、执行和结论。"
    symbol_text = f"{context.stock_name} ({context.stock_id} / {context.symbol})"
    if context.execution_row is not None:
        return (
            f"复盘结论：{symbol_text}\n"
            "当前状态：已从机会池带着这只票进入复盘，计划与执行回执都已同步。\n"
            "优先检查：主线是否仍在前排、委托与成交是否偏离计划、复盘结论是否能支撑下一次继续跟踪。\n"
            "下一步：继续对照机会池计划、交易回执和同主线候选，确认这笔票的执行偏差和后续跟踪价值。"
        )
    if context.order_intent is not None:
        return (
            f"复盘结论：{symbol_text}\n"
            "当前状态：已从机会池带着这只票进入复盘，主线计划与委托建议已同步，但回执还没到。\n"
            "优先检查：计划价位、风控边界和为什么准备送审或提交。\n"
            "下一步：先去交易核对价格、数量和风控，再回来补齐执行结果与复盘结论。"
        )
    return (
        f"复盘结论：{symbol_text}\n"
        "当前状态：已从机会池带着这只票进入复盘，主线与计划已同步。\n"
        "优先检查：主线地位、计划价位、动作建议和这只票为什么值得进入复盘研究。\n"
        "下一步：先对照机会池计划，再决定是继续去交易生成委托，还是留在复盘补齐结论。"
    )


