def _qh_auth_route_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    profile = None
    if hasattr(self, "current_broker_profile"):
        try:
            profile = self.current_broker_profile()
        except Exception:
            profile = None
    if profile is None:
        profile = getattr(getattr(self, "state", None), "broker_profile", SimpleNamespace())
    channel_text = self.auth_channel_combo.currentText() if hasattr(self, "auth_channel_combo") else "东方财富"
    mode_value = str(getattr(profile, "mode", "") or "")
    mode_text = self._display_mode(mode_value) if hasattr(self, "_display_mode") else (mode_value or "未填写")
    username = str(getattr(profile, "username", "") or "").strip()
    account_id = str(getattr(profile, "account_id", "") or "").strip()
    strategy_id = str(getattr(profile, "strategy_id", "") or "").strip()
    token_ready = bool(str(getattr(profile, "token", "") or "").strip())
    bridge_python = str(getattr(profile, "sdk_python_path", "") or "").strip()
    sdk_module = str(getattr(profile, "sdk_module", "") or "").strip()
    missing_fields: list[str] = []
    if not username:
        missing_fields.append("账号")
    if not account_id:
        missing_fields.append("账户 ID")
    if not strategy_id:
        missing_fields.append("策略 ID")
    if not token_ready:
        missing_fields.append("SDK Token")
    needs_bridge = channel_text in {"GM", "自定义"}
    if needs_bridge and not bridge_python:
        missing_fields.append("Bridge Python")
    if needs_bridge and not sdk_module:
        missing_fields.append("SDK 模块")
    return SimpleNamespace(
        channel_text=channel_text,
        mode_text=mode_text,
        missing_fields=missing_fields,
        token_ready=token_ready,
        bridge_python=bridge_python,
        sdk_module=sdk_module,
        needs_bridge=needs_bridge,
    )


