def _qh_config_route_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    state = getattr(self, "state", SimpleNamespace())
    risk_key = str(
        self.strategy_risk_profile_combo.currentData()
        if hasattr(self, "strategy_risk_profile_combo") and self.strategy_risk_profile_combo.currentIndex() >= 0
        else getattr(state, "strategy_risk_profile", "standard")
    )
    risk_label = RISK_PROFILE_LABELS.get(risk_key, risk_key)
    workspace_payload = load_strategy_workspace_payload()
    strategies = [dict(item) for item in list(workspace_payload.get("strategies", []) or []) if isinstance(item, dict)]
    strategy_total = len(strategies)
    strategy_json_total = sum(1 for item in strategies if str(item.get("source_type", "") or "catalog").strip().lower() != "script")
    strategy_script_total = sum(1 for item in strategies if str(item.get("source_type", "") or "").strip().lower() == "script")
    provider_key = str(getattr(self, "news_source_provider_key", "") or getattr(state, "news_source_provider", "csv") or "csv")
    descriptor = get_news_source_descriptor(provider_key)
    provider_text = descriptor.label + ("（预留）" if not descriptor.available else "")
    news_status = str(getattr(self, "news_source_status", "") or ("等待选择消息源" if descriptor.requires_path else "可直接载入"))
    ai_config = self._current_ai_review_config() if hasattr(self, "_current_ai_review_config") else SimpleNamespace(model="--", api_key=getattr(state, "ai_review_api_key", ""))
    ai_model = str(getattr(ai_config, "model", "") or "--")
    ai_key_ready = bool(str(getattr(ai_config, "api_key", "") or "").strip())
    current_strategy = self._strategy_catalog_current_name() if hasattr(self, "_strategy_catalog_current_name") else ""
    return SimpleNamespace(
        risk_label=risk_label,
        strategy_total=strategy_total,
        strategy_json_total=strategy_json_total,
        strategy_script_total=strategy_script_total,
        provider_text=provider_text,
        news_status=news_status,
        ai_model=ai_model,
        ai_key_ready=ai_key_ready,
        current_strategy=current_strategy,
    )


