def _qh_broker_action_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    profile = self.current_broker_profile() if hasattr(self, "current_broker_profile") else SimpleNamespace()
    symbol = str(getattr(self, "active_symbol", "") or "").strip()
    if not symbol:
        current_intents = list(getattr(self, "order_intents", []) or [])
        if current_intents:
            symbol = str(getattr(current_intents[0], "symbol", "") or "").strip()
    stock_name = self._stock_name_for_symbol(symbol) if symbol and hasattr(self, "_stock_name_for_symbol") else "--"
    stock_id = self._stock_id_for_symbol(symbol) if symbol and hasattr(self, "_stock_id_for_symbol") else "--"
    mode_text = self._display_mode(str(getattr(profile, "mode", "") or "")) if hasattr(self, "_display_mode") else str(getattr(profile, "mode", "") or "")
    export_dir = str(getattr(profile, "export_dir", "") or "").strip()
    account_id = str(getattr(profile, "account_id", "") or "").strip()
    return SimpleNamespace(
        symbol=symbol,
        stock_name=stock_name,
        stock_id=stock_id,
        mode_text=mode_text or "--",
        export_dir=export_dir,
        account_id=account_id or "--",
    )


