def _qh_paper_action_status_text_v1(
    *,
    action: str,
    state: PaperTradingState,
    artifacts=None,
) -> str:
    positions = len(list(getattr(state, "positions", []) or []))
    ledger = len(list(getattr(state, "ledger", []) or []))
    auto_text = "开启" if bool(getattr(state, "auto_run", False)) else "关闭"
    cash_text = float(getattr(state, "cash", 0.0) or getattr(state, "initial_cash", 0.0) or 0.0)
    equity_text = float(getattr(state, "total_equity", 0.0) or cash_text or 0.0)
    if action == "initialize":
        return (
            f"实验台状态：模拟盘已初始化 | 当前权益 {equity_text:,.0f} / 现金 {cash_text:,.0f} | 自动巡航 {auto_text} | 当前结论：实验底稿已建立 | "
            "下一步：先核对初始参数和预算，再执行一轮模拟盘。"
        )
    if action == "reset":
        return (
            f"实验台状态：模拟盘已重置 | 当前权益 {equity_text:,.0f} / 现金 {cash_text:,.0f} | 持仓 {positions} / 交割 {ledger} | 当前结论：实验账户已清空 | "
            "下一步：先确认参数，再执行一轮或重新建立样本。"
        )
    if action == "run":
        latest_note = str(getattr(state, "last_strategy_note", "") or "等待下一轮").strip()
        return (
            f"实验台状态：AI 模拟盘已完成一轮执行 | 持仓 {positions} / 交割 {ledger} | {latest_note} | 当前结论：实验结果已更新 | "
            "下一步：先看持仓、交割和实验洞察，再决定是否回机会池或执行中控。"
        )
    markdown_name = Path(str(getattr(artifacts, "markdown_path", "") or "")).name
    csv_name = Path(str(getattr(artifacts, "csv_path", "") or "")).name
    json_name = Path(str(getattr(artifacts, "json_path", "") or "")).name
    return (
        f"实验台状态：已导出模拟盘报告 | 持仓 {positions} / 交割 {ledger} | 产物：{markdown_name} / {csv_name} / {json_name} | 当前结论：实验报告已生成 | "
        "下一步：先核对收益、交割和执行画像，再决定是否复用到真实交易。"
    )


