def _qh_qt_object_alive_v1(obj) -> bool:
    if obj is None:
        return False
    try:
        return bool(_shiboken_is_valid(obj))
    except Exception:
        return False


def _qh_window_ready_for_ui_v1(self: QuantHunterWindow) -> bool:
    if not _qh_qt_object_alive_v1(self):
        return False
    return not bool(getattr(self, "_qh_shutdown_started_v1", False))


def _qh_schedule_window_callback_v1(self: QuantHunterWindow, delay_ms: int, callback) -> None:
    def _runner() -> None:
        if not _qh_window_ready_for_ui_v1(self):
            return
        try:
            callback()
        except RuntimeError:
            return

    QTimer.singleShot(int(delay_ms or 0), _runner)


def _qh_stop_child_timers_v1(self: QuantHunterWindow) -> None:
    if not _qh_qt_object_alive_v1(self):
        return
    try:
        timers = list(self.findChildren(QTimer))
    except RuntimeError:
        return
    for timer in timers:
        if not _qh_qt_object_alive_v1(timer):
            continue
        try:
            timer.stop()
        except RuntimeError:
            continue


def _qh_market_chart_dialog_context_v1(self: QuantHunterWindow) -> SimpleNamespace:
    current_symbol_fn = getattr(self, "_current_market_chart_symbol", None)
    symbol = str(current_symbol_fn() if callable(current_symbol_fn) else "" or "").strip()
    if not symbol:
        symbol = str(getattr(self, "active_symbol", "") or "").strip()
    stock_name = self._stock_name_for_symbol(symbol) if symbol and hasattr(self, "_stock_name_for_symbol") else "--"
    stock_id = self._stock_id_for_symbol(symbol) if symbol and hasattr(self, "_stock_id_for_symbol") else "--"
    preset_key = str(getattr(self, "market_chart_preset", "BALANCED") or "BALANCED")
    preset_label = self._market_chart_preset_label(preset_key) if hasattr(self, "_market_chart_preset_label") else preset_key
    custom_presets = self._normalized_market_chart_custom_presets() if hasattr(self, "_normalized_market_chart_custom_presets") else {}
    annotation_mode = str(getattr(self, "market_strategy_annotation_mode", "FULL") or "FULL")
    annotation_hint_fn = getattr(self, "_market_strategy_annotation_mode_hint", None)
    annotation_label, annotation_hint = (
        annotation_hint_fn(annotation_mode)
        if callable(annotation_hint_fn)
        else ("完整提示", "同时看计划与执行")
    )
    timeframe = self._normalize_market_timeframe() if hasattr(self, "_normalize_market_timeframe") else str(
        getattr(self, "market_timeframe_mode", "日线") or "日线"
    )
    header_label = getattr(self, "market_header_label", None)
    header_text = str(header_label.text() if hasattr(header_label, "text") else "" or "").strip()
    return SimpleNamespace(
        symbol=symbol,
        stock_name=stock_name,
        stock_id=stock_id,
        preset_label=str(preset_label or "均衡盯盘"),
        custom_count=len(dict(custom_presets or {})),
        annotation_label=str(annotation_label or "完整提示"),
        annotation_hint=str(annotation_hint or "同时看计划与执行"),
        timeframe=str(timeframe or "日线"),
        header_text=header_text,
    )


