def _qh_scanner_focus_symbol_v1(self: QuantHunterWindow) -> str:
    for attr_name in (
        "_selected_symbol_from_monitor_table",
        "_selected_symbol_from_watchlist",
        "_selected_symbol_from_summary_table",
        "_selected_symbol_from_scan",
    ):
        selector = getattr(self, attr_name, None)
        if callable(selector):
            try:
                value = str(selector() or "").strip()
            except Exception:
                value = ""
            if value:
                return value
    return str(getattr(self, "active_symbol", "") or "")


def _qh_symbol_route_context_v1(self: QuantHunterWindow, symbol: str) -> SimpleNamespace:
    normalized_symbol = str(symbol or "").strip()
    recommendation = next((row for row in getattr(self, "daily_pool_rows", []) if getattr(row, "symbol", "") == normalized_symbol), None) if normalized_symbol else None
    order_intent = next((item for item in getattr(self, "order_intents", []) if getattr(item, "symbol", "") == normalized_symbol), None) if normalized_symbol else None
    execution_row = None
    if normalized_symbol:
        for attr_name in ("order_submission_records", "submission_records", "execution_records"):
            records = list(getattr(self, attr_name, []) or [])
            execution_row = next(
                (
                    row
                    for row in records
                    if str((row.get("symbol", "") if isinstance(row, dict) else getattr(row, "symbol", "")) or "") == normalized_symbol
                ),
                None,
            )
            if execution_row is not None:
                break
    scan_row = next((row for row in getattr(self, "scan_rows", []) if getattr(row, "symbol", "") == normalized_symbol), None) if normalized_symbol else None
    board_candidate = self._board_candidate_snapshot_for_symbol(normalized_symbol) if normalized_symbol and hasattr(self, "_board_candidate_snapshot_for_symbol") else None
    board_monitor = self._board_monitor_snapshot_for_symbol(normalized_symbol) if normalized_symbol and hasattr(self, "_board_monitor_snapshot_for_symbol") else None
    stock_name = self._stock_name_for_symbol(normalized_symbol) if normalized_symbol and hasattr(self, "_stock_name_for_symbol") else "--"
    stock_id = self._stock_id_for_symbol(normalized_symbol) if normalized_symbol and hasattr(self, "_stock_id_for_symbol") else "--"
    return SimpleNamespace(
        symbol=normalized_symbol,
        stock_name=stock_name,
        stock_id=stock_id,
        recommendation=recommendation,
        order_intent=order_intent,
        execution_row=execution_row,
        scan_row=scan_row,
        board_candidate=board_candidate,
        board_monitor=board_monitor,
    )


def _qh_scanner_status_text_v1(context: SimpleNamespace, *, route_key: str) -> str:
    route_copy = {
        "scan": ("扫描榜", "先看信号、评分和触发原因"),
        "watch": ("观察池", "先看是否继续跟踪和留样"),
        "monitor": ("盘中监控区", "先看动作、信号和跨页联动"),
        "summary": ("回测摘要区", "先看回测收益、胜率和是否继续跟踪"),
    }
    destination, next_step = route_copy.get(route_key, ("扫描页", "先看当前扫描链路"))
    if not context.symbol:
        return f"扫描状态：已定位到{destination} | 当前焦点票待同步 | 当前结论：继续复核 | 下一步：先锁定一只股票，再{next_step}。"
    symbol_brief = f"{context.stock_name} ({context.stock_id})"
    if route_key == "monitor" and context.board_monitor is not None:
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 盘中监控已同步 | 当前结论：继续复核 | 下一步：{next_step}。"
    if route_key == "summary":
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 观察与留样链路已同步 | 当前结论：继续复核 | 下一步：{next_step}。"
    if context.execution_row is not None:
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 执行链路已先行 | 当前结论：继续复核 | 下一步：{next_step}，再回头核对计划和委托。"
    if context.order_intent is not None:
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 委托建议已生成 | 当前结论：继续复核 | 下一步：{next_step}，再决定是否继续送审。"
    if context.recommendation is not None:
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 机会池计划已同步 | 当前结论：继续复核 | 下一步：{next_step}，再回看计划是否还成立。"
    if context.scan_row is not None:
        return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 当前扫描信号已同步 | 当前结论：继续复核 | 下一步：{next_step}。"
    return f"扫描状态：已带着 {symbol_brief} 定位到{destination} | 当前焦点已同步 | 当前结论：继续复核 | 下一步：{next_step}。"


