def _qh_open_selected_recommend_in_detail_v21(self: QuantHunterWindow) -> None:
    context = _qh_selected_recommend_route_context_v1(self)
    if context.current is None:
        self._navigate_to_workspace("detail", "metrics_text")
    else:
        self.active_symbol = context.symbol
        if hasattr(self, "open_focus_symbol_in_detail"):
            self.open_focus_symbol_in_detail()
        else:
            if hasattr(self, "_focus_symbol_everywhere"):
                self._focus_symbol_everywhere(context.symbol, origin="recommend")
            self._navigate_to_workspace("detail", "metrics_text")
    detail_text = _qh_selected_recommend_to_detail_copy_v1(context)
    if hasattr(self, "detail_conclusion_text"):
        self._set_plain_text_if_changed(self.detail_conclusion_text, detail_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "复盘页", "机会池 -> 复盘")


def _qh_open_selected_recommend_in_broker_v21(self: QuantHunterWindow) -> None:
    context = _qh_selected_recommend_route_context_v1(self)
    if context.current is None:
        self._navigate_to_workspace("broker", "orders_table")
    else:
        self.active_symbol = context.symbol
        self._focus_symbol_in_broker_workspace(context.symbol)
        if hasattr(self, "_focus_symbol_everywhere"):
            self._focus_symbol_everywhere(context.symbol, origin="recommend")
    status_text = _qh_selected_recommend_to_broker_status_text_v1(context)
    if hasattr(self, "broker_status_banner"):
        self._set_label_text_if_changed(self.broker_status_banner, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "执行中控", "机会池 -> 交易")


QuantHunterWindow.open_selected_recommend_in_detail = _qh_open_selected_recommend_in_detail_v21
QuantHunterWindow.open_selected_recommend_in_broker = _qh_open_selected_recommend_in_broker_v21


def _qh_open_overview_capability_v2(self: QuantHunterWindow, capability_key: str) -> None:
    focus_map = {
        "market": "市场总览",
        "leaders": "主线龙头",
        "news": "消息催化",
        "decision": "买卖决策",
    }
    key = str(capability_key or "").strip()
    focus = focus_map.get(key, "市场总览")
    self.activate_overview_quick_action(focus)
    status_text = _qh_overview_capability_status_text_v1(_qh_overview_route_context_v1(self), route_key=key or "market")
    if hasattr(self, "market_status_label"):
        self._set_label_text_if_changed(self.market_status_label, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "市场总览", f"总览能力卡 -> {key or 'market'}")


def _qh_open_broker_capability_v2(self: QuantHunterWindow, capability_key: str) -> None:
    route_map = {
        "overview": ("broker_summary_box", None),
        "commit": ("orders_table", "orders_table"),
        "posttrade": ("execution_table", "execution_table"),
        "setup": ("broker_setup_drawer", None),
    }
    key = str(capability_key or "").strip()
    target, select_row = route_map.get(key, ("broker_summary_box", None))
    self._navigate_to_workspace("broker", target, select_row)
    if key == "commit" and hasattr(self, "_refresh_broker_order_focus"):
        self._refresh_broker_order_focus()
    if key == "posttrade" and hasattr(self, "_refresh_submission_focus"):
        self._refresh_submission_focus()
    status_text = _qh_broker_capability_status_text_v1(_qh_detail_route_context_v1(self), route_key=key or "overview")
    if hasattr(self, "broker_status_banner"):
        self._set_label_text_if_changed(self.broker_status_banner, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "执行中控", f"交易能力卡 -> {key or 'overview'}")


