def _qh_open_auth_capability_v2(self: QuantHunterWindow, capability_key: str) -> None:
    key = str(capability_key or "").strip()
    context = _qh_auth_route_context_v1(self)
    if key == "next":
        self._navigate_to_workspace("recommend", "daily_pool_table", "daily_pool_table")
        status_text = _qh_auth_next_status_text_v1(context)
        if hasattr(self, "recommend_status_label"):
            self._set_label_text_if_changed(self.recommend_status_label, status_text, tooltip=status_text)
        if hasattr(self, "_refresh_live_workspace_summary_panels"):
            self._refresh_live_workspace_summary_panels()
        if hasattr(self, "_refresh_workspace_focus_banners"):
            self._refresh_workspace_focus_banners()
        _qh_emit_route_feedback_v1(self, "机会池", "接入中心 -> 机会池")
        return
    route_map = {
        "channel": "auth_form_box",
        "credential": "login_status_text",
        "bridge": "login_status_text",
    }
    target = route_map.get(key, "auth_form_box")
    self._navigate_to_workspace("auth", target)
    status_text = _qh_auth_status_text_v1(context, route_key=key or "channel")
    if hasattr(self, "auth_status_banner"):
        self._set_label_text_if_changed(self.auth_status_banner, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "接入中心", f"接入能力卡 -> {key or 'channel'}")


