def _qh_ensure_watch_workspace_tab_priority_binding_v1(self: QuantHunterWindow) -> None:
    for attr_name in (
        "recommend_workflow_tabs",
        "broker_stage_tabs",
        "scanner_stage_tabs",
        "board_stage_tabs",
        "config_stage_tabs",
    ):
        tab_widget = getattr(self, attr_name, None)
        if not isinstance(tab_widget, QTabWidget):
            continue
        if bool(tab_widget.property("_qh_watch_priority_bound_v1")):
            continue
        tab_widget.currentChanged.connect(
            lambda _index, widget=tab_widget: _qh_mark_watch_workspace_tab_priority_user_locked_v1(self, widget)
        )
        tab_widget.setProperty("_qh_watch_priority_bound_v1", True)


def _qh_apply_watch_workspace_tab_priority_v1(self: QuantHunterWindow) -> None:
    if str(getattr(self, "current_density", "compact") or "compact").strip().lower() != "watch":
        return
    _qh_ensure_watch_workspace_tab_priority_binding_v1(self)

    pending_orders = len(getattr(self, "order_intents", []) or [])
    submitted_orders = len(getattr(self, "order_submission_records", []) or [])
    scan_count = getattr(getattr(self, "scan_table", None), "rowCount", lambda: 0)()
    summary_count = getattr(getattr(self, "summary_table", None), "rowCount", lambda: 0)()
    monitor_count = getattr(getattr(self, "monitor_table", None), "rowCount", lambda: 0)()
    board_monitor_count = getattr(getattr(self, "board_monitor_table", None), "rowCount", lambda: 0)()
    watch_count = getattr(getattr(self, "watchlist_widget", None), "count", lambda: 0)()

    target_indexes = {
        "recommend_workflow_tabs": 1 if getattr(self, "daily_pool_rows", []) else 0,
        "broker_stage_tabs": 1 if pending_orders else (2 if submitted_orders else 0),
        "scanner_stage_tabs": 2 if monitor_count else (1 if (watch_count or summary_count) else (0 if scan_count else 0)),
        "board_stage_tabs": 1 if board_monitor_count else 0,
        "config_stage_tabs": 1,
    }

    self._qh_setting_watch_workspace_tab_priority_v1 = True
    try:
        for attr_name, target_index in target_indexes.items():
            tab_widget = getattr(self, attr_name, None)
            if not isinstance(tab_widget, QTabWidget):
                continue
            if bool(tab_widget.property("_qh_watch_priority_user_locked_v1")):
                continue
            if 0 <= int(target_index) < tab_widget.count() and tab_widget.currentIndex() != int(target_index):
                tab_widget.setCurrentIndex(int(target_index))
    finally:
        self._qh_setting_watch_workspace_tab_priority_v1 = False


def _qh_apply_overview_tab_priority_v60(self: QuantHunterWindow, *, compact: bool) -> None:
    if not compact:
        return
    _qh_ensure_overview_tab_priority_binding_v60(self)
    recommendation = None
    if hasattr(self, "_explicit_recommendation_focus"):
        recommendation = self._explicit_recommendation_focus()
    if recommendation is None and hasattr(self, "_selected_daily_pool_recommendation"):
        recommendation = self._selected_daily_pool_recommendation()
    intent = self._selected_order_intent() if hasattr(self, "_selected_order_intent") else None
    side = str(getattr(intent, "side", "") or getattr(recommendation, "action", "") or "").upper()
    blockers = list((getattr(self, "last_broker_execution_summary", {}) or {}).get("blockers", []))
    warnings = list((getattr(self, "last_broker_execution_summary", {}) or {}).get("warnings", []))
    pending_orders = len(getattr(self, "order_intents", []) or [])
    symbol = str(getattr(intent, "symbol", "") or getattr(recommendation, "symbol", "") or "")
    symbol_news = list((getattr(self, "news_catalysts", {}) or {}).get(symbol, []) or []) if symbol else []
    has_news = bool(symbol_news)
    buy_like = side in {"BUY", "ADD"} or str(getattr(recommendation, "action", "") or "").upper() == "BUY"
    risk_like = side in {"SELL", "REDUCE"} or bool(blockers)

    target_indexes = {
        "right_intel_tabs": 2 if (risk_like or pending_orders or buy_like or warnings) else 0,
        "overview_primary_chart_tabs": 1 if (pending_orders or buy_like or risk_like) else 0,
        "overview_mini_chart_tabs": 2 if risk_like else (1 if (pending_orders or buy_like) else 0),
        "overview_chart_controls_tabs": 1 if (pending_orders or buy_like or risk_like) else 0,
    }

    self._qh_setting_overview_tab_priority_v60 = True
    try:
        for attr_name, target_index in target_indexes.items():
            tab_widget = getattr(self, attr_name, None)
            if not isinstance(tab_widget, QTabWidget):
                continue
            if bool(tab_widget.property("_qh_priority_user_locked_v60")):
                continue
            if 0 <= int(target_index) < tab_widget.count() and tab_widget.currentIndex() != int(target_index):
                tab_widget.setCurrentIndex(int(target_index))
    finally:
        self._qh_setting_overview_tab_priority_v60 = False


def _qh_run_scheduled_layout_polish_v19(self: QuantHunterWindow) -> None:
    self._qh_layout_polish_due_v19 = None
    self._apply_layout_polish_v19()


def _qh_schedule_layout_polish_v19(self: QuantHunterWindow, delays: tuple[int, ...] = (0, 80, 220)) -> None:
    normalized_delays = [max(int(delay), 0) for delay in delays] or [0]
    requested_delay = min(normalized_delays)
    last_applied = float(getattr(self, "_qh_last_layout_polish_perf_v19", 0.0) or 0.0)
    now = time_module.perf_counter()
    if requested_delay == 0 and now - last_applied < 0.18:
        requested_delay = 180

    if not hasattr(self, "_qh_layout_polish_timer_v19"):
        timer = QTimer(self)
        timer.setSingleShot(True)
        timer.timeout.connect(self._run_scheduled_layout_polish_v19)
        self._qh_layout_polish_timer_v19 = timer

    timer = self._qh_layout_polish_timer_v19
    due_at = now + (requested_delay / 1000.0)
    existing_due = getattr(self, "_qh_layout_polish_due_v19", None)
    if timer.isActive() and existing_due is not None and existing_due <= due_at + 1e-6:
        return
    timer.stop()
    self._qh_layout_polish_due_v19 = due_at
    timer.start(requested_delay)


def _qh_schedule_tab_layout_polish_v20(self: QuantHunterWindow, workspace_key: str = "") -> None:
    delay = 80 if workspace_key in {"recommend", "broker", "detail", "scanner", "board", "overview"} else 120
    self._schedule_layout_polish_v19((delay,))


