def _qh_shell_workflow_status_target_v2(workspace_key: str, widget_name: str) -> str:
    if workspace_key == "overview":
        return "market_status_label"
    if workspace_key == "recommend":
        return "recommend_status_label"
    if workspace_key == "broker":
        return "broker_status_banner"
    if workspace_key == "paper":
        return "paper_trading_focus_label"
    return ""


def _qh_shell_workflow_status_text_v2(workspace_key: str, widget_name: str, note: str) -> str:
    destination = {
        ("overview", "market_pool_table"): "市场总览",
        ("recommend", "daily_pool_table"): "机会池",
        ("recommend", "trade_plan_table"): "交易计划区",
        ("broker", "orders_table"): "交易页",
        ("broker", "execution_table"): "回执区",
        ("paper", "paper_positions_table"): "实验持仓区",
        ("paper", "paper_strategy_table"): "实验分析区",
    }.get((workspace_key, widget_name), widget_name or workspace_key)
    prefix = {
        "overview": "总览状态",
        "recommend": "推荐状态",
        "broker": "交易状态",
        "paper": "模拟盘联动",
    }.get(workspace_key, "当前状态")
    return f"{prefix}：已从流程条定位到{destination} | 当前结论：继续复核 | 下一步：{note or '继续推进当前流程'}。"


def _qh_open_shell_workflow_stage_v43(self: QuantHunterWindow, stage_key: str) -> None:
    trade_plan = getattr(self, "current_trade_plan", None)
    trade_decisions = list(getattr(trade_plan, "decisions", []) or [])
    paper_state = getattr(self, "paper_trading_state", getattr(getattr(self, "state", None), "paper_trading_state", PaperTradingState()))
    paper_analytics = summarize_paper_trading_performance(paper_state)
    current_workspace_getter = getattr(self, "_current_workspace_key_v42", None)
    current_workspace_key = current_workspace_getter() if callable(current_workspace_getter) else "overview"
    specs, _ = _qh_shell_workflow_stage_specs_v42(
        current_workspace_key=current_workspace_key,
        pool_count=len(getattr(self, "daily_pool_rows", []) or []),
        trade_decisions_count=len(trade_decisions),
        pending_orders=len(getattr(self, "order_intents", []) or []),
        submitted_orders=len(getattr(self, "order_submission_records", []) or []),
        paper_enabled=bool(getattr(paper_state, "enabled", False)),
        paper_closed_trades=int(paper_analytics.get("closed_trade_count", 0) or 0),
        paper_position_count=len(getattr(paper_state, "positions", []) or []),
    )
    route = next((item for item in specs if item["key"] == stage_key), None)
    _ORIGINAL_QH_OPEN_SHELL_WORKFLOW_STAGE_V2(self, stage_key)
    if route is None:
        return
    label_name = _qh_shell_workflow_status_target_v2(str(route.get("workspace", "")), str(route.get("widget", "")))
    status_text = _qh_shell_workflow_status_text_v2(str(route.get("workspace", "")), str(route.get("widget", "")), str(route.get("note", "") or ""))
    label = getattr(self, label_name, None) if label_name else None
    if label is not None and hasattr(self, "_set_label_text_if_changed"):
        self._set_label_text_if_changed(label, status_text, tooltip=status_text)
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    _qh_emit_route_feedback_v1(self, "流程", f"流程条 -> {stage_key}")


QuantHunterWindow._open_shell_workflow_stage = _qh_open_shell_workflow_stage_v43


