def _qh_measure_recommend_decision_summary_text_height_v77(text_widget: QTextEdit) -> int:
    width = max(
        240,
        int(getattr(text_widget.viewport(), "width", lambda: 0)() or 0),
        max(0, int(getattr(text_widget, "width", lambda: 0)() or 0) - 24),
    )
    document = QTextDocument()
    document.setDefaultFont(text_widget.font())
    option = document.defaultTextOption()
    option.setWrapMode(QTextOption.WrapAtWordBoundaryOrAnywhere)
    document.setDefaultTextOption(option)
    document.setDocumentMargin(text_widget.document().documentMargin())
    document.setPlainText(text_widget.toPlainText())
    document.setTextWidth(float(width))
    document.adjustSize()
    return max(0, int(document.size().height()))


def _qh_parent_group_box_v77(widget: QWidget | None) -> QGroupBox | None:
    parent = widget.parentWidget() if isinstance(widget, QWidget) else None
    while parent is not None:
        if isinstance(parent, QGroupBox):
            return parent
        parent = parent.parentWidget()
    return None


def _qh_sync_recommend_decision_summary_geometry_v77(self: QuantHunterWindow) -> None:
    box = getattr(self, "recommend_decision_summary_box", None)
    text_widget = getattr(self, "recommend_decision_summary_text", None)
    label = getattr(self, "recommend_decision_summary_label", None)
    if not isinstance(box, QGroupBox) or not isinstance(text_widget, QTextEdit):
        return

    watch_density = str(getattr(self, "current_density", "compact") or "compact").strip().lower() == "watch"
    compact_density = str(getattr(self, "current_density", "compact") or "compact").strip().lower() == "compact"
    text_floor = max(int(text_widget.property("_qh_watch_min_height_v1") or 0), 280) if watch_density else 220
    measured_height = _qh_measure_recommend_decision_summary_text_height_v77(text_widget)
    text_target = max(text_floor, measured_height + (36 if compact_density and not watch_density else 42))
    text_widget.setMinimumHeight(text_target)
    text_widget.setMaximumHeight(16777215 if watch_density else text_target)
    text_widget.updateGeometry()

    layout = box.layout()
    margins = layout.contentsMargins() if isinstance(layout, (QVBoxLayout, QHBoxLayout, QGridLayout)) else QMargins(12, 12, 12, 10)
    spacing = layout.spacing() if isinstance(layout, (QVBoxLayout, QHBoxLayout, QGridLayout)) else 8
    label_height = max(label.height(), label.sizeHint().height(), 42) if isinstance(label, QLabel) else 0
    buttons = [
        button
        for button in (
            getattr(self, "recommend_push_focus_button", None),
            getattr(self, "recommend_detail_focus_button", None),
            getattr(self, "recommend_broker_focus_button", None),
        )
        if isinstance(button, QPushButton)
    ]
    button_height = max((max(button.height(), button.sizeHint().height(), 38) for button in buttons), default=38)
    box_target = margins.top() + margins.bottom() + label_height + text_target + button_height + max(12, spacing * 2) + 12
    box_floor = 356 if compact_density and not watch_density else (408 if watch_density else 344)
    box_target = max(box_floor, box_target)
    box.setMinimumHeight(box_target)
    box.setMaximumHeight(16777215 if watch_density else box_target)
    box.updateGeometry()


