    text_target = max(text_floor, measured_height + (22 if compact_density and not watch_density else 26))
    text_widget.setMinimumHeight(text_target)
    text_widget.setMaximumHeight(16777215 if watch_density else text_target)
    text_widget.updateGeometry()

    layout = box.layout()
    margins = layout.contentsMargins() if isinstance(layout, (QVBoxLayout, QHBoxLayout, QGridLayout)) else QMargins(12, 12, 12, 12)
    spacing = layout.spacing() if isinstance(layout, (QVBoxLayout, QHBoxLayout, QGridLayout)) else 10
    buttons = [
        button
        for button in (
            getattr(self, "recommend_news_source_button", None),
            getattr(self, "recommend_news_detail_button", None),
            getattr(self, "recommend_ai_review_button", None),
        )
        if isinstance(button, QPushButton)
    ]
    button_height = max((max(button.height(), button.sizeHint().height(), 38) for button in buttons), default=38)
    box_target = margins.top() + margins.bottom() + text_target + button_height + max(12, spacing * 2) + 10
    box_floor = 328 if compact_density and not watch_density else (356 if watch_density else 312)
    box_target = max(box_floor, box_target)
    box.setMinimumHeight(box_target)
