def _qh_add_selected_to_watchlist_v80(self: QuantHunterWindow) -> None:
    symbol = self._selected_symbol_from_scan() if hasattr(self, "_selected_symbol_from_scan") else ""
    if not symbol:
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：请先从扫描榜选中一只股票，再加入观察池。")
        QMessageBox.information(self, "提示", "请先从扫描结果中选择一只股票。")
        return
    stock_name = self._stock_name_for_symbol(symbol) if hasattr(self, "_stock_name_for_symbol") else symbol
    stock_id = self._stock_id_for_symbol(symbol) if hasattr(self, "_stock_id_for_symbol") else "--"
    watchlist = list(getattr(getattr(self, "state", None), "watchlist", []) or [])
    if symbol in watchlist:
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(
                self.scan_summary_label,
                f"扫描状态：{stock_name} ({stock_id}) 已在观察池 | 当前观察 {len(watchlist)} 只 | 下一步：继续看监控或去机会池。",
            )
        if hasattr(self, "_refresh_live_workspace_summary_panels"):
            self._refresh_live_workspace_summary_panels()
        return
    watchlist.append(symbol)
    watchlist.sort()
    self.state.watchlist = watchlist
    if hasattr(self, "_refresh_watchlist"):
        self._refresh_watchlist()
    if hasattr(self, "_select_watchlist_symbol"):
        self._select_watchlist_symbol(symbol)
    if hasattr(self, "_refresh_monitor_summary"):
        self._refresh_monitor_summary(symbol)
    if hasattr(self, "_refresh_scanner_focus_status"):
        self._refresh_scanner_focus_status(symbol)
    if hasattr(self, "_refresh_scanner_summary_cards"):
        self._refresh_scanner_summary_cards(symbol)
    if hasattr(self, "_refresh_scanner_capability_overview_v1"):
        self._refresh_scanner_capability_overview_v1()
    if hasattr(self, "_refresh_scanner_watch_summary_v1"):
        self._refresh_scanner_watch_summary_v1()
    if hasattr(self, "_refresh_scanner_monitor_summary_v1"):
        self._refresh_scanner_monitor_summary_v1(symbol)
    if hasattr(self, "scan_summary_label"):
        self._set_label_text_if_changed(
            self.scan_summary_label,
            f"扫描状态：已把 {stock_name} ({stock_id}) 加入观察池 | 当前观察 {len(watchlist)} 只 | 下一步：继续看监控动作与跨页联动。",
        )
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    self.save_state()


def _qh_remove_selected_from_watchlist_v80(self: QuantHunterWindow) -> None:
    symbol = ""
    if hasattr(self, "_selected_symbol_from_scan"):
        symbol = self._selected_symbol_from_scan() or ""
    if not symbol and hasattr(self, "_selected_symbol_from_watchlist"):
        symbol = self._selected_symbol_from_watchlist() or ""
    if not symbol:
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(self.scan_summary_label, "扫描状态：请先从扫描榜或观察池选中一只股票，再移出观察池。")
        return
    stock_name = self._stock_name_for_symbol(symbol) if hasattr(self, "_stock_name_for_symbol") else symbol
    stock_id = self._stock_id_for_symbol(symbol) if hasattr(self, "_stock_id_for_symbol") else "--"
    watchlist = list(getattr(getattr(self, "state", None), "watchlist", []) or [])
    if symbol not in watchlist:
        if hasattr(self, "scan_summary_label"):
            self._set_label_text_if_changed(
                self.scan_summary_label,
                f"扫描状态：{stock_name} ({stock_id}) 当前不在观察池 | 下一步：可先看扫描榜或继续锁监控焦点。",
            )
        if hasattr(self, "_refresh_live_workspace_summary_panels"):
            self._refresh_live_workspace_summary_panels()
        return
    self.state.watchlist = [item for item in watchlist if item != symbol]
    if hasattr(self, "_refresh_watchlist"):
        self._refresh_watchlist()
    fallback_symbol = self._selected_symbol_from_watchlist() if hasattr(self, "_selected_symbol_from_watchlist") else ""
    if hasattr(self, "_refresh_monitor_summary"):
        self._refresh_monitor_summary(fallback_symbol or "")
    if hasattr(self, "_refresh_scanner_focus_status"):
        self._refresh_scanner_focus_status(fallback_symbol or "")
    if hasattr(self, "_refresh_scanner_summary_cards"):
        self._refresh_scanner_summary_cards(fallback_symbol or "")
    if hasattr(self, "_refresh_scanner_capability_overview_v1"):
        self._refresh_scanner_capability_overview_v1()
    if hasattr(self, "_refresh_scanner_watch_summary_v1"):
        self._refresh_scanner_watch_summary_v1()
    if hasattr(self, "_refresh_scanner_monitor_summary_v1"):
        self._refresh_scanner_monitor_summary_v1(fallback_symbol or "")
    if hasattr(self, "scan_summary_label"):
        self._set_label_text_if_changed(
            self.scan_summary_label,
            f"扫描状态：已把 {stock_name} ({stock_id}) 移出观察池 | 当前观察 {len(self.state.watchlist)} 只 | 下一步：重新确认留样或监控焦点。",
        )
    if hasattr(self, "_refresh_live_workspace_summary_panels"):
        self._refresh_live_workspace_summary_panels()
    if hasattr(self, "_refresh_workspace_focus_banners"):
        self._refresh_workspace_focus_banners()
    self.save_state()


QuantHunterWindow.add_selected_to_watchlist = _qh_add_selected_to_watchlist_v80
QuantHunterWindow.remove_selected_from_watchlist = _qh_remove_selected_from_watchlist_v80


def _build_terminal_palette(theme_key: str = DEFAULT_TERMINAL_THEME) -> QPalette:
    token = _terminal_theme_tokens(theme_key)
    palette = QPalette()
    palette.setColor(QPalette.Window, QColor(token["shell_bg_1"]))
    palette.setColor(QPalette.WindowText, QColor(token["text"]))
    palette.setColor(QPalette.Base, QColor(token["panel_2"]))
    palette.setColor(QPalette.AlternateBase, QColor(token["panel_1"]))
    palette.setColor(QPalette.Text, QColor(token["text"]))
    palette.setColor(QPalette.Button, QColor(token["panel_0"]))
    palette.setColor(QPalette.ButtonText, QColor(token["text"]))
    palette.setColor(QPalette.BrightText, QColor(token["selection_text"]))
    palette.setColor(QPalette.Highlight, QColor(token["selection"]))
    palette.setColor(QPalette.HighlightedText, QColor(token["selection_text"]))
    palette.setColor(QPalette.ToolTipBase, QColor(token["shell_bg_2"]))
    palette.setColor(QPalette.ToolTipText, QColor(token["text"]))
    palette.setColor(QPalette.PlaceholderText, QColor(token["text_soft"]))
    return palette


def main() -> int:
    app = QApplication(sys.argv)
    app.setStyle("Fusion")
    app.setPalette(_build_terminal_palette())
    _install_runtime_cjk_font(app)
    app.setApplicationName("量化猎手")
    splash = StartupSplashWindow()
    splash.show()
    app.processEvents()
    window = QuantHunterWindow(startup_splash=splash)
    splash.attach_owner(window)
    splash.set_progress(window.startup_boot_progress, "主控台已创建，正在接入启动任务...")
    app.processEvents()
    return app.exec()


if __name__ == "__main__":
    raise SystemExit(main())

